import { computed, type ComputedRef, type Ref } from 'vue'
import type { Material } from '@/core/material/Material'
import { REALMS } from '@/data/realms/realm'
import { PILL_FAMILIES } from '@/data/pill/PillFamilies'

// Filter/search/gộp họ cho MaterialBag (economy-fixes-sinks-plan.md §3.2 B4).
// Tách thuần function khỏi component để dễ test và tái dùng.

// Nhóm hiển thị — gộp các category material nhỏ (monster_core/
// spirit_stone/byproduct/other) về "khác". Composable thuần function
// KHÔNG import i18n (core/composables rule) — trả về KEY locale, consumer
// render qua t(key) (pattern useBagFilter → MaterialBagSection).
export type MaterialGroup = 'wood' | 'ore' | 'herb' | 'essence' | 'other'

export const MATERIAL_GROUPS: readonly MaterialGroup[] = ['wood', 'ore', 'herb', 'essence', 'other']

export const GROUP_LABEL_KEYS: Record<MaterialGroup, string> = {
  wood: 'bag.filter.group.wood',
  ore: 'bag.filter.group.ore',
  herb: 'bag.filter.group.herb',
  essence: 'bag.filter.group.essence',
  other: 'bag.filter.group.other',
}

export function groupLabelKey(group: MaterialGroup): string {
  return GROUP_LABEL_KEYS[group]
}

export function toMaterialGroup(category: Material['category']): MaterialGroup {
  if (category === 'wood' || category === 'ore' || category === 'herb' || category === 'essence') {
    return category
  }

  return 'other'
}

const AGE_LABEL_KEYS: Record<string, string> = {
  decade: 'bag.filter.age.decade',
  century: 'bag.filter.age.century',
  millennium: 'bag.filter.age.millennium',
  myriad_year: 'bag.filter.age.myriadYear',
  thuong_co: 'bag.filter.age.thuongCo',
}

export function ageLabelKey(age: string | undefined): string | null {
  return (age && AGE_LABEL_KEYS[age]) || null
}

// gp123 6E (task C2): Gỗ/Quáng dùng CÙNG trục tuổi với Linh Thảo — id
// `<realm>_wood_<age>` / `<realm>_ore_<age>`. Hệ nhãn chất cũ
// (QUALITY_LABEL_KEYS/DATA_QUALITY_LABELS/qualityRank) đã bị xóa cùng
// id phẩm hoang..tien. Vẫn gộp theo "họ" gỗ/quáng resourceKind+realmId,
// badge hiện bậc tuổi cao nhất đang sở hữu.

const REALM_NAME_BY_ID: Readonly<Record<string, string>> = Object.fromEntries(
  REALMS.map((realm) => [realm.id, realm.name]),
)

export function realmLabel(realmId: string): string {
  return REALM_NAME_BY_ID[realmId] ?? realmId
}

/** Normalize tên tìm kiếm: lowercase + bỏ dấu tiếng Việt (NFD strip). */
export function normalizeSearchText(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
}

/** Số niên đại để chọn badge "rộng nhất" — thiếu meta xếp thấp nhất. */
export function ageRank(age: string | undefined): number {
  switch (age) {
    case 'decade': return 0
    case 'century': return 1
    case 'millennium': return 2
    case 'myriad_year': return 3
    case 'thuong_co': return 4
    default: return -1
  }
}

/**
 * Rank biến thể DÙNG CHUNG cho mọi kiểu họ gộp (thảo/gỗ/quáng theo tuổi)
 * — biến thể "cao nhất" làm đại diện icon/tooltip và badge. Material
 * không có age (vd. material legacy) xếp thấp nhất (-1).
 */
export function variantRank(material: Material): number {
  const meta = material.profession

  return meta?.age !== undefined ? ageRank(meta.age) : -1
}

/** Prefix tuổi của tên material ("Thập Niên Linh Mộc" → "Thập Niên") — tên data GỐC vi, dùng để strip prefix khi hiện tên gốc họ. */
function variantLabel(material: Material): string | undefined {
  const meta = material.profession

  return meta?.age !== undefined ? dataAgeLabel(meta.age, material.years) : undefined
}

// ===== Bảng nhãn DATA (vi gốc) — KHÔNG phải UI label: tên material trong
// registry có dạng "<Tuổi> <Tên gốc>" (materials.ts), variantLabel chỉ
// dùng để tách prefix đó. Nhãn HIỂN THỊ cho user đi qua locale key
// (ageLabelKey + t() ở consumer). =====

const DATA_AGE_LABELS: Record<string, string> = {
  decade: 'Thập Niên',
  century: 'Bách Niên',
  millennium: 'Thiên Niên',
  myriad_year: 'Vạn Niên',
  thuong_co: 'Thượng Cổ',
}

function dataAgeLabel(age: string, years: number | undefined): string | undefined {
  if (DATA_AGE_LABELS[age]) {
    return DATA_AGE_LABELS[age]
  }

  return years !== undefined ? `${years} năm` : undefined
}

/**
 * Tên GỐC của họ (bỏ prefix tuổi) — tên material giờ có dạng
 * "<Tuổi> <Tên gốc>" (spec 2026-08-30-unify-material-quality-names);
 * ô gộp họ hiển thị tên gốc, tuổi/chất đã có trong badge nên không
 * lặp. Material legacy không khớp prefix nào giữ nguyên tên.
 */
export function baseNameFor(material: Material): string {
  const label = variantLabel(material)

  if (label && material.name.startsWith(`${label} `)) {
    return material.name.slice(label.length + 1)
  }

  return material.name
}

/** Khoá gộp họ: thảo theo herbBaseId, gỗ/quáng theo resourceKind+realmId — undefined nếu không gộp. */
function familyKeyFor(material: Material): string | undefined {
  const meta = material.profession

  if (!meta) return undefined

  if (meta.resourceKind === 'herb') return meta.herbBaseId

  if (meta.resourceKind === 'wood' || meta.resourceKind === 'ore') {
    return `${meta.resourceKind}:${meta.realmId}`
  }

  return undefined
}

export interface HerbVariant {
  material: Material

  amount: number
}

export interface HerbFamilyGroup {
  herbBaseId: string

  /** Tên hiển thị lấy từ biến thể đầu tiên gặp. */
  name: string

  realmId: string

  variants: HerbVariant[]

  /**
   * Badge: "Phàm Nhân · Thập Niên" (niên đại rộng nhất họ) — GHÉP SẴN
   * vi data realm + KEY locale bậc tuổi ("{realm} · {badgeKey}") để
   * consumer t() 1 lần; bậc chỉ có suffix số năm thì giữ nguyên số.
   */
  badgeLabel: string
}

export interface FilteredMaterial {
  /** Khóa ổn định cho grid — material riêng hoặc herbBaseId của họ. */
  key: string

  material: Material

  /** Tổng amount của họ thảo (cộng dồn biến thể). */
  amount: number

  /** Họ thảo đã gộp — render thành 1 ô thay cho nhiều biến thể. */
  family?: HerbFamilyGroup
}

export interface BagFilterOptions {
  searchQuery: Ref<string>

  activeGroup: Ref<MaterialGroup | 'all'>
}

export interface BagFilterState {
  /** Item đã lọc + gộp họ thảo — đưa thẳng vào sort/pagination sau đó. */
  filtered: ComputedRef<FilteredMaterial[]>

  /** Số ô hiển thị sau lọc/gộp — đếm UI. */
  visibleCount: ComputedRef<number>

  /** Có đang áp dụng filter nào không (search hoặc nhóm khác 'all'). */
  isFiltering: ComputedRef<boolean>

  clear: () => void
}

function badgeFor(family: HerbFamilyGroup): string {
  const best = family.variants.reduce((acc, variant) => {
    const rank = variantRank(variant.material)

    return rank > acc.rank ? { rank, variant } : acc
  }, { rank: Number.NEGATIVE_INFINITY, variant: family.variants[0]! })

  const meta = best.variant.material.profession

  const badgeKey = ageLabelKey(meta?.age)

  const realmName = realmLabel(family.realmId)

  return badgeKey ? `${realmName} · ${badgeKey}` : realmName
}

export function useBagFilter(
  entries: ComputedRef<{ material: Material; amount: number }[]>,
  options: BagFilterOptions,
): BagFilterState {
  const { searchQuery, activeGroup } = options

  const filtered = computed<FilteredMaterial[]>(() => {
    const query = normalizeSearchText(searchQuery.value.trim())

    const grouped = new Map<string, FilteredMaterial>()

    for (const entry of entries.value) {
      // Filter nhóm trước.
      const group = toMaterialGroup(entry.material.category)

      if (activeGroup.value !== 'all' && group !== activeGroup.value) {
        continue
      }

      // Search theo tên (đã normalize bỏ dấu).
      if (query && !normalizeSearchText(entry.material.name).includes(query)) {
        continue
      }

      const meta = entry.material.profession

      // Gộp theo HỌ: thảo theo herbBaseId, gỗ/quáng theo resourceKind+
      // realmId — material legacy không có meta đi theo đường riêng.
      const familyKey = familyKeyFor(entry.material)

      if (familyKey) {
        const existing = grouped.get(familyKey)

        if (existing?.family) {
          existing.amount += entry.amount
          existing.family.variants.push({ material: entry.material, amount: entry.amount })
        } else {
          grouped.set(familyKey, {
            key: familyKey,
            material: entry.material,
            amount: entry.amount,
            family: {
              herbBaseId: familyKey,
              name: baseNameFor(entry.material),
              realmId: meta!.realmId,
              variants: [{ material: entry.material, amount: entry.amount }],
              badgeLabel: '',
            },
          })
        }

        continue
      }

      const key = entry.material.id

      grouped.set(key, {
        key,
        material: entry.material,
        amount: entry.amount,
      })
    }

    // Badge tính SAU khi gộp đủ biến thể — niên đại rộng nhất của họ,
    // đúng cả khi biến thể đến theo thứ tự niên đại bất kỳ.
    const result = Array.from(grouped.values())

    for (const item of result) {
      if (item.family) {
        item.family.badgeLabel = badgeFor(item.family)
      }
    }

    return result
  })

  const visibleCount = computed(() => filtered.value.length)

  const isFiltering = computed(
    () => searchQuery.value.trim() !== '' || activeGroup.value !== 'all',
  )

  function clear() {
    searchQuery.value = ''

    activeGroup.value = 'all'
  }

  return { filtered, visibleCount, isFiltering, clear }
}

// @vitest-environment jsdom
//
// Remediation Task 4 (2026-09-05) — useBagGridLayout đo grid CHỈ tại
// onMounted: grid nằm trong v-if/tab (như tab Hóa Luyện, EquipmentHall)
// sẽ KHÔNG tồn tại lúc mount → observer không bao giờ attach → layout
// kẹt fallback MIN_COLUMNS/MIN_ROWS vĩnh viễn dù container render và
// resize sau đó. Sửa: watch gridRef (immediate) — disconnect observer cũ
// khi ref đổi, attach khi element mới xuất hiện, cleanup khi unmount.
// Pattern mirror usePanelPagination (audit H4 2026-08-31 đã sửa cùng
// lỗi cho list dọc).
//
// KHÔNG có @vue/test-utils trong devDeps → mount thủ công createApp
// (cùng pattern usePanelPagination.test.ts).
import { afterEach, describe, expect, it, vi } from 'vitest'
import { createApp, h, nextTick, ref } from 'vue'
import { useBagGridLayout } from './useBagGridLayout'
import { GRID_GAP, MIN_COLUMNS, MIN_ROWS } from '@/core/ui/SlotSizes'

// jsdom không có ResizeObserver thật — stub global bằng class mock
// (giống usePanelPagination.test.ts).
class MockResizeObserver {
  static instances: MockResizeObserver[] = []

  callback: ResizeObserverCallback
  observe = vi.fn()
  disconnect = vi.fn()
  unobserve = vi.fn()

  constructor(callback: ResizeObserverCallback) {
    this.callback = callback
    MockResizeObserver.instances.push(this)
  }
}

function fireLayout(entries: Array<{ width: number; height: number }>) {
  const observer = MockResizeObserver.instances.at(-1)

  if (!observer) {
    return
  }

  observer.callback(
    entries.map(
      (rect) => ({ contentRect: rect }) as unknown as ResizeObserverEntry,
    ),
    observer as unknown as ResizeObserver,
  )
}

function mountHost() {
  const show = ref(false)
  const observedWidths: number[] = []

  const container = document.createElement('div')

  document.body.appendChild(container)

  const app = createApp({
    setup() {
      const { gridRef, layout, pageSize, gridStyle } = useBagGridLayout()

      return () => {
        observedWidths.push(layout.value.columns)

        return [
          // Grid như tab bag: chỉ tồn tại khi show = true.
          show.value ? h('div', { ref: gridRef }) : null,
          // Render layout ra text để assert không cần expose.
          h('div', `columns:${layout.value.columns};pageSize:${pageSize.value};style:${gridStyle.value['--grid-columns']}`),
        ]
      }
    },
  })

  app.mount(container)

  return {
    show,
    root: container,
    unmount: () => {
      app.unmount()
      container.remove()
    },
  }
}

describe('useBagGridLayout — conditional mount (Remediation Task 4)', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it('grid render SAU mount (v-if): trước đó observer không bao giờ attach — giờ layout cập nhật khi ref gán + callback fire', async () => {
    vi.stubGlobal('ResizeObserver', MockResizeObserver)
    MockResizeObserver.instances.length = 0

    const host = mountHost()

    // Chưa show → layout fallback MIN.
    expect(host.root.textContent).toBe(
      `columns:${MIN_COLUMNS};pageSize:${MIN_COLUMNS * MIN_ROWS};style:${MIN_COLUMNS}`,
    )

    // Show grid (như mở tab bag) → ref gán → observer attach.
    host.show.value = true
    await nextTick()
    await nextTick()

    const observer = MockResizeObserver.instances.at(-1)

    expect(observer).toBeDefined()
    expect(observer!.observe).toHaveBeenCalledTimes(1)

    // Callback fire: container 600×200 → layout tính từ kích thước thật.
    fireLayout([{ width: 600, height: 200 }])
    await nextTick()

    expect(host.root.textContent).not.toContain(`columns:${MIN_COLUMNS};`)
    expect(host.root.textContent).toContain(`style:`)

    host.unmount()
  })

  it('resize sau khi layout đã đo → columns/pageSize/style cập nhật lại', async () => {
    vi.stubGlobal('ResizeObserver', MockResizeObserver)
    MockResizeObserver.instances.length = 0

    const host = mountHost()

    host.show.value = true
    await nextTick()
    await nextTick()

    fireLayout([{ width: 1600, height: 900 }])
    await nextTick()

    const wideText = host.root.textContent

    expect(wideText).not.toBe(
      `columns:${MIN_COLUMNS};pageSize:${MIN_COLUMNS * MIN_ROWS};style:${MIN_COLUMNS}`,
    )

    fireLayout([{ width: 200, height: 120 }])
    await nextTick()

    const narrowText = host.root.textContent

    expect(narrowText).not.toBe(wideText)

    host.unmount()
  })

  it('ref gán LẠI (grid unmount rồi remount): observer cũ disconnect, observer mới attach', async () => {
    vi.stubGlobal('ResizeObserver', MockResizeObserver)
    MockResizeObserver.instances.length = 0

    const host = mountHost()

    host.show.value = true
    await nextTick()
    await nextTick()

    const first = MockResizeObserver.instances.at(-1)

    expect(first).toBeDefined()
    expect(first!.observe).toHaveBeenCalledTimes(1)

    // Ẩn rồi hiện lại → ref null rồi gán element mới.
    host.show.value = false
    await nextTick()
    await nextTick()

    expect(first!.disconnect).toHaveBeenCalled()

    host.show.value = true
    await nextTick()
    await nextTick()

    const second = MockResizeObserver.instances.at(-1)

    expect(second).toBeDefined()
    expect(second).not.toBe(first)
    expect(second!.observe).toHaveBeenCalledTimes(1)

    host.unmount()

    // Unmount cleanup: observer cuối disconnect.
    expect(second!.disconnect).toHaveBeenCalled()
  })

  it('grid tồn tại NGAY từ mount (current behavior giữ nguyên): observer attach lúc mounted', async () => {
    vi.stubGlobal('ResizeObserver', MockResizeObserver)
    MockResizeObserver.instances.length = 0

    const show = ref(true)
    const container = document.createElement('div')

    document.body.appendChild(container)

    const app = createApp({
      setup() {
        const { gridRef, layout } = useBagGridLayout()

        return () => [
          h('div', { ref: gridRef }),
          h('div', `gap:${layout.value.gap}`),
        ]
      },
    })

    app.mount(container)

    await nextTick()
    await nextTick()

    const observer = MockResizeObserver.instances.at(-1)

    expect(observer).toBeDefined()
    expect(observer!.observe).toHaveBeenCalledTimes(1)

    fireLayout([{ width: 900, height: 500 }])
    await nextTick()

    expect(container.textContent).toContain(`gap:${GRID_GAP}`)

    app.unmount()
    container.remove()
  })
})

// @vitest-environment jsdom
// Task 8 (A11) — the unwatched pause. A hidden tab freezes combat with
// reason 'tab-hidden'; becoming visible again must NOT resume it (spec
// §6.1: "Returning attention is not consent to resume"). Only
// continueBattle() (wired to the player's Continue button) may resume.
import { afterEach, describe, expect, it, vi } from 'vitest'
import { useCombatPause } from './useCombatPause'

describe('useCombatPause', () => {
  let visibility: DocumentVisibilityState = 'visible'

  function stubVisibility() {
    Object.defineProperty(document, 'visibilityState', {
      configurable: true,
      get: () => visibility,
    })
  }

  afterEach(() => {
    visibility = 'visible'
    vi.restoreAllMocks()
  })

  it('pauses when hidden and does NOT resume when visible again', () => {
    stubVisibility()
    const calls: string[] = []
    const gameManager = {
      freezeCombat: (r: string) => calls.push(`freeze:${r}`),
      resumeCombat: (r: string) => calls.push(`resume:${r}`),
    }

    const { isPaused, continueBattle, dispose } = useCombatPause(gameManager as any)

    visibility = 'hidden'
    document.dispatchEvent(new Event('visibilitychange'))
    expect(isPaused.value).toBe(true)
    expect(calls).toEqual(['freeze:tab-hidden'])

    visibility = 'visible'
    document.dispatchEvent(new Event('visibilitychange'))
    expect(isPaused.value).toBe(true)
    expect(calls).toEqual(['freeze:tab-hidden'])

    continueBattle()
    expect(isPaused.value).toBe(false)
    expect(calls).toEqual(['freeze:tab-hidden', 'resume:tab-hidden'])

    dispose()
  })

  it('does not pause when not in combat', () => {
    stubVisibility()
    const calls: string[] = []
    const gameManager = {
      freezeCombat: (r: string) => calls.push(`freeze:${r}`),
      resumeCombat: (r: string) => calls.push(`resume:${r}`),
    }

    const { isPaused, dispose } = useCombatPause(gameManager as any, {
      isCombatActive: () => false,
    })

    visibility = 'hidden'
    document.dispatchEvent(new Event('visibilitychange'))

    expect(isPaused.value).toBe(false)
    expect(calls).toEqual([])

    dispose()
  })
})

