import { toTurnBattleParticipant } from '../../game/TurnBattleAdapter'
import { GENERIC_PHYSICAL_BASIC } from '../../../data/skill/TurnBasicAttacks'

// Combat Runtime Separation (Task 1, 2026-09-07) — CombatAnimationRuntime
// owns the presentation-ack timing state extracted from GameManager (P17).
// Fixture below mirrors the createCombatant()/participant() convention
// already used by TurnBattleSystem.test.ts — a real CombatSystem +
// TurnBattleSystem so declareActorAction/applyActionImpact/completeAction
// run for real (no mocking the business logic the runtime delegates to).

function createCombatant(id: string, overrides: Partial<CombatEntity> = {}): CombatEntity {
  const stats = createBaseStats({ evasionRate: 0, dexterity: 0, criticalRate: 0 })

  return {
    id,
    name: id,
    type: 'player',
    baseStats: stats,
    stats,
    currentHp: stats.maxHp,
    maxHp: stats.maxHp,
    currentMp: stats.maxMp,
    currentSwordIntent: 0,
    currentMomentum: 0,
    currentHoaThe: 0,
    currentThoThe: 0,
    currentKimThe: 0,
    timeSinceLastBleedProc: 0,
    tuLucActive: false,
    tuLucElapsed: 0,
    tuLucDamageTakenPercent: 0,
    currentWard: 0,
    timeSinceLastHitTaken: Infinity,
    realmIndex: 0,
    x: 0,
    row: 4,
    alive: true,
    ...overrides,
  } as CombatEntity
}

function fixture() {
  const eventBus = new EventBus()
  const combatSystem = new CombatSystem(eventBus)
  const turnBattleSystem = new TurnBattleSystem(combatSystem)

  const player = toTurnBattleParticipant(
    createCombatant('player', { type: 'player', x: 0, row: 4 }),
    0,
    GENERIC_PHYSICAL_BASIC,
  )
  const enemy = toTurnBattleParticipant(
    createCombatant('enemy', { type: 'enemy', x: 2, row: 4 }),
    1,
    GENERIC_PHYSICAL_BASIC,
  )

  const battle: TurnBattle = {
    players: [player],
    enemies: [enemy],
    state: 'fighting',
    totalTurnsElapsed: 0,
  }

  const runtime = new CombatAnimationRuntime({
    getTurnBattleSystem: () => turnBattleSystem,
    eventBus,
    getBattle: () => battle,
  })

  return { runtime, battle, player, enemy, eventBus, turnBattleSystem }
}

describe('R5 runtime contract re-audit', () => {
  it('emits exactly one gameplay attack in presentation mode, matching headless', () => {
    const visual = fixture()
    const headless = fixture()
    const visualEvents: string[] = []
    const headlessEvents: string[] = []
    visual.eventBus.on('attack', () => visualEvents.push('attack'))
    headless.eventBus.on('attack', () => headlessEvents.push('attack'))
    headless.turnBattleSystem.resolveActorTurn(headless.battle, headless.player)
    visual.runtime.setPresentationActive(true)
    visual.runtime.notifyReadyActor(visual.player)
    const token = visual.runtime.getPendingPlaybackToken()!
    visual.runtime.acknowledgeTurnReady(token)
    visual.runtime.acknowledgeActionImpact(token)
    visual.runtime.acknowledgeActionComplete(token)
    expect(headlessEvents).toHaveLength(1)
    expect(visualEvents).toHaveLength(headlessEvents.length)
  })

  it('rejects an omitted ready token without declaring a new action', () => {
    const { runtime, player } = fixture()
    runtime.notifyReadyActor(player)
    runtime.acknowledgeTurnReady(undefined)
    expect(runtime.getAnimationState(player.id)).toBe('ready')
  })

  it('rejects an omitted impact token without applying damage', () => {
    const { runtime, player, enemy } = fixture()
    runtime.notifyReadyActor(player)
    runtime.acknowledgeTurnReady(runtime.getPendingPlaybackToken()!)
    const hp = enemy.entity.currentHp
    runtime.acknowledgeActionImpact(undefined)
    expect(enemy.entity.currentHp).toBe(hp)
    expect(runtime.getAnimationState(player.id)).toBe('cast')
  })

  it('rejects an omitted complete token without completing the turn', () => {
    const { runtime, player, battle } = fixture()
    runtime.notifyReadyActor(player)
    const token = runtime.getPendingPlaybackToken()!
    runtime.acknowledgeTurnReady(token)
    runtime.acknowledgeActionImpact(token)
    const turns = battle.totalTurnsElapsed
    runtime.acknowledgeActionComplete(undefined)
    expect(battle.totalTurnsElapsed).toBe(turns)
    expect(runtime.getAnimationState(player.id)).toBe('standby')
  })

  it('rejects an old explicit token after a reset and new action', () => {
    const { runtime, player } = fixture()
    runtime.notifyReadyActor(player)
    const stale = runtime.getPendingPlaybackToken()!
    runtime.resetPendingState()
    runtime.notifyReadyActor(player)
    runtime.acknowledgeTurnReady(stale)
    expect(runtime.getAnimationState(player.id)).toBe('ready')
  })
})

import { describe, expect, it } from 'vitest'
import { recomputeEffectiveStats } from './TurnStatsRecompute'
import { calculateStats } from '../../stats/StatCalculator'
import { createBaseStats, type Stats } from '../../stats/StatBlock'
import { BuffPool } from '../../buff/BuffPool'
import { BuffSystem } from '../../buff/BuffSystem'
import type { BuffDefinition, BuffDefinitionCatalog } from '../../buff/BuffTypes'
import type { CombatEntity } from '../../combat/CombatEntity'

// R2 (AR-02) — recomputeEffectiveStats now treats its first argument as an
// ALREADY-RESOLVED base (attribute derivation happened exactly once when
// the entity was built). Fixture mirrors the audit probe: raw attack 10 +
// strength 100 resolves to attack 70; an in-battle +50% attack buff must
// fold onto 70 (=105), not re-derive strength (+60) first (=130).

function qaEntity(overrides: Partial<CombatEntity> = {}): CombatEntity {
  const stats = createBaseStats({ evasionRate: 0, criticalRate: 0, blockChance: 0, ...overrides.stats })
  const { stats: _drop, ...rest } = overrides
  return {
    id: 'id', name: 'name', type: 'enemy', baseStats: stats, stats,
    currentHp: stats.maxHp, maxHp: stats.maxHp, currentMp: stats.maxMp,
    currentSwordIntent: 0, currentMomentum: 0, currentHoaThe: 0, currentThoThe: 0, currentKimThe: 0,
    timeSinceLastBleedProc: 0, tuLucActive: false, tuLucElapsed: 0, tuLucDamageTakenPercent: 0,
    currentWard: 0, timeSinceLastHitTaken: Infinity, realmIndex: 0, x: 0, row: 2, alive: true,
    ...rest,
  } as CombatEntity
}

class FixtureBuffRegistry implements BuffDefinitionCatalog {
  private readonly definitions = new Map<string, BuffDefinition>()
  constructor(definitions: BuffDefinition[]) {
    for (const d of definitions) this.definitions.set(d.id, d)
  }
  get(id: string): BuffDefinition {
    const d = this.definitions.get(id)
    if (!d) throw new Error(`fixture buff not found: ${id}`)
    return d
  }
}

const ATTACK_UP_DEFINITION: BuffDefinition = {
  id: 'fixture_attack_up',
  name: 'Fixture Attack Up',
  polarity: 'buff',
  duration: 3,
  stackMode: 'refresh',
  effects: [{ type: 'statModifier', stat: 'attack', flat: 50 }],
}

function makePoolWithAttackBuff(percent: number, stacks: number): BuffPool {
  const pool = new BuffPool()
  const definition: BuffDefinition = {
    id: 'qa_atk_buff',
    name: 'QA Attack Buff',
    polarity: 'buff',
    duration: 5,
    maxStacks: 5,
    stackMode: 'stack',
    effects: [{ type: 'statModifier', stat: 'attack', percent }],
  }
  const registry: BuffDefinitionCatalog = {
    get: (id: string): BuffDefinition => {
      if (id === definition.id) {
        return definition
      }
      throw new Error(`unknown fixture buff id: ${id}`)
    },
  }
  // Minimal entity stub: statModifier folding never reads entity fields,
  // but BuffSystem.apply requires real CombatEntity-shaped args.
  const entity = {
    id: 'src',
    stats: { ailmentResistPercent: 0, ailmentDurationPercent: 0 },
    skillStats: undefined,
  } as unknown as CombatEntity

  const system = new BuffSystem(pool)

  for (let i = 0; i < stacks; i++) {
    system.apply(definition, entity, entity, registry)
  }

  return pool
}

describe('recomputeEffectiveStats (R2 effective boundary)', () => {
  it('folds buff modifiers onto the RESOLVED base without re-deriving attributes', () => {
    const raw = createBaseStats({ strength: 100, attack: 10 })
    const resolved = calculateStats(raw, [])
    expect(resolved.attack).toBe(70)

    // 2 stacks × +50% increased pool → 70 × (1 + 0.5 + 0.5) = 140.
    const effective = recomputeEffectiveStats(resolved, makePoolWithAttackBuff(0.5, 2))
    expect(effective.attack).toBe(140)
  })

  it('no buffs: effective equals resolved base exactly', () => {
    const raw = createBaseStats({ strength: 100, attack: 10 })
    const resolved = calculateStats(raw, [])

    expect(recomputeEffectiveStats(resolved, new BuffPool())).toEqual(resolved)
  })
})

describe('recomputeEffectiveStats', () => {
  it('folds active statModifier buff effects into the resolved base via the effective pipeline', () => {
    // R2: the input is a RESOLVED base — attribute derivation must NOT
    // run again, so the old strength-derivation expectations (+0.6) are
    // gone. Resolved attack 100 + flat buff 50 = 150 exactly.
    const base = createBaseStats({ attack: 100 })
    const pool = new BuffPool()
    const registry = new FixtureBuffRegistry([ATTACK_UP_DEFINITION])
    const source = qaEntity({ id: 'src' })
