}

function makeEquipment(slot: EquipmentSlotState['slot'] = 'weapon'): Equipment {
  return {
    id: `base_${slot}`,
    name: 'Kiếm',
    slot,
    maxEnhanceLevel: 10,
    implicitStats: [],
    mainStats: [{ stat: 'attack', min: 10, max: 20 }],
    affixPools: [],
    iconPool: [],
  } as unknown as Equipment
}function makeInstance(id: string): EquipmentInstance {
  return {
    instanceId: id,
    itemId: 'base_weapon',
    slot: 'weapon',
    equipped: false,
    quality: 'hoang',
    grade: 'cuu_pham',
    realmLevel: 1,
