  /** @internal - diagnostics; the freeze reason set is the engine's channel. */
  getFreezeReasons(): readonly FreezeReason[] {
    return this.turnBattleOps.getFreezeReasons()
  }

  /** @internal - for tests and the dev inspector, never for gameplay code. */
  getTurnTokenState(): TokenState {
    return this.turnBattleOps.getTurnTokenState()
  }

  /** The single predicate for "a turn is in flight" (spec section 2). */
  isTurnInFlight(): boolean {
    return this.turnBattleOps.isTurnInFlight()
  }

  setPresentationMode(mode: PresentationMode): void {
    this.turnBattleOps.presentationOps.setPresentationMode(mode)
    this.tribulationDirector.setPresentationMode(mode)
  }

  getPresentationMode(): PresentationMode {
    return this.turnBattleOps.presentationOps.getPresentationMode()
  }

  /**
   * Without `kind` this answers "any active session", combat first - that is a
   * recovery query for the coordinator, NOT an identity source for a caller
   * that just issued a start command. Entry points MUST pass their kind:
   * combat and tribulation sessions can be active at the same time (a terminal
   * battle may still sit at Home), so an unscoped read can hand back the other
   * owner's session and produce a request the coordinator must reject.
   */
  getCurrentPresentationSession(kind?: SessionKind): SessionRef | null {
    if (kind === 'combat') {
      return this.turnBattleOps.presentationOps.getCurrentPresentationSession()
    }

    if (kind === 'tribulation') {
      return this.tribulationDirector.getCurrentPresentationSession()
    }

    return (
      this.turnBattleOps.presentationOps.getCurrentPresentationSession() ??
      this.tribulationDirector.getCurrentPresentationSession() ??
      null
    )
  }

  getPresentationPort(): SessionPresentationPort {
    return {
      getCurrentSession: () => this.getCurrentPresentationSession(),
      hold: (session) => {
        if (session.kind === 'combat') {
          return this.turnBattleOps.presentationOps.getPresentationPort().hold(session)
        }
        if (session.kind === 'tribulation') {
          return this.tribulationDirector.getPresentationPort().hold(session)
        }
        return null
      },
      attach: (token) => {
        return (
          this.turnBattleOps.presentationOps.getPresentationPort().attach(token) ||
          this.tribulationDirector.getPresentationPort().attach(token)
        )
      },
      release: (token) => {
        return (
          this.turnBattleOps.presentationOps.getPresentationPort().release(token) ||
          this.tribulationDirector.getPresentationPort().release(token)
        )
      },
      detach: (token, policy) => {
        return (
          this.turnBattleOps.presentationOps.getPresentationPort().detach(token, policy) ||
          this.tribulationDirector.getPresentationPort().detach(token, policy)
        )
      },
    }
  }

  getTribulationPresentationSnapshot(sessionId: number): { sessionId: number; state: ActiveTribulationState } | null {
    return this.tribulationDirector.getPresentationSnapshot(sessionId)
  }

  /** True while the current interactive session is held by the coordinator. */
  isAwaitingPresentationLayer(): boolean {
    return this.turnBattleOps.presentationOps.isAwaitingPresentationLayer()
  }

  /** Test/UI đọc token hiện tại của phase đang chờ (null nếu không pending). */
  getPendingPlaybackToken(): string | null {
    return this.turnBattleOps.presentationOps.getPendingPlaybackToken()
  }

  preparePresentationResume(): ResumePlayback | null {
    return this.turnBattleOps.presentationOps.preparePresentationResume()
  }

  getCombatPresentationSnapshot(sessionId: number): {
    sessionId: number
    entities: TurnBattleEntitySnapshotEvent
  } | null {
    return this.turnBattleOps.presentationOps.getCombatPresentationSnapshot(sessionId)
  }

  setPresentationActive(active: boolean): void {
    this.turnBattleOps.presentationOps.setPresentationActive(active)
  }

  isActionPlaybackWaiting(): boolean {
    return this.turnBattleOps.presentationOps.isActionPlaybackWaiting()
  }

  /** Phaser gọi khi ready flourish xong → declare action, phát 'attack'. */
  acknowledgeTurnReady(token?: string): void {
    this.turnBattleOps.presentationOps.acknowledgeTurnReady(token)
  }

  /** Phaser gọi tại impact frame (lunge tween xong) → áp damage, phát VFX. */
  acknowledgeActionImpact(token?: string): void {
    this.turnBattleOps.presentationOps.acknowledgeActionImpact(token)
  }

  /** Phaser gọi khi VFX tween xong → turn cleanup, phát standby tail. */
  acknowledgeActionComplete(token?: string): void {
    this.turnBattleOps.presentationOps.acknowledgeActionComplete(token)
  }

  /**
   * UI submit choice cho lượt đang pause. Trả false nếu không có pause
   * (no-op an toàn — choice bị bỏ, không crash).
   */
  submitTurnChoice(role: TurnSkillSlotRole): boolean {
    return this.turnBattleOps.submitTurnChoice(role)
  }

  /**
   * Dành cho UI: id của actor đang pause (luôn là 'player' ở engine hiện
   * tại — party nhiều người là redesign tương lai), null khi không pause.
   */
  consumeAwaitedActorId(): string | null {
    return this.turnBattleOps.presentationOps.consumeAwaitedActorId()
  }

  /**
   * Slice 7 — presentation facade: buildTurnSkillPresentation cho trận
   * turn hiện tại (isPlayerTurnPaused = manual pause đang chờ choice).
   * Party (Task 10): khi pause, presentation theo PAUSED ACTOR (bất kỳ
   * party member nào), không cố định players[0].
   */
  buildTurnSkillPresentation(
    battle: TurnBattle,
    isPlayerTurnPaused: boolean,
  ): {
    basic: TurnSkillPresentationEntry
    special: TurnSkillPresentationEntry
    ultimate: TurnSkillPresentationEntry
  } {
    return this.turnBattleOps.presentationOps.buildTurnSkillPresentation(battle, isPlayerTurnPaused)
  }

  getBattleRewardSummary(): BattleRewardSummary {
    return this.battleLoot.getSummary()
  }

  /**
   * Tiện ích: bắt đầu trận đấu thẳng từ PlayerData thay vì phải
   * tự convert sang CombatEntity trước. `playerStats` truyền vào
   * phải là finalStats (đã cộng modifiers) — lấy từ
   * player store getter `finalStats`, không tính lại ở đây để
   * tránh 2 nơi tự gọi calculateStats() khác nhau.
   */
  startBattleWithPlayer(player: PlayerData, playerStats: Stats, enemy: Enemy) {
    this.turnBattleOps.startBattleWithPlayer(player, playerStats, enemy)
  }

  /**
   * getBattle() returns the TurnBattle (cast to the Battle shape its
   * read-only consumers expect: state/player/enemies). C1: the legacy
   * fallback branch is gone — null when no turn battle (tribulation side
   * never creates one).
   */
  getBattle(): Battle | null {
    return this.turnBattleOps.getBattle()
  }

  /**

    * ï¿½? Ki?p (spec dot-pha-loi-kiep ï¿½5.1) ï¿½ delegate xu?ng
    * TribulationDirector (runtime chuong ki?p m?i: tï¿½m ma + tank lï¿½i,
    * KHï¿½NG qua BattleSystem, khï¿½ng quï¿½i Ki?p). hasTrucCoDan d?c t?
    * PillBag (v?t ch?ng b?c ï¿½?a/Thiï¿½n, khï¿½ng tiï¿½u). B?t T? Th? khï¿½ng ï¿½p
    * trong ki?p (nghi l? th?t ï¿½ gi? pattern cu): ki?p khï¿½ng qua combat
    * nï¿½n khï¿½ng cï¿½ session nï¿½o d? xoï¿½.
    */

  startTribulation(
    player: PlayerData,
    playerStats: Stats,
    targetRealmId: string,
  ): boolean {
    const hasTrucCoDan = this.pillBag.has('truc_co_dan', 1)

    return this.tribulationDirector.start(player, playerStats, hasTrucCoDan, targetRealmId)
  }

  /**
   * Người chơi CHỦ ĐỘNG thoát trận giữa chừng (nút "Thoát Trận" ở
   * CombatControlBar.vue, có xác nhận trước khi gọi tới đây) — TÁI
   * DÙNG luồng 'defeat' sẵn có thay vì dựng 1 BattleState/UI mới:
   * chỉ set battle.state + emit 'battle_end' giống hệt
   * BattleSystem.checkBattleEnd() làm khi player chết.
   * updateStageProgress() TỰ dừng stageManager ở tick kế tiếp khi thấy
   * state 'defeat' (xem ghi chú ở đó) — không cần tự dọn gì thêm ở
   * đây. Phần thưởng đã kiếm được (grantBattleRewardIfNeeded() chạy
   * MỖI TICK theo từng quái chết, không đợi tới cuối trận) KHÔNG mất
   * dù thoát giữa chừng. Chỉ áp dụng trận Stage — Tribulation (Đột
   * Phá) có luồng thắng/thua RIÊNG (useTribulation.ts), nút "Thoát
   * Trận" không hiện trong trận đó (xem CombatControlBar.vue).
   */
  abandonBattle(): boolean {
    return this.turnBattleOps.abandonBattle()
  }

  /**
   * Vue layer (App.vue's tick()) gọi mỗi tick để rút toast phát sinh
   * TRONG core kể từ lần gọi trước — trả về rồi xoá hàng đợi.
   */
  drainNotifications(): NotificationEvent[] {
    return this.notifications.drain()
  }
}

import type { EventBus } from '../events/EventBus'
import {
  PresentationSession,
  type PresentationMode,
  type SessionPresentationPort,
  type SessionRef,
} from '../presentation/PresentationSession'
import type { TurnBattle, TurnBattleSystem } from '../battle/turn/TurnBattleSystem'
import {
  CombatAnimationRuntime,
  type ResumePlayback,
} from '../battle/turn/CombatAnimationRuntime'
import type { TurnSkillSlotRole } from '../battle/turn/TurnSkillAction'
import {
  buildTurnBattleEntitySnapshot,
  type TurnBattleEntitySnapshotEvent,
} from '../battle/turn/TurnActionPresentationEvents'
import type { TurnSkillPresentationEntry } from '../combat/CombatSkillPresentation'
import { buildTurnSkillPresentation } from '../combat/CombatSkillPresentation'

/**
 * The three renderer signals the pipeline's asynchronous steps wait on.
 * Presentation owns this contract: the signals ARE renderer reports.
 */
export type TurnStepSignal = 'ready' | 'impact' | 'complete'

/**
 * Presentation facade for the turn battle (Wave-2 GameManagerTurnBattleOps
 * split; moved verbatim). Owns the presentation object graph:
 *
 * - PresentationSession - interactive-session hold/attach/release lifecycle;
 * - CombatAnimationRuntime - the presentation-ack timing state machine;
 * - presentationMode flag ('headless' | 'interactive').
 *
 * The scheduling core (clock/token/pipeline) reaches the owned objects via
 * the public `runtime`/`session` fields; this ops also carries the facade
 * methods GameManager forwards (ack tokens, session queries, snapshot).
 * Commands that drive the turn token or pipeline (setBattleManualMode,
 * submitTurnChoice) stay in the scheduling core - they are not pure
 * presentation reads.
 *
 * Public access: `gameManager.turnBattleOps.presentationOps.*`.
 */
export class GameManagerTurnBattlePresentationOps {
  readonly session: PresentationSession
  readonly runtime: CombatAnimationRuntime

  private presentationMode: PresentationMode = 'headless'

  constructor(
    private readonly deps: {
      sessionAllocator?: { allocate(): number }
      eventBus: EventBus
      // Live getters - turnBattleSystem/turnBattle are REASSIGNED wholesale
      // by the battle owner (restartTurnBattleCycle/startStage), so
      // capturing by value would freeze the runtime onto the first
      // registry-less instance.
      getTurnBattleSystem: () => TurnBattleSystem
      getBattle: () => TurnBattle | null
      // The clock's 'not-revealed' freeze reason re-evaluates after every
      // session transition (owned by the scheduling core).
      syncOffScreenFreeze: () => void
      // Pipeline settle for parked steps - deferred back into the core.
      settleStep: (signal: TurnStepSignal) => void
    },
  ) {
    this.session = new PresentationSession(deps.sessionAllocator)

    this.runtime = new CombatAnimationRuntime({
      getTurnBattleSystem: deps.getTurnBattleSystem,
      eventBus: deps.eventBus,
      getBattle: deps.getBattle,
      isSessionBlocking: () => this.session.isBlocking(),
      stepCompletionSink: {
        onReady: () => this.deps.settleStep('ready'),
        onImpact: () => this.deps.settleStep('impact'),
        onComplete: () => this.deps.settleStep('complete'),
      },
    })
  }

  setPresentationMode(mode: PresentationMode): void {
    this.presentationMode = mode
  }

  getPresentationMode(): PresentationMode {
    return this.presentationMode
  }

  getCurrentPresentationSession(): SessionRef | null {
    return this.session.getCurrentSession()
  }

  /**
   * The port the presentation coordinator drives. Every transition that can
   * change whether the battle is on screen re-evaluates the clock's
   * `not-revealed` freeze reason, so readiness reaches combat time through the
   * reason set and nowhere else.
   */
  getPresentationPort(): SessionPresentationPort {
    return {
      getCurrentSession: () => this.session.getCurrentSession(),
      hold: (session) => this.withOffScreenSync(() => this.session.hold(session)),
      attach: (token) => this.withOffScreenSync(() => this.session.attach(token)),
      release: (token) => this.withOffScreenSync(() => this.session.release(token)),
      detach: (token, policy) =>
        this.withOffScreenSync(() => this.session.detach(token, policy)),
    }
  }

  private withOffScreenSync<T>(operation: () => T): T {
    const result = operation()

    this.deps.syncOffScreenFreeze()

    return result
  }

  /** True while the current interactive session is held by the coordinator. */
  isAwaitingPresentationLayer(): boolean {
    return this.session.isBlocking()
  }

  /**
   * Pure snapshot query for presentation reconciliation (Task 4).
   * Validates sessionId, emits zero events, changes zero state, returns detached plain data.
   */
  getCombatPresentationSnapshot(sessionId: number): {
    sessionId: number
    entities: TurnBattleEntitySnapshotEvent
  } | null {
    const currentSession = this.session.getCurrentSession()
    if (!currentSession || currentSession.sessionId !== sessionId || currentSession.kind !== 'combat') {
      return null
    }

    const battle = this.deps.getBattle()

    if (!battle) {
      return null
    }

    return {
      sessionId,
      entities: buildTurnBattleEntitySnapshot(battle),
    }
  }

  getPendingPlaybackToken(): string | null {
    return this.runtime.getPendingPlaybackToken()
  }

  preparePresentationResume(): ResumePlayback | null {
    return this.runtime.preparePresentationResume()
  }

  setPresentationActive(active: boolean): void {
    this.runtime.setPresentationActive(active)
  }

  isActionPlaybackWaiting(): boolean {
    return this.runtime.isActionPlaybackWaiting()
  }

  /** Phaser gọi khi ready flourish xong → declare action, phát 'attack'. */
  acknowledgeTurnReady(token?: string): void {
    this.runtime.acknowledgeTurnReady(token)
  }

  /** Phaser gọi tại impact frame (lunge tween xong) → áp damage, phát VFX. */
  acknowledgeActionImpact(token?: string): void {
    this.runtime.acknowledgeActionImpact(token)
  }

  /** Phaser gọi khi VFX tween xong → turn cleanup, phát standby tail. */
  acknowledgeActionComplete(token?: string): void {
    this.runtime.acknowledgeActionComplete(token)
  }

  consumeAwaitedActorId(): string | null {
    return this.runtime.getAwaitedManualActor()?.id ?? null
  }

  isBattleManualMode(): boolean {
    return this.runtime.isBattleManualMode()
  }

  /**
   * Slice 7 — presentation facade: buildTurnSkillPresentation cho trận
   * turn hiện tại (isPlayerTurnPaused = manual pause đang chờ choice).
   * Party (Task 10): khi pause, presentation theo PAUSED ACTOR (bất kỳ
   * party member nào), không cố định players[0].
   */
  buildTurnSkillPresentation(
    battle: TurnBattle,
    isPlayerTurnPaused: boolean,
  ): {
    basic: TurnSkillPresentationEntry
    special: TurnSkillPresentationEntry
    ultimate: TurnSkillPresentationEntry
  } {
    return buildTurnSkillPresentation(
      battle,
      isPlayerTurnPaused,
      isPlayerTurnPaused
        ? (this.runtime.getAwaitedManualActor() ?? undefined)
        : undefined,
    )
  }
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import {
  devResetBranch,
  getNodeLevel,
  purchaseNode,
  upgradeNode,
} from './NodeSystem'
import { createDefaultPlayer } from '../player/Player'
import type { ProgressionNode } from './ProgressionNode'

// Talent v4 M2 — Van Dao (spec §4.3 row 18): at each purchase/upgrade a
// 50% roll may waive the insight cost; the waived amount is recorded in
// player.nodeFreePurchaseRecord so devResetBranch refunds only what was
// ACTUALLY paid (record survives talent removal — no refund exploit).
function minorNode(overrides: Partial<ProgressionNode> = {}): ProgressionNode {
  return {
    id: 'test_minor',
    name: 'Test Minor',
    type: 'minor',
    insightCost: 5,
    branchTag: 'test_branch',
    effect: {},
    ...overrides,
  }
}

function growthNode(overrides: Partial<ProgressionNode> = {}): ProgressionNode {
  return minorNode({
    id: 'test_growth',
    insightCost: 4,
    maxLevel: 3,
    upgradeCost: { base: 2, perLevel: 1 },
    ...overrides,
  })
}

describe('NodeSystem — Van Dao free-purchase roll (M2)', () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('roll trung (random < 0.5) — purchase mien phi, ghi waived amount', () => {
    vi.spyOn(Math, 'random').mockReturnValue(0.4)
    const player = createDefaultPlayer()
    player.selectedTalentIds = ['van_dao']
    player.skillInsight = 5

    expect(purchaseNode(player, minorNode())).toBe(true)

    expect(player.skillInsight).toBe(5) // waived — khong tru
    expect(player.nodeFreePurchaseRecord['test_minor']).toBe(5)
    expect(getNodeLevel(player, 'test_minor')).toBe(1)
  })

  it('roll truot (random >= 0.5) — purchase tru cost nhu thuong', () => {
    vi.spyOn(Math, 'random').mockReturnValue(0.9)
    const player = createDefaultPlayer()
    player.selectedTalentIds = ['van_dao']
    player.skillInsight = 5

    expect(purchaseNode(player, minorNode())).toBe(true)

    expect(player.skillInsight).toBe(0)
    expect(player.nodeFreePurchaseRecord['test_minor']).toBeUndefined()
  })

  it('upgradeNode cung roll — waived amount cong don theo cost tung cap', () => {
    const player = createDefaultPlayer()
    player.selectedTalentIds = ['van_dao']
    player.skillInsight = 20

    // growthNode: upgradeCost {base:2, perLevel:1} -> costs 2, 3, 4.
    vi.spyOn(Math, 'random')
      .mockReturnValueOnce(0.9) // purchase pays 2
      .mockReturnValueOnce(0.1) // upgrade to 2 free (waived 3)
      .mockReturnValueOnce(0.1) // upgrade to 3 free (waived 4)

    expect(purchaseNode(player, growthNode())).toBe(true)
    expect(upgradeNode(player, growthNode())).toBe(true)
    expect(upgradeNode(player, growthNode())).toBe(true)

    expect(getNodeLevel(player, 'test_growth')).toBe(3)
    expect(player.skillInsight).toBe(18) // paid 2 only
    expect(player.nodeFreePurchaseRecord['test_growth']).toBe(7) // waived 3 + 4
  })

  it('khong co van_dao — khong roll, khong record', () => {
    const randomSpy = vi.spyOn(Math, 'random').mockReturnValue(0.1)
    const player = createDefaultPlayer()
    player.skillInsight = 10

    expect(purchaseNode(player, minorNode())).toBe(true)

    expect(player.skillInsight).toBe(5)
    expect(player.nodeFreePurchaseRecord).toEqual({})
    // canPurchaseNode still gates — affordability unchanged.
  })

  it('devResetBranch refund = tien THUC tra (tru waived amount da ghi)', () => {
    const player = createDefaultPlayer()
    player.selectedTalentIds = ['van_dao']
    player.skillInsight = 20

    vi.spyOn(Math, 'random')
      .mockReturnValueOnce(0.1) // purchase free (waived 2)
      .mockReturnValueOnce(0.9) // upgrade pays 3
      .mockReturnValueOnce(0.9) // upgrade pays 4

    const node = growthNode()
    purchaseNode(player, node)
    upgradeNode(player, node)
    upgradeNode(player, node)

    expect(player.skillInsight).toBe(13) // 20 - 7 paid
    expect(player.nodeFreePurchaseRecord['test_growth']).toBe(2)

    const registry = { getAll: () => [node] }
    const refunded = devResetBranch(player, registry, 'test_branch')

    // Total level costs 2+3+4=9, waived 2 -> actual paid 7 refunded.
    expect(refunded).toBe(7)
    expect(player.skillInsight).toBe(20)
    // Record cleared together with the reset node (no double-subtract
    // if the node is re-purchased later).
    expect(player.nodeFreePurchaseRecord['test_growth']).toBeUndefined()
  })

  it('refund dung ngay ca khi talent da bi go (record song doc lap)', () => {
    const player = createDefaultPlayer()
    player.selectedTalentIds = ['van_dao']
    player.skillInsight = 20

    vi.spyOn(Math, 'random').mockReturnValue(0.1)

    const node = growthNode()
    purchaseNode(player, node) // free, waived 2 (upgradeCost.base at level 0)

    player.selectedTalentIds = [] // talent removed

    const registry = { getAll: () => [node] }
    const refunded = devResetBranch(player, registry, 'test_branch')

    expect(refunded).toBe(0) // node was free — nothing paid, nothing refunded
    expect(player.skillInsight).toBe(20)
  })
})

import { describe, expect, it } from 'vitest'
import { calculateStats, calculateEffectiveStats, type StatModifier } from './StatCalculator'
import { createBaseStats } from './StatBlock'
import { STAT_METADATA, isPercentStat } from './StatMetadata'
import type { Stats } from './StatBlock'

// Turn-based stat conversion (2026-09-04) — adversarial QA probes cho
// plan 2026-09-04-stat-system-turn-based-conversion. Mỗi test bắn 1
// hypothesis rủi ro riêng của việc rename attackSpeed→speed,
// hpRegenPerSecond→hpRegenPerTurn, retire movementSpeed/
// castSpeedPercent/cooldownReduction.

describe('Adversarial QA — stat turn-based conversion invariants', () => {
  it('INV-1 (Boundedness): baseStats.speed = 100 neo HSR-SPD, không NaN/0', () => {
    const base = createBaseStats()
    expect(base.speed).toBe(100)
    expect(Number.isFinite(base.speed)).toBe(true)
  })

  it('INV-2 (Conservation): Dexterity dẫn xuất speed flat 0.15/điểm, KHÔNG còn percent attackSpeed pool', () => {
    const base = createBaseStats()
    // dexterity 1 → speed = 100 (base) + 1×0.15 (flat) = 100.15
    const result = calculateStats(base, [])
    expect(result.speed).toBeCloseTo(100.15, 5)
    // dexterity 21 → speed = 100 + 21×0.15 = 103.15 (tăng tuyến tính
    // đúng, KHÔNG compound percent).
    const boosted = calculateStats(base, [
      { id: 't:dex', sourceId: 't', sourceType: 'technique', stat: 'dexterity', flat: 20 },
    ])
    expect(boosted.speed).toBeCloseTo(103.15, 5)
  })

  it('INV-3 (Exactly-once/Conservation): Intelligence KHÔNG còn cấp cooldownReduction — modifier không chết lọt pipeline', () => {
    const base = createBaseStats()
    const result = calculateStats(base, [])
    // Trước conversion Intelligence 1 cấp +0.001 CDR. Sau retire, giá
    // trị CDR phải biến mất hoàn toàn (không còn field để nhận).
    expect('cooldownReduction' in result).toBe(false)
    // Intelligence vẫn cấp 2 stat đúng spec §5: criticalDamage là PERCENT
    // modifier → 1.5 × (1 + 1×0.003) = 1.5045.
    expect(result.criticalDamage).toBeCloseTo(1.5 * 1.003, 5)
    expect(result.ailmentResistPercent).toBeCloseTo(1 * 0.002, 5)
  })

  it('INV-4 (Boundedness): hpRegenPerTurn giữ đúng rate 0.1/vitality — đổi tên không đổi số', () => {
    const base = createBaseStats()
    const boosted = calculateStats(base, [
      { id: 't:vit', sourceId: 't', sourceType: 'technique', stat: 'vitality', flat: 9 },
    ])
    // vitality 10 → 10×0.1 = 1.0 hpRegenPerTurn (base 0 + flat).
    expect(boosted.hpRegenPerTurn).toBeCloseTo(1, 5)
  })

  it('INV-5 (Recoverability): StatModifier nhắm stat đã retire bị StatType tĩnh chặn ngay compile-time — runtime chỉ nhận StatType hợp lệ', () => {
    // Metadata của mọi StatType hợp lệ phải tra được; các key đã retire
    // phải vắng mặt khỏi metadata (đảm bảo không còn memento rác).
    expect(STAT_METADATA.speed).toBeUndefined() // speed là flat, không cần trần
    expect(STAT_METADATA.hpRegenPerTurn).toBeUndefined()
    expect('cooldownReduction' in STAT_METADATA).toBe(false)
    expect('castSpeedPercent' in STAT_METADATA).toBe(false)
    expect('movementSpeed' in STAT_METADATA).toBe(false)
    // isPercentStat không phân loại sai speed thành percent.
    expect(isPercentStat('speed')).toBe(false)
  })

  it('INV-6 (Synchronization): createBaseStats đủ đúng StatType — không thiếu key mới, không dư key chết', () => {
    const base = createBaseStats()
    expect(Object.keys(base)).toContain('speed')
    expect(Object.keys(base)).toContain('hpRegenPerTurn')
    expect(Object.keys(base)).not.toContain('attackSpeed')
    expect(Object.keys(base)).not.toContain('movementSpeed')
    expect(Object.keys(base)).not.toContain('cooldownReduction')
    expect(Object.keys(base)).not.toContain('castSpeedPercent')
    expect(Object.keys(base)).not.toContain('hpRegenPerSecond')
  })

  it('INV-7 (Boundedness): speed cao bất thường vẫn bounded trong pipeline (không NaN/âm)', () => {
    const base = createBaseStats()
    const huge = calculateStats(base, [
      { id: 't:speed', sourceId: 't', sourceType: 'technique', stat: 'speed', flat: 1e9 },
    ])
    expect(Number.isFinite(huge.speed)).toBe(true)
    expect(huge.speed).toBeGreaterThan(0)
    // Speed không có trần metadata — chấp nhận theo spec (GAUGE_MAX
    // chỉ quan tâm tỉ lệ), nhưng KHÔNG BAO GIỜ âm từ pipeline chuẩn.
    const neg = calculateStats(base, [
      { id: 't:speed', sourceId: 't', sourceType: 'technique', stat: 'speed', flat: -50 },
    ])
    // 100 - 50 + dexterity 1×0.15 (attribute flat hoà chung Added pool).
    expect(neg.speed).toBeCloseTo(50.15, 5)
  })

  it('INV-8 (Determinism): modifier trỏ speed qua nhiều nguồn cộng dồn đúng Added pool', () => {
    const base = createBaseStats()
    const mods: StatModifier[] = [
      { id: 'a:1', sourceId: 'a', sourceType: 'buff', stat: 'speed', flat: 10 },
      { id: 'e:1', sourceId: 'e', sourceType: 'equipment', stat: 'speed', percent: 0.1 },
    ]
    const result = calculateStats(base, mods)
    // Added pool: 100 + 10 (equipment flat) + 0.15 (dexterity attribute
    // flat) = 110.15 → Increased ×1.1 = 121.165.
    expect(result.speed).toBeCloseTo(121.165, 5)
  })

  it('INV-9 (full Stats shape): deriveAttributeModifiers không sinh StatModifier nhắm key đã retire', () => {
    // calculateStats gọi deriveAttributeModifiers nội bộ — kết quả cuối
    // phải chứa ĐỦ 5 attribute dẫn xuất đúng, trong đó Thân Pháp/Dexterity
    // nhắm 'speed', Thần Thức/Intelligence KHÔNG nhắm gì đã retire.
    const base = createBaseStats()
    const result = calculateStats(base, [])
    // Thân Pháp 1: speed 100.15, accuracy +1.5, evasion +1.0, crit +0.05%.
    expect(result.accuracyRating).toBeCloseTo(100 + 1.5, 5)
    expect(result.evasionRate).toBeCloseTo(5 + 1, 5)
    expect(result.criticalRate).toBeCloseTo(0.05 * (1 + 0.0005), 5)
  })
})

describe('calculateEffectiveStats (R2 resolved→effective boundary)', () => {
  // Audit AR-02 probe: strength 100 + attack 10 raw → calculateStats
  // resolves to attack 70 (10 + 100×0.6). Feeding that resolved snapshot
  // back into calculateStats re-derived +60 (130). The effective boundary
  // must fold temp modifiers onto 70 without re-deriving.
  const RAW = createBaseStats({ strength: 100, attack: 10 })

  const ATTACK_BUFF: StatModifier = {
    id: 'b1',
    sourceId: 'buff',
    sourceType: 'buff',
    stat: 'attack',
    percent: 0.5,
  }

  it('does NOT re-derive attribute bonuses from an already-resolved base', () => {
    const resolved = calculateStats(RAW, [])
    expect(resolved.attack).toBe(70)

    // +50% applied to 70 once = 105. The old double-derivation path
    // yielded 130 (re-derived +60 then folded the buff).
    const effective = calculateEffectiveStats(resolved, [ATTACK_BUFF])
    expect(effective.attack).toBe(105)
  })

  it('resolved base passes through unchanged with no temp modifiers', () => {
    const resolved = calculateStats(RAW, [])

    expect(calculateEffectiveStats(resolved, [])).toEqual(resolved)
  })
})

