  scene.playerSpawnHandle = undefined
  scene.renderMode = 'flat'
  scene.lastKnownScreenPositions = new Map()
  scene.lastKnownGridPositions = new Map()
  scene.maxTrackedSourcePositions = 64
  scene.playerProfileId = 'mortal'
  scene.gridLeft = 0
