    expect(graphicsCreated.length).toBeGreaterThanOrEqual(4) // 2 cÅ© (destroyed) + 2 má»›i
  })

  it('flat mode: khÃ´ng táº¡o telegraph VFX (renderer legacy giá»¯ hÃ nh vi cÅ©)', () => {
