      // (onBattleStart Ã„â€˜ÃƒÂ£ tÃ„Æ’ng token).
      if (generation === this.backdropGeneration && !this.inBattle) {
        this.swapThanhVanBackdrop(desired)
      }
    })

    this.load.start()
  }

  /** HuÃ¡Â»Â· backdrop Thanh VÃƒÂ¢n hiÃ¡Â»â€¡n hÃƒÂ nh vÃƒÂ  dÃ¡Â»Â±ng lÃ¡ÂºÂ¡i tÃ¡Â»Â« texture Ã„â€˜ÃƒÂ£ load. */
  private swapThanhVanBackdrop(variant: ThanhVanVariant) {
    this.thanhVanVariant = variant

    commitThanhVanVariant(variant)

    this.backdrop?.destroy()

    this.backdrop = attachThanhVanBackdrop(
      this,
      variant,
      this.canvasWidth,
      this.canvasHeight,
      this.projection?.bounds().top ?? this.canvasHeight / 2,
    )

    this.usingArtBackdrop = true

    // Grid lines Ã„â€˜ÃƒÂ£ tÃ¡ÂºÂ¯t khi dÃƒÂ¹ng art backdrop Ã¢â‚¬â€ gÃ¡Â»Âi lÃ¡ÂºÂ¡i cho chÃ¡ÂºÂ¯c (khÃƒÂ´ng
    // vÃ¡ÂºÂ½ gÃƒÂ¬ khi usingArtBackdrop=true).
    this.redrawGridLines()
  }
}

import Phaser from 'phaser'
import type { EventBus } from '@/core/events/EventBus'
import { readOptionalGate } from '@/presentation/gate/PresentationGate'

const GROUND_COLOR = 0x1c1712
const SKY_COLOR = 0x11141c

// (2026-08-26) Art base Động Phủ chuyển hẳn về DOM: DongFuScene.vue mount
// thanh-van-dong-fu-base.png làm lớp nền cover-fit. Overlay DOM opaque
// đó đè lên canvas nên image trong scene này KHÔNG BAO GIỜ nhìn thấy —
// pipeline Phaser bị gỡ để không duy trì hai nguồn sự thật song song;
// skyRect/groundRect giữ lại chỉ làm fallback khi canvas trống.

const CHARACTER_HEIGHT_RATIO = 0.22

const GROUND_HEIGHT_RATIO = 0.1
// Ground CHẠM ĐÁY canvas — tính từ GROUND_HEIGHT_RATIO thay vì
// hardcode để luôn đúng bất kể sau này đổi độ dày ground.
const GROUND_Y_RATIO = 1 - GROUND_HEIGHT_RATIO

const PLAYER_ID = 'player'

// Cultivation gating (2026-08-14, rework 2026-08-20) — emit từ
// App.vue's tick() mỗi khi isFighting đổi trạng thái (KHÔNG còn nút
// bấm thủ công), xem ghi chú Player.ts's PlayerData.isCultivating.
interface CultivationStateEvent {
  isCultivating: boolean
}

const CULTIVATION_LABEL = 'Đang Tu Luyện'

// Sprite animation thật (2026-08-20, thay Rectangle placeholder) — 2
// atlas TexturePacker "multi-atlas" riêng (idle/cultivate), mỗi cái tự
// khai `image` trong chính file .json nên dùng load.multiatlas() thay
// vì load.atlas() (atlas() cần truyền tay 1 textureURL, multiatlas()
// tự đọc `image` field). 17 frame mỗi bên, đặt tên frame_000..frame_016
// (xác nhận qua asset-drop/idle.json, cultivate.json). 2 sheet có
// sourceSize khác nhau (idle 76x112, cultivate 128x132) — PHẢI tính
// lại width hiển thị theo đúng tỉ lệ từng sheet mỗi lần đổi animation,
// nếu không nhân vật sẽ méo hình lúc chuyển idle<->cultivate (xem
// updateSpriteDisplaySize()).
// Player visual profile (body-anchor plan §4.3) — Home dùng art MỚI
// theo profile: đứng = combat texture, kiết già = cultivate texture
// (static PNG thay animation atlas). Kích thước nguồn đọc LIVE từ
// texture (getSourceImage) nên đổi profile/texture không cần bảng số
// cứng nữa.
import {
  PLAYER_VISUAL_PROFILES,
  getCultivateTexture,
  resolvePlayerVisualProfileId,
  type PlayerVisualProfileId,
} from '@/presentation/art/PlayerVisualProfiles'

interface ResizeSize {
  width: number
  height: number
}

interface PlayerSprite {
  sprite: Phaser.GameObjects.Sprite

  label: Phaser.GameObjects.Text

  sitting: boolean

  profileId: PlayerVisualProfileId
}

/**
 * Combat UI Redesign — scene này giờ CHỈ render Động Phủ lúc idle (nền
 * trời/đất + nhân vật đứng/ngồi thiền tại HERO_HOME_X) — mọi thứ liên
 * quan chiến đấu thật (quái, missile, animation attack/critical/hit/
 * dodge/cast/death, camera framing) đã dời hẳn sang CombatScene.ts
 * (xem file đó). Scene này CHỈ còn 1 việc khi 'battle_start' tới:
 * chuyển hẳn qua CombatScene (`this.scene.start('CombatScene')`) —
 * KHÔNG tự vẽ combat nữa.
 *
 * Player KHÔNG di chuyển/nội suy gì trong scene này nữa (khác trước —
 * 'positions' chỉ emit lúc battle đang fighting, mà lúc đó scene này
 * đã bị stop() rồi) — vị trí/kích thước chỉ phụ thuộc canvas size
 * (applyBackgroundLayout) và trạng thái ngồi thiền (onCultivationChanged).
 *
 * Vẫn cần lắng nghe resize dù GameRoot.vue là 1 frame cố định + CSS
 * transform: container thật (clientWidth/Height) có thể là 0 đúng
 * lúc PhaserCanvas.vue khởi tạo Phaser.Game() (race với lúc trình
 * duyệt layout xong style tổ tiên) — PhaserCanvas.vue dùng
 * ResizeObserver để báo lại kích thước thật ngay sau đó.
 */
export class MainScene extends Phaser.Scene {
  private skyRect?: Phaser.GameObjects.Rectangle
  private groundRect?: Phaser.GameObjects.Rectangle

  private player?: PlayerSprite

  private eventBus?: EventBus
  private cultivationHandler = (event: CultivationStateEvent) => this.onCultivationChanged(event)
  private playerVisualProfileHandler = () => {
    if (!this.player) {
      return
    }

    const registryProfileId = readOptionalGate(this.registry, 'playerVisualProfileId')

    if (registryProfileId && PLAYER_VISUAL_PROFILES[registryProfileId]) {
      this.player.profileId = registryProfileId
    }

    this.refreshPlayerTexture()

    this.updateSpriteDisplaySize()
  }

  // Lifecycle listeners dùng handler ỔN ĐỊNH (audit H3, model theo
  // CombatScene) — ScaleManager là game-level nên anonymous callback
  // đăng ký mỗi create() KHÔNG bị gỡ bởi scene shutdown, TÍCH TỤY qua
  // các lần Home ↔ Combat (N listener chạy trên GameObjects đã destroy
  // mỗi resize). events.once đảm bảo shutdown handler tự gỡ đúng một
  // lần mà không tích lũy.
  private resizeHandler = (gameSize: ResizeSize) => {
    this.applyBackgroundLayout(gameSize.width, gameSize.height)
  }

  private shutdownHandler = () => {
    this.unsubscribeCombatEvents()
    this.scale.off('resize', this.resizeHandler)

    // Audit fix 2026-08-31 — null refs scene-scoped: (a) resize callback lỡ trúng
    // giữa shutdown không mutate dead GameObjects (applyBackgroundLayout đã có
    // null guard), (b) closure không giữ scene state khỏi GC qua các lần restart.
    this.skyRect = undefined
    this.groundRect = undefined
    this.player = undefined
    this.eventBus = undefined
  }

  private canvasWidth = 0
  private canvasHeight = 0
  private groundY = 0
  private characterY = 0
  private characterHeight = 0

  constructor() {
    super('MainScene')
  }

  preload() {
    // Eager combat preload removed (Task 13). Assets are ensured by AssetBundleManager before scene activation.
  }

  private initTransitionId = 0

  init(data?: { transitionId?: number }): void {
    if (data?.transitionId) {
      this.initTransitionId = data.transitionId
    }
  }

  create() {
    // Rectangle (Shape) trong Phaser mặc định setOrigin(0, 0) (neo góc
    // trên-trái) khác với Sprite/Image — phải tự setOrigin(0.5) lại,
    // không thì rect chỉ hiện đúng 1/4 phía dưới-phải của vị trí mong
    // muốn (đã thấy qua Playwright).
    this.skyRect = this.add.rectangle(0, 0, 0, 0, SKY_COLOR).setOrigin(0.5)
    this.groundRect = this.add.rectangle(0, 0, 0, 0, GROUND_COLOR).setOrigin(0.5)

    // Player visual profile (plan §4.3) — static texture theo profile;
    // KHÔNG còn animation atlas idle/cultivate ở scene này.
    const registryProfileId = readOptionalGate(this.registry, 'playerVisualProfileId')

    const profileId =
      registryProfileId && PLAYER_VISUAL_PROFILES[registryProfileId]
        ? registryProfileId
        : resolvePlayerVisualProfileId({})

    const sprite = this.add.sprite(0, 0, PLAYER_VISUAL_PROFILES[profileId].combatTextureKey)
    const label = this.add.text(0, 0, 'Player', { fontSize: '14px', color: '#ffffff' }).setOrigin(0.5, 0)

    this.player = { sprite, label, sitting: false, profileId }

    this.applyBackgroundLayout(this.scale.width, this.scale.height)

    this.scale.on('resize', this.resizeHandler)

    this.subscribeCombatEvents()

    const adapter = readOptionalGate(this.registry, 'sceneAdapter')
    adapter?.reportReady({ transitionId: this.initTransitionId })

    this.events.once('shutdown', this.shutdownHandler)
  }

  private applyBackgroundLayout(width: number, height: number) {
    if (!this.skyRect || !this.groundRect || !this.player) {
      return
    }

    this.canvasWidth = width
    this.canvasHeight = height

    this.groundY = height * GROUND_Y_RATIO
    const groundHeight = height * GROUND_HEIGHT_RATIO

    this.groundRect.setPosition(width / 2, this.groundY + groundHeight / 2)
    this.groundRect.width = width
    this.groundRect.height = groundHeight
    this.groundRect.updateDisplayOrigin()

    this.characterHeight = height * CHARACTER_HEIGHT_RATIO
    this.characterY = this.groundY - this.characterHeight / 2

    this.updateSpriteDisplaySize()
    this.positionPlayer()
  }

  // Static art theo profile — sourceSize đọc LIVE từ texture hiện hành
  // (mỗi profile/art có kích thước nguồn khác nhau), giữ characterHeight
  // cố định và tự suy width theo đúng tỉ lệ.
  private updateSpriteDisplaySize() {
    if (!this.player) {
      return
    }

    const sourceImage = this.textures.get(this.player.sprite.texture.key).getSourceImage()

    const sourceWidth = 'width' in sourceImage ? Number(sourceImage.width) : 1

    const sourceHeight = 'height' in sourceImage ? Number(sourceImage.height) : 1

    const width = this.characterHeight * (sourceWidth / Math.max(1, sourceHeight))

    this.player.sprite.setDisplaySize(width, this.characterHeight)
  }

  /** Texture key theo profile + pose đang hiển thị (plan §4.1 bảng). */
  private textureKeyForCurrentPose(): string {
    if (!this.player) {
      return PLAYER_VISUAL_PROFILES.mortal.combatTextureKey
    }

    const profile = PLAYER_VISUAL_PROFILES[this.player.profileId]

    return this.player.sitting
      ? getCultivateTexture(profile).key
      : profile.combatTextureKey
  }

  private refreshPlayerTexture() {
    if (!this.player) {
      return
    }

    const key = this.textureKeyForCurrentPose()

    if (this.textures.exists(key) && this.player.sprite.texture.key !== key) {
      this.player.sprite.setTexture(key)
    }
  }

  // Player luôn đứng giữa Home Scene (HERO_HOME_X = 0, xem BattleLane.ts)
  // — không di chuyển/nội suy gì ở đây nữa (khác lúc combat, xem class
  // doc), nên world 0 map thẳng vào chính giữa canvas. Chiều cao hiển
  // thị giờ LUÔN characterHeight (animation cultivate tự vẽ dáng ngồi
  // thật, không cần co rect giả như bản Rectangle cũ).
  private positionPlayer() {
    if (!this.player) {
      return
    }

    const screenX = this.canvasWidth / 2
    const screenY = this.groundY - this.characterHeight / 2

    this.player.sprite.setPosition(screenX, screenY)
    this.player.label.setPosition(screenX, screenY + this.characterHeight / 2 + 4)
  }

  private subscribeCombatEvents() {
    const eventBus = readOptionalGate(this.registry, 'eventBus')

    if (!eventBus) {
      return
    }

    this.eventBus = eventBus

    eventBus.on<CultivationStateEvent>('cultivation_changed', this.cultivationHandler)
    // Player visual profile bridge (plan §4.2) — đổi hình thái áp dụng
    // texture NGAY cho pose đang hiển thị.
    eventBus.on('player_visual_profile_changed', this.playerVisualProfileHandler)
  }

  private unsubscribeCombatEvents() {
    if (!this.eventBus) {
      return
    }

    this.eventBus.off<CultivationStateEvent>('cultivation_changed', this.cultivationHandler)
    this.eventBus.off('player_visual_profile_changed', this.playerVisualProfileHandler)
  }

  // Cultivation gating — đổi TEXTURE tĩnh sang art kiết già (theo profile
  // hiện hành) khi isCultivating=true, trả lại art đứng khi false (plan
  // §4.3: static swap thay animation atlas cũ).
  private onCultivationChanged(event: CultivationStateEvent) {
    if (!this.player) {
      return
    }

    this.player.sitting = event.isCultivating

    this.player.label.setText(event.isCultivating ? CULTIVATION_LABEL : 'Player')

    this.refreshPlayerTexture()

    this.updateSpriteDisplaySize()
    this.positionPlayer()
  }
}

// TranPhapCombatPreviewScene (Battlefield Slot spec, 2026-09-06) — thay
// TranPhapPreviewScene (2026-09-06, formation combat preview tooling):
// scene Phaser RIÊNG (Phaser.Game riêng, TextureManager riêng — không có
// nguy cơ đụng key dù dùng lại ĐÚNG PLACEHOLDER_SHEET_KEY), nhưng giờ
// implements CombatGridViewHost và dùng ĐÚNG CombatGridView mà combat
// thật dùng (spec §4) — thay vì tự viết lại logic sprite/animation. Vẽ
// lưới 3x3 standing-slot ở 2.5D perspective (isPerspective: true —
// Battlefield Perspective Panel 2026-09-06) + 2 lớp nền sky/ground cho
// art thật sau này. Tương tác kéo-thả KHÔNG nằm ở đây — canvas này thuần
// hiển thị, overlay HTML trong suốt (TranPhapPanel.vue, không đổi) mới là
// drop target thật.
// Standing-slot rework (2026-09-07): grid resolution reads the shared
// STANDING_SLOT_COUNT (3) from BattlefieldRegions — single source of
// truth shared with FormationPlacement/EnemySpawnPlacement. Removed:
// PREVIEW_CELL_SIZE, PREVIEW_GRID_SIZE, previewCellTopLeft() (dead code).
import Phaser from 'phaser'
import {
  PLACEHOLDER_SHEET_KEY,
  PLACEHOLDER_SHEET_URL,
  PLACEHOLDER_ATLAS_URL,
  PLACEHOLDER_FRAME_PREFIX,
  PLACEHOLDER_FRAME_SUFFIX,
  PLACEHOLDER_ZERO_PAD,
  PLACEHOLDER_FRAME_COUNT,
  PLACEHOLDER_FRAME_RATE,
  PLACEHOLDER_FRAME_WIDTH,
  PLACEHOLDER_FRAME_HEIGHT,
} from '@/presentation/art/CombatPresentationCatalogue'
import { PLAYER_VISUAL_PROFILES, type PlayerVisualProfile } from '@/presentation/art/PlayerVisualProfiles'
import type { PlayerVisualProfileId } from '@/core/player/PlayerVisualForm'
import type { FormationAssignmentsPayload } from '@/presentation/contracts/regionEvents'
import { PLAYER_ID } from './combat/combatConstants'
import type { BattleGridProjection } from '@/presentation/geometry/BattleGridProjection'
import { STANDING_SLOT_COUNT } from '@/core/battle/BattlefieldRegions'
import type { FormationSlotAssignment } from '@/core/player/Player'
import type { LaneIndex } from '@/core/battle/BattleLane'
import { CombatGridView } from './combat/combat-grid-view'
import type { CombatGridViewHost } from './combat/CombatGridViewHost'
import type { EntitySprite } from './combat/combatTypes'
import { FORMATION_ASSIGNMENTS_EVENT } from '@/presentation/contracts/regionEvents'
import {
  createFormationProjection,
  formationPerspectiveGeometry,
  FORMATION_CANVAS_HEIGHT,
  FORMATION_CANVAS_WIDTH,
  FORMATION_MIN_ROAD_HEIGHT,
} from '@/presentation/geometry/FormationCanvasSpec'

// Canvas size has ONE owner now (V9): FormationCanvasSpec, under
// presentation/geometry. It used to be declared here and again in
// TranPhapPanel.vue, kept in sync by a comment -- which is not a mechanism.
// Re-exported under the old local names so every use site below reads the
// same as before.
export const PANEL_WIDTH = FORMATION_CANVAS_WIDTH
export const PANEL_HEIGHT = FORMATION_CANVAS_HEIGHT
// Re-exported for existing consumers; the value's owner is FormationCanvasSpec.
export const PERSPECTIVE_MIN_ROAD_HEIGHT_PANEL = FORMATION_MIN_ROAD_HEIGHT

const PANEL_SKY_COLOR = 0x22283a
const PANEL_GROUND_COLOR = 0x1a1a1a

export const PREVIEW_IDLE_ANIMATION_KEY = 'tran-phap-preview-idle'

export class TranPhapCombatPreviewScene extends Phaser.Scene implements CombatGridViewHost {
  // Battlefield Perspective Panel (2026-09-06) — chuyển từ flat sang
  // perspective; combat-grid-view.ts's applySpriteSize()/positionSprite()
  // tự rẽ nhánh áp dụng applyEntityDepthScale() khi cờ này true (đã build
  // sẵn từ Part 1, không cần sửa gì thêm ở 2 hàm đó).
  readonly isPerspective = true
  projection: BattleGridProjection | undefined
  gridGraphics: Phaser.GameObjects.Graphics | undefined
  readonly usingArtBackdrop = false
  // arenaRect luôn undefined ở panel (chỉ combat thật's flat mode dùng nó
  // để CombatGridView.redrawGridLines() phân biệt flat/perspective qua
  // Boolean(this.host.arenaRect) — panel LUÔN perspective nên giữ
  // undefined là đúng, KHÔNG gán Rectangle nào vào field này).
  arenaRect: Phaser.GameObjects.Rectangle | undefined
  private skyLayer: Phaser.GameObjects.Rectangle | undefined
  private groundLayer: Phaser.GameObjects.Rectangle | undefined
  // 0.8 x cell -- reproduces the sprite/cell ratio of the pre-perspective
  // scene (setDisplaySize(cell * 0.8, cell * 0.8)); cell size now comes
  // from the projection at STANDING_SLOT_COUNT resolution, not a fixed
  // PREVIEW_CELL_SIZE constant.
  characterWidth = (PANEL_WIDTH / STANDING_SLOT_COUNT) * 0.8
  characterHeight = (PANEL_WIDTH / STANDING_SLOT_COUNT) * 0.8
  // Không dùng khi isPerspective=false (applySpriteSize() nhánh flat đọc
  // characterWidth/Height trực tiếp) — giữ 1:1 để tránh chia 0 nếu code
  // sau này lỡ đọc tới.
  // The authored box of the placeholder atlas every combatant in this panel
  // draws. Was `{ w: 1, h: 1 }` — a square, which forced a 1.0 aspect onto art
  // authored at 200x350 and rendered every figure ~1.8x too wide. Same class of
  // defect as the player's in `combat-grid-view.ts`, found by the same
  // measurement on 2026-09-11: what a sprite DRAWS and what SIZES it had drifted
  // apart.
  // The player's visual form is DERIVED from the entity (player store getter
  // `visualProfileId` -> payload below), not hardcoded — the same id CombatScene
  // receives through the registry gate. `mortal` is only the pre-payload
  // default; syncAssignments() updates it on every assignments event.
  private currentProfileId: PlayerVisualProfileId = 'mortal'

  private activeProfile(): PlayerVisualProfile {
    return PLAYER_VISUAL_PROFILES[this.currentProfileId] ?? PLAYER_VISUAL_PROFILES.mortal
  }

  get playerSourceSize(): { w: number; h: number } {
    return { ...this.activeProfile().combatSourceSize }
  }

  get playerProfile(): { combatTextureKey: string } {
    return this.activeProfile()
  }
  sprites = new Map<string, EntitySprite>()
  entityFootMinY = 0
  entityFootMaxY = 1
  // resetVisual() không dùng ở panel — Map rỗng thoả type, .get() luôn
  // undefined (đã guard sẵn trong CombatGridView.resetVisual()).
  readonly interpolations = new Map<string, unknown>()

  private gridView!: CombatGridView

  constructor() {
    super('TranPhapCombatPreviewScene')
  }

  fallbackSpriteTextureKey(_id: string): string | undefined {
    return PLACEHOLDER_SHEET_KEY
  }

  preload(): void {
    // Placeholder atlas stays: it is the declared fallback for combatants with
    // no registered presentation (companions have no art yet).
    this.load.atlas(PLACEHOLDER_SHEET_KEY, PLACEHOLDER_SHEET_URL, PLACEHOLDER_ATLAS_URL)

    // Real art, same source CombatScene uses: every profile's static combat
    // PNG (the sprite's base texture — the player renders static art in
    // combat, `playerUsesStaticTexture`, so no atlas is needed here).
    for (const profile of Object.values(PLAYER_VISUAL_PROFILES)) {
      if (!this.textures.exists(profile.combatTextureKey)) {
        this.load.image(profile.combatTextureKey, profile.combatTextureUrl.replace(/^\/+/, ''))
      }
    }
  }

  create(): void {
    this.gridView = new CombatGridView(this)

    // V10 / §3.6 surface two: the shell addresses the REGION, not this object.
    // Subscribing here rather than exposing a method means the shell can send
    // what this file names and nothing else. Unsubscribed on shutdown, because
    // the emitter is the Game's and outlives a scene restart.
    this.game.events.on(FORMATION_ASSIGNMENTS_EVENT, this.assignmentsHandler)
    this.events.once('shutdown', () => {
      this.game.events.off(FORMATION_ASSIGNMENTS_EVENT, this.assignmentsHandler)
    })

    const geometry = formationPerspectiveGeometry()

    // 2 lớp nền phẳng (sky/ground) — KHÔNG dùng attachBattlefieldBackdrop()
    // của combat thật (sao/trăng/núi/đá quá cầu kỳ cho panel test, và
    // cũng hardcode GRID_ROW_COUNT/COLUMN_COUNT). Đặt tên rõ ràng để sau
    // này thay Rectangle bằng Image thật chỉ cần đổi loại GameObject, giữ
    // nguyên vị trí gọi.
    this.skyLayer = this.add.rectangle(0, 0, PANEL_WIDTH, geometry.horizonY, PANEL_SKY_COLOR).setOrigin(0, 0)
    this.groundLayer = this.add
      .rectangle(0, geometry.horizonY, PANEL_WIDTH, geometry.roadHeight, PANEL_GROUND_COLOR)
      .setOrigin(0, 0)

    // Same factory the shell calls (FormationCanvasSpec) — the five parameters
    // are declared once and neither layer restates them (§3.6.2).
    this.projection = createFormationProjection()
    this.gridGraphics = this.add.graphics()
    this.gridView.redrawGridLines()

    if (!this.anims.exists(PREVIEW_IDLE_ANIMATION_KEY)) {
      this.anims.create({
        key: PREVIEW_IDLE_ANIMATION_KEY,
        frames: this.anims.generateFrameNames(PLACEHOLDER_SHEET_KEY, {
          prefix: PLACEHOLDER_FRAME_PREFIX,
          suffix: PLACEHOLDER_FRAME_SUFFIX,
          start: 0,
          end: PLACEHOLDER_FRAME_COUNT - 1,
          zeroPad: PLACEHOLDER_ZERO_PAD,
        }),
        frameRate: PLACEHOLDER_FRAME_RATE,
        repeat: -1,
      })
    }

  }

  /**
   * Diff theo combatantId qua chính CombatGridView.getOrCreateSprite() —
   * KHÔNG tự viết lại logic tạo/xoá sprite: entity còn trong assignment
   * mới → getOrCreateSprite() no-op nếu id đã có trong this.sprites (chỉ
   * reposition), animation KHÔNG bị ngắt/reset (đây chính là fix cho bug
   * "animation reset về 0 mỗi lần kéo-thả 1 entity", 2026-09-06); entity
   * biến mất → destroyEntitySprite() qua CombatGridView; entity mới xuất
   * hiện → getOrCreateSprite() tạo sprite mới, play() từ frame 0 (đúng —
   * chưa từng animate trong panel này).
   */
  private readonly assignmentsHandler = (
    payload: FormationSlotAssignment[] | FormationAssignmentsPayload,
  ) => this.syncAssignments(payload)

  syncAssignments(payload: FormationSlotAssignment[] | FormationAssignmentsPayload): void {
    // Phaser event payloads are untyped at runtime — accept the current
    // snapshot shape and the legacy bare array, ignore anything else.
    let assignments: FormationSlotAssignment[]
    let profileId: PlayerVisualProfileId | undefined

    if (Array.isArray(payload)) {
      assignments = payload
    } else if (payload && Array.isArray(payload.assignments)) {
      assignments = payload.assignments
      profileId = payload.playerProfileId
    } else {
      return
    }

    if (profileId && PLAYER_VISUAL_PROFILES[profileId]) {
      this.currentProfileId = profileId
    }

    const nextIds = new Set(assignments.map((a) => a.combatantId))

    for (const [id, sprite] of this.sprites) {
      if (!nextIds.has(id)) {
        this.gridView.destroyEntitySprite(sprite)
        this.sprites.delete(id)
      }
    }

    for (const assignment of assignments) {
      // The player's visual form can change while the panel is open (the
      // panel re-dispatches on player.visualProfileId changes). Rebuild the
      // sprite so it picks up the new profile PNG — same outcome as
      // CombatScene.applyPlayerVisualProfile's setTexture + re-size.
      if (assignment.combatantId === PLAYER_ID) {
        const existing = this.sprites.get(PLAYER_ID)

        if (
          existing &&
          existing.kind === 'sprite' &&
          (existing.rect as Phaser.GameObjects.Sprite).texture.key !== this.playerProfile.combatTextureKey
        ) {
          this.gridView.destroyEntitySprite(existing)
          this.sprites.delete(PLAYER_ID)
        }
      }

      const sprite = this.gridView.getOrCreateSprite(
        assignment.combatantId,
        0x4caf50,
        assignment.combatantId,
        assignment.row as LaneIndex,
      )

      // Cell->cell drags reuse the existing sprite: getOrCreateSprite's
      // early-return keeps the ORIGINAL row, and positionSprite projects
      // gridToScreen(sprite.row, column) — refresh it or the unit draws in
      // its old cell while the DOM grid shows the new one.
      sprite.row = assignment.row as LaneIndex

      // The player renders the static profile PNG exactly like CombatScene
      // (playerUsesStaticTexture — no idle clip); everyone else keeps the
      // placeholder idle until they have authored art.
      if (
        sprite.kind === 'sprite' &&
        assignment.combatantId !== PLAYER_ID &&
        !(sprite.rect as Phaser.GameObjects.Sprite).anims.isPlaying
      ) {
        ;(sprite.rect as Phaser.GameObjects.Sprite).play(PREVIEW_IDLE_ANIMATION_KEY)
      }

      this.gridView.positionSprite(sprite, assignment.column)
    }
  }
}

// @vitest-environment jsdom
// 6A-T4 (2026-09-01) — PlayerHudLayer: HP/MP/Kiếm bars + labels vẽ
// trong canvas, flexible layout theo viewport (AGENTS.md UI rule),
// ẩn MP khi maxMp<=0, ẩn Kiếm khi max<=0, update HP từ event values.
import { describe, expect, it } from 'vitest'
import { PlayerHudLayer, HUD_MARGIN, HUD_HP_WIDTH, HUD_SUB_WIDTH } from './PlayerHudLayer'

interface FakeRect {
  x: number
  y: number
  width: number
  scaleX: number
  visible: boolean
  setPosition(x: number, y: number): FakeRect
  setDisplaySize(w: number, h: number): FakeRect
  setVisible(v: boolean): FakeRect
  setDepth(d: number): FakeRect
  setStrokeStyle(...a: unknown[]): FakeRect
  setOrigin(...a: unknown[]): FakeRect
  destroy(): void
}

interface FakeText {
  text: string
  x: number
  y: number
  visible: boolean
  setPosition(x: number, y: number): FakeText
  setOrigin(...a: unknown[]): FakeText
  setDepth(d: number): FakeText
  setVisible(v: boolean): FakeText
  destroy(): void
}

function makeFakeRect(width: number): FakeRect {
  const rect = {
    x: 0,
    y: 0,
    width,
    scaleX: 1,
    visible: true,
    setPosition(x: number, y: number) {
      rect.x = x
      rect.y = y
      return rect
    },
    setDisplaySize(w: number, _h: number) {
      rect.width = w
      return rect
    },
    setVisible(v: boolean) {
      rect.visible = v
      return rect
    },
    setDepth() {
      return rect
    },
    setStrokeStyle() {
      return rect
    },
    setOrigin() {
      return rect
    },
    destroy() {},
  } as unknown as FakeRect

  return rect
}

function makeFakeText(initial: string): FakeText {
  const text = {
    text: initial,
    x: 0,
    y: 0,
    visible: true,
    setPosition(x: number, y: number) {
      text.x = x
      text.y = y
      return text
    },
    setOrigin() {
      return text
    },
    setDepth() {
      return text
    },
    setVisible(v: boolean) {
      text.visible = v
      return text
    },
    destroy() {},
  } as unknown as FakeText

  return text
}

function makeScene() {
  const rects: FakeRect[] = []
  const texts: FakeText[] = []

  return {
    add: {
      rectangle: () => {
        const rect = makeFakeRect(0)

        rects.push(rect)

        return rect
      },
      text: (_x: number, _y: number, content: string) => {
        const text = makeFakeText(content)

        texts.push(text)

        return text
      },
    },
    rects,
    texts,
  }
}

type SceneLike = ReturnType<typeof makeScene>

describe('PlayerHudLayer — in-canvas HUD (6A-T4)', () => {
  it('layout: HP bar neo góc trái-dưới theo viewport — resize không hardcode', () => {
    const scene = makeScene()
    const hud = new PlayerHudLayer(scene as never, { width: 800, height: 600 })

    hud.layout(800, 600)

    // Label HP ở trên bar; bar Y = height - margin - barH - label offset.
    // Chỉ assert ràng buộc vị trí (không cứng số tuyệt đối ngoài hằng).
    expect(hud.hpFill.y).toBeLessThanOrEqual(600 - HUD_MARGIN)
    expect(hud.hpFill.y).toBeGreaterThan(600 - HUD_MARGIN - 60)
    expect(hud.hpFill.x).toBeGreaterThanOrEqual(HUD_MARGIN)

    // Resize nhỏ hơn → vị trí dời theo height mới (flexible rule).
    hud.layout(600, 360)

    expect(hud.hpFill.y).toBeLessThanOrEqual(360 - HUD_MARGIN)
    expect(hud.hpFill.y).toBeGreaterThan(360 - HUD_MARGIN - 60)
  })

  it('updateHp: fill ratio đúng + label số', () => {
    const scene = makeScene()
    const hud = new PlayerHudLayer(scene as never, { width: 800, height: 600 })

    hud.updateHp(50, 100)

    expect(hud.hpFill.scaleX).toBeCloseTo(0.5, 5)
    expect(hud.hpLabel.text).toContain('50')
    expect(hud.hpLabel.text).toContain('100')
  })

  it('updateMp: maxMp <= 0 → ẩn (Phàm/Kiếm Tu không có pool MP)', () => {
    const scene = makeScene()
    const hud = new PlayerHudLayer(scene as never, { width: 800, height: 600 })

    hud.updateMp(0, 0)

    expect(hud.mpGroupVisible).toBe(false)

    hud.updateMp(20, 50)

    expect(hud.mpGroupVisible).toBe(true)
    expect(hud.mpFill.scaleX).toBeCloseTo(0.4, 5)
  })

  it('updateKiem: max <= 0 → ẩn; có resource → hiện + label custom', () => {
    const scene = makeScene()
    const hud = new PlayerHudLayer(scene as never, { width: 800, height: 600 })

    hud.updateKiem(0, 0, 'Kiếm Ý T.2')

    expect(hud.kiemGroupVisible).toBe(false)

    hud.updateKiem(30, 100, 'Kiếm Ý T.2')

    expect(hud.kiemGroupVisible).toBe(true)
    expect(hud.kiemLabel.text).toContain('Kiếm Ý T.2')
    expect(hud.kiemFill.scaleX).toBeCloseTo(0.3, 5)
  })

  it('destroy: mọi rect/text được destroy (không leak giữa trận)', () => {
    const scene = makeScene()
    const hud = new PlayerHudLayer(scene as never, { width: 800, height: 600 })

    const rectCount = scene.rects.length
    const textCount = scene.texts.length

    expect(rectCount).toBeGreaterThan(0)
    expect(textCount).toBeGreaterThan(0)

    hud.destroy()
  })

  it('kích thước flexible: HP width hằng số, sub bars nhỏ hơn (không cứng theo màn hình)', () => {
    const scene = makeScene()
    const hud = new PlayerHudLayer(scene as never, { width: 1280, height: 720 })

    hud.layout(1280, 720)

    expect(hud.hpWidth).toBe(HUD_HP_WIDTH)
    expect(hud.subWidth).toBe(HUD_SUB_WIDTH)
  })
})

// 6A-T4 (2026-09-01, spec docs/superpowers/specs/2026-09-01-combat-scene-
// ui-redesign-design.md §3) — HP/MP/Kiếm player vẽ TRONG canvas Phaser,
// thay 3 DOM bars (Status/Event/Control). Minimalism/Swiss: không khung
// nền, bar mảnh 2 lớp Rectangle theo pattern enemy HP bar, ink tokens.
//
// Flexible rule (AGENTS.md): mọi vị trí tính từ viewport width/height
// qua layout() — resize gọi lại layout, KHÔNG hardcode px màn hình dev.
import Phaser from 'phaser'
import { DEPTH_OVERLAY_UI } from '@/game/support/BattleLayers'
import { formatNumber } from '@/core/format/NumberFormatter'

import {
  PLAYER_HUD_BG_COLOR,
  PLAYER_HUD_HP_COLOR,
  PLAYER_HUD_MP_COLOR,
  PLAYER_HUD_KIEM_COLOR,
  PLAYER_HUD_LABEL_COLOR,
  PLAYER_HUD_STROKE_COLOR,
  ENEMY_HP_BAR_HEIGHT,
} from './combatConstants'

export const HUD_MARGIN = 16
export const HUD_HP_WIDTH = 180
export const HUD_HP_HEIGHT = 6
export const HUD_SUB_WIDTH = 140
export const HUD_SUB_HEIGHT = 4
export const HUD_GAP = 8

const HUD_LABEL_FONT_SIZE = '12px'
const HUD_SUB_LABEL_FONT_SIZE = '10px'
const LABEL_ABOVE_BAR = 4

interface HudRectGroup {
  background: Phaser.GameObjects.Rectangle
  fill: Phaser.GameObjects.Rectangle
  label: Phaser.GameObjects.Text
  width: number
  height: number
  visible: boolean
}

export class PlayerHudLayer {
  private readonly scene: Phaser.Scene

  private viewport = { width: 0, height: 0 }

  private hpGroup!: HudRectGroup

  private mpGroup!: HudRectGroup

  private kiemGroup!: HudRectGroup

  private destroyed = false

  constructor(scene: Phaser.Scene, viewport: { width: number; height: number }) {
    this.scene = scene
    this.viewport = viewport

    this.hpGroup = this.createGroup(HUD_HP_WIDTH, HUD_HP_HEIGHT, `${HUD_LABEL_FONT_SIZE}`, true)
    this.mpGroup = this.createGroup(HUD_SUB_WIDTH, HUD_SUB_HEIGHT, HUD_SUB_LABEL_FONT_SIZE, false)
    this.kiemGroup = this.createGroup(HUD_SUB_WIDTH, HUD_SUB_HEIGHT, HUD_SUB_LABEL_FONT_SIZE, false)

    this.layout(viewport.width, viewport.height)
  }

  /** Test accessors — vị trí/kích thước hiện tại (flexible assertions). */
  get hpFill(): Phaser.GameObjects.Rectangle {
    return this.hpGroup.fill
  }

  get hpLabel(): Phaser.GameObjects.Text {
    return this.hpGroup.label
  }

  get mpFill(): Phaser.GameObjects.Rectangle {
    return this.mpGroup.fill
  }

  get mpGroupVisible(): boolean {
    return this.mpGroup.visible
  }

  get kiemFill(): Phaser.GameObjects.Rectangle {
    return this.kiemGroup.fill
  }

  get kiemLabel(): Phaser.GameObjects.Text {
    return this.kiemGroup.label
  }

  get kiemGroupVisible(): boolean {
    return this.kiemGroup.visible
  }

  get hpWidth(): number {
    return this.hpGroup.width
  }

  get subWidth(): number {
    return this.mpGroup.width
  }

  /**
   * Vị trí tính từ viewport: cụm HP neo góc trái-DƯỚI (cách HUD_MARGIN),
   * MP ngay dưới HP (cách HUD_GAP), Kiếm dưới MP. bottom inset = 0 từ
   * 6A-T3 nên không cần chừa chỗ bar DOM nào.
   */
  layout(width: number, height: number): void {
    this.viewport = { width, height }

    const leftX = HUD_MARGIN
    const hpBarY = height - HUD_MARGIN - HUD_HP_HEIGHT
    const sub1Y = hpBarY - HUD_GAP - HUD_SUB_HEIGHT
    const sub2Y = sub1Y - HUD_GAP - HUD_SUB_HEIGHT

    this.positionGroup(this.hpGroup, leftX, hpBarY, HUD_HP_WIDTH, HUD_HP_HEIGHT)
    this.positionGroup(this.mpGroup, leftX, sub1Y, HUD_SUB_WIDTH, HUD_SUB_HEIGHT)
    this.positionGroup(this.kiemGroup, leftX, sub2Y, HUD_SUB_WIDTH, HUD_SUB_HEIGHT)
  }

  updateHp(current: number, max: number): void {
    this.updateGroup(this.hpGroup, current, max, `${formatNumber(Math.ceil(current))} / ${formatNumber(Math.max(0, Math.round(max)))}`)
  }

  updateMp(current: number, max: number): void {
    this.updateGroup(this.mpGroup, current, max, max > 0 ? `Linh Lực ${formatNumber(Math.floor(current))} / ${formatNumber(Math.max(0, Math.round(max)))}` : '')
  }

  updateKiem(current: number, max: number, label: string): void {
    this.updateGroup(this.kiemGroup, current, max, max > 0 ? label : '')
  }

  setVisible(visible: boolean): void {
    const groups = [this.hpGroup, this.mpGroup, this.kiemGroup]

    for (const group of groups) {
      this.setGroupVisible(group, visible && (group === this.hpGroup || group.visible))
    }
  }

  destroy(): void {
    if (this.destroyed) {
      return
    }

    this.destroyed = true

    for (const group of [this.hpGroup, this.mpGroup, this.kiemGroup]) {
      group.background.destroy()
      group.fill.destroy()
      group.label.destroy()
    }
  }

  private createGroup(
    width: number,
    height: number,
    fontSize: string,
    initialVisible: boolean,
  ): HudRectGroup {
    const depth = DEPTH_OVERLAY_UI + 2

    const background = this.scene.add
      .rectangle(0, 0, width, height, PLAYER_HUD_BG_COLOR)
      .setStrokeStyle(1, PLAYER_HUD_STROKE_COLOR)
      .setOrigin(0, 0.5)
      .setDepth(depth)

    const fill = this.scene.add
      .rectangle(0, 0, width, height, PLAYER_HUD_HP_COLOR)
      .setOrigin(0, 0.5)
      .setDepth(depth + 1)

    const label = this.scene.add
      .text(0, 0, '', {
        fontSize,
        color: PLAYER_HUD_LABEL_COLOR,
      })
      .setOrigin(0, 1)
      .setDepth(depth)

    const group: HudRectGroup = {
      background,
      fill,
      label,
      width,
      height,
      visible: initialVisible,
    }

    this.setGroupVisible(group, initialVisible)

    return group
  }

  private positionGroup(group: HudRectGroup, x: number, barY: number, width: number, height: number): void {
    group.background.setPosition(x, barY).setDisplaySize(width, height)
    group.fill.setPosition(x, barY).setDisplaySize(width, height)
    group.label.setPosition(x, barY - height / 2 - LABEL_ABOVE_BAR)

    group.width = width
    group.height = height
  }

  private updateGroup(group: HudRectGroup, current: number, max: number, labelText: string): void {
    const hasPool = Number.isFinite(max) && max > 0

    this.setGroupVisible(group, hasPool)

    if (!hasPool) {
      return
    }

    const ratio = Math.min(1, Math.max(0, current / max))

    group.fill.scaleX = ratio
    group.label.text = labelText
  }

  private setGroupVisible(group: HudRectGroup, visible: boolean): void {
    group.visible = visible
    group.background.setVisible(visible)
    group.fill.setVisible(visible)
    group.label.setVisible(visible)
  }
}

// Re-export cho constants import ở test.
export {
  PLAYER_HUD_BG_COLOR,
  PLAYER_HUD_HP_COLOR,
  PLAYER_HUD_MP_COLOR,
  PLAYER_HUD_KIEM_COLOR,
}

// combat-snapshot-reconcile (Wave-3 large-file split) — tach tu CombatScene.ts.
// Snapshot→sprite reconciliation: applies 'positions' (legacy real-time) and
// 'turn_battle_entity_snapshot' (turn engine) events to the scene's sprite
// set — spawn telegraph gating, create/update/remove, HP bars, position
// interpolation targets. All state (sprites/entityVisual/knownIds/pending
// positions/telegraph fields) stays on the scene as Internal module-boundary
// members; this module carries the reconcile mechanism only.
import type {
  BattlePositionsEvent,
} from '@/core/battle/BattleEvents'
import type { LaneIndex } from '@/core/battle/BattleLane'
import type { TurnBattleEntitySnapshotEvent } from '@/core/battle/turn/TurnActionPresentationEvents'
import { spawnEnemySpawnVfx } from '@/game/support/EnemySpawnVfx'

import type { CombatScene } from '../CombatScene'
import type { SpawnVfxSnapshot } from './combat-vfx-spawner'
import { planCombatantSpriteReconciliation } from './combat-entity-reconciliation'
import {
  ENEMY_COLOR,
  MAX_SEGMENT_DURATION_MS,
  PLAYER_COLOR,
  PLAYER_ID,
} from './combatConstants'

export class CombatSnapshotReconcile {
  constructor(private readonly scene: CombatScene) {}

  // Combat Grid Rework — COALESCE: nhiều event 'positions' đồng bộ trong
  // 1 frame chỉ giữ snapshot MỚI NHẤT, apply ĐÚNG MỘT lần trong update().
  // Cadence = khoảng cách giữa 2 SNAPSHOT (lastSnapshotAt), clamp
  // [MIN_SEGMENT_DURATION_MS, MAX_SEGMENT_DURATION_MS].
  onPositions(event: BattlePositionsEvent) {
    const scene = this.scene
    const now = scene.time.now

    // 6A-T5 — HUD HP fast-path từ positions (khi chưa có vitals event).
    scene.playerHud?.updateHp(event.playerCurrentHp, event.playerMaxHp)

    if (scene.lastSnapshotAt !== undefined) {
      scene.pendingCadence = Math.min(
        MAX_SEGMENT_DURATION_MS,
        Math.max(50, now - scene.lastSnapshotAt),
      )
    }

    scene.lastSnapshotAt = now
    scene.pendingPositions = event
  }

  applyPendingPositions(event: BattlePositionsEvent) {
    const scene = this.scene

    // Spawn VFX reconcile TRƯỚC enemy sprites: id rời spawningEnemies =
    // materialize xong → đánh dấu để sprite mới tạo dưới đây fade-in.
    scene.reconcileSpawnVfx(event)

    // Player spawn reconcile (plan §12.2): entityVisual.playerMaterialized false =
    // ẩn sprite; playerSpawn hiện = vẽ telegraph tại projected cell;
    // telegraph biến mất = materialize → hiện sprite với fade-in.
    scene.reconcilePlayerSpawn(event)

    scene.reconcileEnemySprites(event.enemies)

    // Grid fallback cache (plan §7.1 mức 3) — ô cuối cùng theo snapshot
    // positions, dùng khi cả sprite lẫn screen cache đã mất.
    for (const enemy of event.enemies) {
      scene.trackSourceGridPosition(enemy.id, enemy.row, enemy.x)
    }

    const playerSprite = scene.sprites.get(PLAYER_ID)

    if (playerSprite && playerSprite.row !== event.playerRow) {
      // Teleport qua snapshot (fallback khi lỡ miss event riêng):
      // snap tức thời, KHÔNG tween qua hàng trung gian.
      playerSprite.row = event.playerRow
      scene.positionInterp.snapInterpolationTarget(PLAYER_ID, event.playerX)
      scene.positionSprite(playerSprite, event.playerX)
    }

    scene.positionInterp.setInterpolationTarget(
      PLAYER_ID,
      event.playerX,
      scene.pendingCadence,
      scene.lastSnapshotAt,
    )

    for (const enemy of event.enemies) {
      scene.positionInterp.setInterpolationTarget(
        enemy.id,
        enemy.x,
        scene.pendingCadence,
        scene.lastSnapshotAt,
      )
    }
  }

  // Combat Art Pipeline Task 5 (2026-09-05) — thay thế snapshot ĐÔNG CỨNG
  // (chỉ seed một lần từ 'positions' của legacy engine lúc battle start) bằng
  // dữ liệu SỐNG mỗi fixed step từ turn engine (xem TurnActionPresentationEvents.ts).
  // Tổng quát hoá đúng tinh thần reconcileEnemySprites() cho CẢ HAI phe.
  onTurnBattleEntitySnapshot(event: TurnBattleEntitySnapshotEvent) {
    // Turn-Based Wave Redesign (2026-09-06) — countdown reconcile PHẢI
    // chạy TRƯỚC reconcileCombatantSprites('player', ...): lần đầu 1
    // player/companion id xuất hiện trong event.players (ngay từ tick đầu
    // countdown, KHÔNG như enemy phải chờ pending), nhánh 'create' của
    // reconcileCombatantSprites() sẽ setVisible(true) ngay — cần
    // entityVisual.pending đã có id đó SẴN để nhánh 'create' biết
    // giữ ẩn (xem nhánh 'create').
    this.reconcileTurnCountdownSpawn(event)

    // Turn-Based Wave Redesign (2026-09-06) — enemy wave telegraph: tái dùng
    // đúng reconcileSpawnVfx() của legacy qua SpawnVfxSnapshot (Task 6) —
    // id biến mất khỏi pendingEnemySpawns = materialize → entityVisual.materializing
    // đánh dấu TRƯỚC khi reconcileCombatantSprites tạo sprite (thứ tự giống
    // applyPendingPositions() của legacy: spawn VFX reconcile chạy trước
    // sprite reconcile) để nhánh 'create' kịp consume fade-in materialize.
    this.scene.reconcileSpawnVfx({
      spawningEnemies: event.pendingEnemySpawns.map((pending) => ({
        id: pending.id,
        row: pending.row as LaneIndex,
        column: pending.column,
        progress: pending.progress,
        isBoss: pending.isBoss,
        presetId: pending.presetId,
      })),
    })

    this.reconcileCombatantSprites('player', event.players, PLAYER_COLOR)
    this.reconcileCombatantSprites('enemy', event.enemies, ENEMY_COLOR)
  }

  /**
   * Turn-Based Wave Redesign (2026-09-06) — telegraph đếm 3→2→1 cho CẢ
   * party (player + companion). countdownProgress undefined = countdown
   * hết → flush mọi handle còn treo + hiện sprite từng id. KHÔNG đụng
   * reconcilePlayerSpawn() (legacy real-time).
   *
   * 2026-09-12 fix (user report: player art already on the field before
   * its spawn telegraph ran) — 'intro' ALSO has countdownProgress ===
   * undefined, but it means "countdown has not started", not "countdown
   * done". An intro snapshot used to fall straight into the flush branch
   * (empty pending set -> no-op), then the 'create' branch of
   * reconcileCombatantSprites() saw the id as not pending and called
   * setVisible(true) — the player stayed visible through intro and under
   * its own countdown telegraph. The phase field on the snapshot contract
   * separates the two meanings: intro marks pending so 'create' stays
   * hidden; only the flush reveals.
   */
  reconcileTurnCountdownSpawn(event: TurnBattleEntitySnapshotEvent) {
    const scene = this.scene

    if (event.phase === 'intro') {
      // Pre-combat intro: no telegraph runs yet, but ids already appear in
      // the snapshot — mark them pending so the 'create' branch keeps them
      // hidden until the countdown-end flush. Enemies are marked too: a
      // direct startBattle() may carry pre-materialized enemies in
      // battle.enemies, and "both sides spawn first, then appear" means
      // they stay hidden for the same intro window.
      scene.entityVisual.markPending(event.players.map((state) => state.id))
      scene.entityVisual.markPending(event.enemies.map((state) => state.id))

      return
    }

    if (event.countdownProgress === undefined) {
      // Countdown ended — the gating window is over: complete every hanging
      // handle (materialize flash), then reveal the union of still-pending
      // ids and every materialized id in the snapshot. Pending ids can lack
      // a handle (projection not ready when their telegraph would have
      // spawned, or marked during 'intro') but must still materialize; and
      // a scene that rebinds mid-'fighting' (never saw the gating window)
      // reveals its party through the snapshot ids.
      for (const handle of scene.turnCountdownSpawnVfxHandles.values()) {
        handle.complete()
      }

      scene.entityVisual.revealPending(
        [...event.players, ...event.enemies]
          .filter((state) => state.alive)
          .map((state) => state.id),
      )

      scene.turnCountdownSpawnVfxHandles.clear()

      // Reset interpolation state alongside the handles it drives — a
      // refight's countdown must start its telegraph from 0, not resume
      // from the previous battle's last shown value.
      scene.telegraph.reset()

      return
    }

    // Enemies already materialized in the snapshot (a direct startBattle()
    // that skipped 'intro') join the same hidden window — marked pending so
    // the 'create' branch keeps them hidden until the flush. They get no
    // countdown handle: the enemy telegraph belongs to the wave path
    // (pendingEnemySpawns), these simply materialize at flush.
    scene.entityVisual.markPending(event.enemies.map((state) => state.id))

    for (const player of event.players) {
      scene.entityVisual.markPending([player.id])

      if (scene.turnCountdownSpawnVfxHandles.has(player.id)) {
        continue
      }

      if (!scene.projection) {
        continue
      }

      const handle = spawnEnemySpawnVfx({
        scene,
        projection: scene.projection,
        row: player.row as LaneIndex,
        column: player.column,
        presetId: 'player_spawn',
        uprightDepth: scene.resolveUprightVfxDepth({
          row: player.row as LaneIndex,
          column: player.column,
        }),
      })

      scene.turnCountdownSpawnVfxHandles.set(player.id, handle)
    }

    // The whole party shares ONE countdown progress — set the chase target
    // once per snapshot rather than once per player (telegraph.setTarget is
    // itself a no-op when the target hasn't actually changed).
    scene.telegraph.setTarget(event.countdownProgress)
  }

  reconcileCombatantSprites(
    side: 'player' | 'enemy',
    states: TurnBattleEntitySnapshotEvent['players'],
    color: number,
  ) {
    const scene = this.scene
    const knownIds =
      side === 'player' ? scene.knownTurnBattlePlayerIds : scene.knownTurnBattleEnemyIds
    const actions = planCombatantSpriteReconciliation(knownIds, states)

    for (const action of actions) {
      if (action.type === 'create') {
        // Fix round 1 (Task 5 review, Important) — dùng name/isBoss THẬT từ
        // schema (TurnActionPresentationEvents.toVisualState()) thay vì
        // hardcode false/id. Đây chính là đường tạo sprite ĐẦU TIÊN cho enemy
        // các wave sau wave 1 (getOrCreateSprite no-op nếu id đã có trong
        // scene.sprites) — hardcode isBoss:false ở đây từng làm mất luôn HP
        // bar boss (1.45x width + BOSS_HP_FILL_COLOR, xem combat-grid-view.ts)
        // cho đúng những boss mà task này sinh ra để fix.
        // `action.state.row` đến từ entityGridPosition() — nguồn DUY NHẤT
        // sản xuất LaneIndex hợp lệ cho luồng turn-based này, nên cast an
        // toàn ở biên; không thêm runtime validation (per brief).
        const sprite = scene.getOrCreateSprite(
          action.state.id,
          color,
          action.state.name,
          action.state.row as LaneIndex,
          { currentHp: action.state.currentHp, maxHp: action.state.maxHp, isBoss: action.state.isBoss },
        )

        scene.positionInterp.snapInterpolationTarget(action.state.id, action.state.column)
        scene.positionSprite(sprite, action.state.column, action.state.id)

        // Bug fix (2026-09-06, user report "không thấy nhân vật nào trong
        // combat") — sprite Player được tạo ẨN ở create() (setVisible(false),
        // chờ event 'positions' LEGACY gọi reconcilePlayerSpawn() để hiện lại
        // sau materialize). Turn-based combat không còn tick legacy
        // BattleSystem (xem TurnActionPresentationEvents.ts) nên event đó
        // không bao giờ tới nữa — sprite kẹt vô hình vĩnh viễn. Snapshot
        // turn-based tự lo hiện sprite ngay khi id đó lần đầu xuất hiện.
        // Turn-Based Wave Redesign (2026-09-06) — party countdown telegraph:
        // a pending id in entityVisual means pre-combat gating is NOT
        // finished — keep the sprite hidden; reconcileTurnCountdownSpawn()
        // flips it visible at the countdown-end flush (see that function).
        // The set holds event.players during countdown plus BOTH sides
        // during 'intro' (a direct startBattle() may carry already-
        // materialized enemies — same hidden window as the party); wave
        // enemies come through pendingEnemySpawns instead and never enter
        // this set, so their behaviour is unchanged.
        scene.entityVisual.applyGating(action.state.id, sprite)

        // Materialize từ telegraph (Turn-Based Wave Redesign, 2026-09-06) —
        // đúng cơ chế đã dùng cho legacy enemy (reconcileEnemySprites()).
        scene.entityVisual.consumeMaterializing(action.state.id, sprite)

        if (action.state.id === PLAYER_ID) {
          scene.entityVisual.markPlayerMaterialized()
        }

        continue
      }

      if (action.type === 'update') {
        const sprite = scene.sprites.get(action.state.id)

        if (!sprite) {
          continue
        }

        // `action.state.row` — cùng trust boundary như nhánh 'create' ở trên
        // (entityGridPosition() là nguồn duy nhất).
        sprite.row = action.state.row as LaneIndex
        scene.positionInterp.snapInterpolationTarget(action.state.id, action.state.column)
        scene.positionSprite(sprite, action.state.column, action.state.id)
        scene.updateEnemyHealthBar(sprite, action.state.currentHp, action.state.maxHp)
        continue
      }

      // 'remove' — id alive:false hoặc biến mất khỏi snapshot mà KHÔNG đi
      // qua event 'death' riêng (race/fallback). Nếu onDeath() đang chạy
      // death sequence cho id này (dyingIds/playerDying) thì BỎ QUA — sequence
      // đó tự lo xóa sprite khi xong, chạy thêm ở đây là double-destroy.
      const isDying = action.id === PLAYER_ID ? scene.playerDying : scene.dyingIds.has(action.id)

      if (isDying) {
        continue
      }

      const sprite = scene.sprites.get(action.id)

      if (!sprite) {
        continue
      }

      // Combat Art Pipeline Task 9 (2026-09-05) — đi qua CÙNG death sequence
      // với onDeath() (phát '-death' + hoãn destroy tới khi animation/tween
      // xong) thay vì xóa ngay, để entity chết theo đường fallback này cũng
      // được chơi animation chết đầy đủ (spec §9).
      scene.beginDeathSequence(sprite, action.id)
    }

    const nextKnownIds = new Set(states.map((state) => state.id))

    if (side === 'player') {
      scene.knownTurnBattlePlayerIds = nextKnownIds
    } else {
      scene.knownTurnBattleEnemyIds = nextKnownIds
    }
  }

  reconcileEnemySprites(enemies: BattlePositionsEvent['enemies']) {
    const scene = this.scene
    const currentIds = new Set(enemies.map((enemy) => enemy.id))

    for (const enemy of enemies) {
      if (scene.sprites.has(enemy.id)) {
        continue
      }

      const sprite = scene.getOrCreateSprite(enemy.id, ENEMY_COLOR, enemy.name, enemy.row, enemy)

      // Vừa materialize từ telegraph — fade-in + scale 0.7→1 (bóng/máu/
      // tên chỉ hiện từ khoảnh khắc này, đúng spec spawn mới).
      scene.entityVisual.consumeMaterializing(enemy.id, sprite)
    }

    for (const [id, sprite] of scene.sprites) {
      if (id === PLAYER_ID || currentIds.has(id) || scene.dyingIds.has(id)) {
        continue
      }

      scene.destroyEntitySprite(sprite)
      scene.sprites.delete(id)
      scene.positionInterp.delete(id)
    }
  }
}

// Buff bar (2026-09-02, Task 4) — CombatVfxSpawner status icon ROW:
// - enemy: hàng icon dưới foot sprite (perspective: foot = rect.y)
// - player: hàng icon trên cụm sub-bar HUD (tính từ viewport height)
// - 2 tầng: temporary (rowTier 0) + permanent (rowTier 1)
// - stack label góc phải-dưới; >8 icon gộp counter "+N" ở icon cuối
// Mock scene = fake objects thuần (pattern PlayerHudLayer.test.ts),
// KHÔNG instantiate Phaser thật.
// @vitest-environment jsdom
import { describe, expect, it, beforeEach } from 'vitest'
import { CombatVfxSpawner } from './combat-vfx-spawner'
import {
  STATUS_ICON_SIZE,
  STATUS_ICON_SPACING,
  STATUS_MAX_PER_ROW,
  STATUS_FOOT_ROW_OFFSET_Y,
  STATUS_ROW_GAP,
} from './combatConstants'
import { HUD_MARGIN, HUD_HP_HEIGHT, HUD_SUB_HEIGHT, HUD_GAP } from './PlayerHudLayer'
import type { StatusVfxAttachedEvent } from '@/core/battle/BattleEvents'

interface FakeGameObject {
  x: number
  y: number
  angle: number
  visible: boolean
  destroyed: boolean
  text: string
  setAngle(deg: number): FakeGameObject
  setDepth(): FakeGameObject
  setPosition(x: number, y: number): FakeGameObject
  setOrigin(): FakeGameObject
  setVisible(v: boolean): FakeGameObject
  setInteractive(): FakeGameObject
  on(): FakeGameObject
  setText(t: string): FakeGameObject
  destroy(): void
}

function makeFakeGameObject(initialText = ''): FakeGameObject {
  const obj: FakeGameObject = {
    x: 0,
    y: 0,
    angle: 0,
    visible: true,
    destroyed: false,
    text: initialText,
    setAngle(deg: number) {
      obj.angle = deg
      return obj
    },
    setDepth() {
      return obj
    },
    setPosition(x: number, y: number) {
      obj.x = x
      obj.y = y
      return obj
    },
    setOrigin() {
      return obj
    },
    setVisible(v: boolean) {
      obj.visible = v
      return obj
    },
    setInteractive() {
      return obj
    },
    on() {
      return obj
    },
    setText(t: string) {
      obj.text = t
      return obj
    },
    destroy() {
      obj.destroyed = true
    },
  }

  return obj
}

interface FakeSprite {
  rect: { x: number; y: number; displayHeight: number }
}

function makeFakeScene(viewport: { width: number; height: number }, sprites: Map<string, FakeSprite>) {
  const created: FakeGameObject[] = []

  return {
    created,
    statuses: new Map<string, unknown>(),
    spriteFor: (id: string) => sprites.get(id),
    isPerspective: true,
    scale: viewport,
    add: {
      rectangle() {
        const obj = makeFakeGameObject()
        created.push(obj)
        return obj
      },
      circle() {
        const obj = makeFakeGameObject()
        created.push(obj)
        return obj
      },
      text(_x: number, _y: number, initial: string) {
        const obj = makeFakeGameObject(initial)
        created.push(obj)
        return obj
      },
    },
  }
}

function makeEvent(overrides: Partial<StatusVfxAttachedEvent> = {}): StatusVfxAttachedEvent {
  return {
    type: 'status_vfx_attached',
    statusInstanceId: 'enemy:bong:src',
    targetId: 'enemy',
    dotType: 'bong',
    stacks: 1,
    durationSeconds: 4,
    buffName: 'Bỏng',
    polarity: 'debuff',
    permanent: false,
    ...overrides,
  }
}

const ENEMY_SPRITE: FakeSprite = { rect: { x: 300, y: 400, displayHeight: 48 } }

describe('CombatVfxSpawner — status icon row (buff bar)', () => {
  let scene: ReturnType<typeof makeFakeScene>
  let spawner: CombatVfxSpawner

  beforeEach(() => {
    scene = makeFakeScene({ width: 800, height: 600 }, new Map([['enemy', ENEMY_SPRITE]]))
    spawner = new CombatVfxSpawner(scene as unknown as never)
  })

  it('attach debuff diamond → 1 icon (angle 45) + entry đầy đủ fields', () => {
    spawner.onStatusAttached(makeEvent())

    expect(scene.statuses.size).toBe(1)

    const entry = scene.statuses.get('enemy:bong:src') as {
      targetId: string
      buffId: string
      polarity: string
      permanent: boolean
      stacks: number
      buffName: string | undefined
      remainingTime: number | undefined
      icon: FakeGameObject
      stackLabel: FakeGameObject
    }

    expect(entry.targetId).toBe('enemy')
    expect(entry.buffId).toBe('bong')
    expect(entry.polarity).toBe('debuff')
    expect(entry.permanent).toBe(false)
    expect(entry.stacks).toBe(1)
    expect(entry.buffName).toBe('Bỏng')
    expect(entry.remainingTime).toBe(4)
    expect(entry.icon.angle).toBe(45) // diamond
    expect(entry.stackLabel.visible).toBe(false) // stacks 1 → ẩn
  })

  it('attach buff circle → icon angle 0 (add.circle)', () => {
    scene = makeFakeScene(
      { width: 800, height: 600 },
      new Map([['player', { rect: { x: 100, y: 500, displayHeight: 48 } }]]),
    )
    spawner = new CombatVfxSpawner(scene as unknown as never)

    spawner.onStatusAttached(
      makeEvent({
        statusInstanceId: 'player:khai_son:src',
        targetId: 'player',
        dotType: 'khai_son',
        buffName: 'Khai Sơn',
        polarity: 'buff',
      }),
    )

    const entry = scene.statuses.get('player:khai_son:src') as { icon: FakeGameObject }

    expect(entry.icon.angle).toBe(0)
  })

  it('stacks > 1 → stack label hiện số', () => {
    spawner.onStatusAttached(makeEvent({ stacks: 3 }))

    const entry = scene.statuses.get('enemy:bong:src') as { stackLabel: FakeGameObject }

    expect(entry.stackLabel.visible).toBe(true)
    expect(entry.stackLabel.text).toBe('3')
  })

  it('update → chỉ stack label + entry.stacks đổi, không tạo GameObject mới', () => {
    spawner.onStatusAttached(makeEvent())
    const createdBefore = scene.created.length

    spawner.onStatusUpdated({
      statusInstanceId: 'enemy:bong:src',
      stacks: 2,
      durationSeconds: 5,
    })

    expect(scene.created.length).toBe(createdBefore)

    const entry = scene.statuses.get('enemy:bong:src') as {
      stacks: number
      remainingTime: number | undefined
      stackLabel: FakeGameObject
    }

    expect(entry.stacks).toBe(2)
    expect(entry.remainingTime).toBe(5)
    expect(entry.stackLabel.text).toBe('2')
    expect(entry.stackLabel.visible).toBe(true)
  })

  it('remove → destroy icon + label, entry khỏi map', () => {
    spawner.onStatusAttached(makeEvent())

    spawner.onStatusRemoved({ statusInstanceId: 'enemy:bong:src' })

    const entry = scene.statuses.get('enemy:bong:src') as { icon: FakeGameObject; stackLabel: FakeGameObject }

    expect(entry).toBeUndefined()
  })

  it('enemy temporary row: icon y = footY + OFFSET, x xếp từ giữa sprite', () => {
    spawner.onStatusAttached(makeEvent())
    spawner.updateStatusIconPositions()

    const entry = scene.statuses.get('enemy:bong:src') as { icon: FakeGameObject }

    expect(entry.icon.y).toBe(ENEMY_SPRITE.rect.y + STATUS_FOOT_ROW_OFFSET_Y)
    // 1 icon: x = giữa sprite
    expect(entry.icon.x).toBe(ENEMY_SPRITE.rect.x)
  })

  it('enemy 2 icon → x lệch nhau đúng spacing', () => {
    spawner.onStatusAttached(makeEvent())
    spawner.onStatusAttached(
      makeEvent({ statusInstanceId: 'enemy:te_cong:src', dotType: 'te_cong', buffName: 'Tê Cóng' }),
    )
    spawner.updateStatusIconPositions()

    const first = scene.statuses.get('enemy:bong:src') as { icon: FakeGameObject }
    const second = scene.statuses.get('enemy:te_cong:src') as { icon: FakeGameObject }

    // rowWidth = 2*(10+4)-4 = 24; startX = 300 - 12 + 5 = 293; icon2 = 293+14 = 307
    expect(first.icon.x).toBe(ENEMY_SPRITE.rect.x - (STATUS_ICON_SIZE + STATUS_ICON_SPACING) / 2)
    expect(second.icon.x).toBe(first.icon.x + STATUS_ICON_SIZE + STATUS_ICON_SPACING)
  })

  it('enemy permanent row: y thấp hơn temporary row 1 bậc (rowTier riêng)', () => {
    spawner.onStatusAttached(makeEvent()) // temporary
    spawner.onStatusAttached(
      makeEvent({
        statusInstanceId: 'enemy:onhit_x:src',
        dotType: 'onhit_x',
        polarity: 'buff',
        permanent: true,
      }),
    )
    spawner.updateStatusIconPositions()

    const temporary = scene.statuses.get('enemy:bong:src') as { icon: FakeGameObject }
    const permanent = scene.statuses.get('enemy:onhit_x:src') as { icon: FakeGameObject }

    // permanent row nằm DƯỚI temporary row (dưới chân, xa sprite hơn)
    expect(permanent.icon.y).toBe(temporary.icon.y + STATUS_ROW_GAP + STATUS_ICON_SIZE)
  })

  it('player temporary row: y tính từ sub2Y của HUD (viewport 800x600 → 538)', () => {
    scene = makeFakeScene({ width: 800, height: 600 }, new Map([['player', { rect: { x: 100, y: 500, displayHeight: 48 } }]]))
    spawner = new CombatVfxSpawner(scene as unknown as never)

    spawner.onStatusAttached(
      makeEvent({
        statusInstanceId: 'player:lam_cham:src',
        targetId: 'player',
        dotType: 'lam_cham',
        polarity: 'debuff',
      }),
    )
    spawner.updateStatusIconPositions()

    const entry = scene.statuses.get('player:lam_cham:src') as { icon: FakeGameObject }
    const sub2Y = 600 - HUD_MARGIN - HUD_HP_HEIGHT - HUD_GAP - HUD_SUB_HEIGHT - HUD_GAP - HUD_SUB_HEIGHT

    expect(entry.icon.y).toBe(sub2Y - STATUS_PLAYER_ROW_OFFSET_Y_FOR_TEST - STATUS_ICON_SIZE)
    expect(entry.icon.x).toBe(HUD_MARGIN)
  })

  it('>8 temporary → icon 9+ ẩn, icon cuối mang counter "+N"', () => {
    for (let i = 0; i < 10; i++) {
      spawner.onStatusAttached(
        makeEvent({ statusInstanceId: `enemy:dot${i}:src`, dotType: `dot${i}` }),
      )
    }
    spawner.updateStatusIconPositions()

    const eighth = scene.statuses.get('enemy:dot7:src') as { icon: FakeGameObject; stackLabel: FakeGameObject }
    const ninth = scene.statuses.get('enemy:dot8:src') as { icon: FakeGameObject }

    expect(eighth.stackLabel.text).toBe('+2')
    expect(eighth.stackLabel.visible).toBe(true)
    expect(ninth.icon.visible).toBe(false)
  })
})

// Local alias tránh import lặp — cùng giá trị STATUS_PLAYER_ROW_OFFSET_Y
// nhưng tách tên để test không phụ thuộc vào constant source-of-truth.
const STATUS_PLAYER_ROW_OFFSET_Y_FOR_TEST = 6

// Invariant "MỘT action_impact = MỘT VFX instance": bất kể hitCount/
// pulses/space, spawnActionImpactVfx chỉ được tạo tối đa 2 Graphics
// (ground + upright) và ĐÚNG 1 tween timeline. Multi-hit là state bên
// trong instance, không phải thêm GameObject.
// @vitest-environment jsdom
import { describe, expect, it, vi } from 'vitest'
import { createBattleGridProjection } from '@/presentation/geometry/BattleGridProjection'
import { computeUprightRadius, spawnActionImpactVfx } from './ActionImpactVfx'
import { COMBAT_VFX_PRESETS } from '@/data/vfx/CombatVfxPresets'

function chainableGraphics(): Record<string, unknown> {
  const target: Record<string, unknown> = {}
  const proxy: Record<string, unknown> = new Proxy(target, {
    get(obj, prop) {
      if (prop in obj) return obj[prop as string]
      return () => proxy
    },
    set(obj, prop, value) {
      obj[prop as string] = value
      return true
    },
  })
  return proxy
}

function createSceneStub() {
  let graphicsCreated = 0
  const tweens: Array<Record<string, unknown>> = []

  const scene = {
    add: {
      graphics: () => {
        graphicsCreated++
        return chainableGraphics()
      },
    },
    tweens: {
      add: (config: Record<string, unknown>) => {
        tweens.push(config)
      },
    },
  }

  return {
    scene: scene as unknown as import('phaser').Scene,
    graphicsCreated: () => graphicsCreated,
    tweens,
  }
}

