// Remediation Task 2 — spawnActionImpactVfx exposes a completion handle:
// the caller (CombatScene) acknowledges the engine from the TWEEN's
// onComplete — not from a duplicated duration calculation. destroy() đúng
// 1 lần cho MỖI graphics (ground/upright), callback fire đúng 1 lần.
describe('spawnActionImpactVfx — completion handle (Remediation Task 2)', () => {
  it('trả về completion handle; onComplete fires từ tween onComplete (đúng 1 lần)', () => {
    const { scene, tweens } = createSceneStub()

    let completed = 0
    const handle = spawnActionImpactVfx(
      {
        scene,
        projection: PROJECTION,
        area: AREA,
        anchorCell: ANCHOR,
        preset: COMBAT_VFX_PRESETS.slash,
        pulses: 1,
        uprightDepth: 450,
      },
      () => {
        completed += 1
      },
    )

    expect(handle).toBeDefined()
    expect(typeof handle.complete).toBe('function')
    expect(completed).toBe(0)

    // Tween của Phaser gọi onComplete khi timeline xong — mô phỏng.
    ;(tweens[0]!.onComplete as () => void)()

    expect(completed).toBe(1)
  })

  it('handle.complete() gọi thủ công cũng complete đúng 1 lần (idempotent, destroy đúng 1 lần)', () => {
    const { scene, tweens } = createSceneStub()

    const destroyCalls: string[] = []
    const sceneWithDestroyTracking = {
      add: {
        graphics: () => {
          const gfx = chainableGraphics() as Record<string, unknown> & { destroy: () => void }

          gfx.destroy = () => {
            destroyCalls.push('destroy')
          }

          return gfx
        },
      },
      tweens: { add: (config: Record<string, unknown>) => tweens.push(config) },
    } as unknown as import('phaser').Scene

    let completed = 0
    const handle = spawnActionImpactVfx(
      {
        scene: sceneWithDestroyTracking,
        projection: PROJECTION,
        area: AREA,
        anchorCell: ANCHOR,
        preset: COMBAT_VFX_PRESETS.fire_burst, // hybrid → ground + upright
        pulses: 1,
        uprightDepth: 450,
      },
      () => {
        completed += 1
      },
    )

    handle.complete()
    handle.complete()

    // Tween onComplete chạy SAU handle.complete() — vẫn không fire lại.
    ;(tweens[0]!.onComplete as () => void)()

    expect(completed).toBe(1)
    // hybrid = 2 Graphics (ground + upright), mỗi cái destroy ĐÚNG 1 lần.
    expect(destroyCalls).toHaveLength(2)
  })

  it('không có callback — handle vẫn hoạt động, graphics vẫn destroy', () => {
    const { scene, tweens } = createSceneStub()

    const handle = spawnActionImpactVfx({
      scene,
      projection: PROJECTION,
      area: AREA,
      anchorCell: ANCHOR,
      preset: COMBAT_VFX_PRESETS.earth_shockwave,
      pulses: 1,
      uprightDepth: 450,
    })

    expect(() => handle.complete()).not.toThrow()
    expect(tweens).toHaveLength(1)
  })

  it('vi.handle.complete() trước khi tween xong → tween onComplete sau đó KHÔNG fire lại callback', () => {
    const { scene, tweens } = createSceneStub()

    let completed = 0
    const handle = spawnActionImpactVfx(
      {
        scene,
        projection: PROJECTION,
        area: AREA,
        anchorCell: ANCHOR,
        preset: COMBAT_VFX_PRESETS.slash,
        pulses: 1,
        uprightDepth: 450,
      },
      () => {
        completed += 1
      },
    )

    handle.complete()
    expect(completed).toBe(1)

    // Giả lập tween vẫn chạy xong sau đó.
    ;(tweens[0]!.onComplete as () => void)()
    expect(completed).toBe(1)
  })
})

// CombatPreload — danh sách texture CombatScene cần, queue MỘT LẦN dùng
// chung cho CẢ MainScene.preload() và CombatScene.preload().
//
// Fix "lần đầu vào combat không thấy spawn animation" (2026-08-26):
// trước đây chỉ CombatScene.preload() queue các ảnh này — lần ĐẦU tiên
// scene start (ngay sau 'battle_start'), loader phải tải ~7-25MB qua
// dev server trong khi phase spawn telegraph (~1s) đã chạy xong phía
// core → scene kịp subscribe khi mọi quái đã materialize. Eager-load từ
// MainScene (chạy lúc boot game, TRƯỚC mọi trận) khiến lần start đầu
// của CombatScene có loader queue RỖNG → create() gần như tức thời,
// listener gắn đúng phase spawn.
import type Phaser from 'phaser'
import { GOURD_TEXTURE_KEY, GOURD_TEXTURE_URL } from './RewardGourd'
import {
  ENEMY_SOURCE_SIZE,
  enemyTextureUrl,
  resolveEnemyTextureKey,
  MORTAL_ENEMY_TEMPLATE_IDS,
} from './EnemyArt'
import { PLAYER_VISUAL_PROFILES } from '@/presentation/art/PlayerVisualProfiles'
import { peekThanhVanVariant, thanhVanLoadList } from './ThanhVanArt'
import {
  animatedCombatEntities,
  FALLBACK_PLAYER_ENTITY_KEY,
} from '@/presentation/art/CombatPresentationCatalogue'
import type { CombatAnimationCatalogue } from '@/presentation/art/CombatEntityPresentation'

// Combat uses the static mortal artwork. MainScene keeps its existing atlas;
// the scenes intentionally use separate texture keys and presentations.
// The catalogue declares this key (it is a presentation fact: an entity whose
// art is the mortal PNG under a second key). Re-exported here so the many
// existing importers do not all have to move at once.
export const PLAYER_TEXTURE_KEY = FALLBACK_PLAYER_ENTITY_KEY

// Same PNG as the mortal profile's combatTextureUrl, without the leading
// slash — R12/AR-30 keeps the literal spelled once (in PlayerVisualProfiles).
export const PLAYER_TEXTURE_URL = PLAYER_VISUAL_PROFILES.mortal.combatTextureUrl.replace(
  /^\/+/,
  '',
)

// Mortal enemy art batch (mortal-enemy-art-batch-plan.md) — 20 PNG cho
// 10 loài + bản ferocious; id ngoài batch fallback Rectangle.
// R12/AR-30: the id list is owned by EnemyArt (MORTAL_ENEMY_TEMPLATE_IDS);
// this re-export keeps the preload surface stable for existing importers.
export const ENEMY_TEMPLATE_IDS = MORTAL_ENEMY_TEMPLATE_IDS

// Spec B §4.4 (2026-09-11) — ONE resolver answers what an entity's art is.
// This used to be three near-identical wrappers around one placeholder builder
// that discarded both of its data parameters (§2.1).
//
// `allCombatAnimationSets` is gone with them: it named every entity, but every
// entity is no longer animated. Enemies are `kind: 'static'` now (§3.2), and a
// list that still handed CombatScene a clip set for each of them would quietly
// re-animate them.
export function animatedCombatAnimationSets(): Array<{
  entityKey: string
  clips: CombatAnimationCatalogue
}> {
  return animatedCombatEntities()
}

/**
 * Queue mọi texture combat cần — DEDUPE THEO TEXTURE KEY trong chính
 * một lần queue (P2 cleanup, dong-fu plan): `textures.exists()` không
 * nhận biết key vừa được queue trong CÙNG lượt gọi, và các Player
 * profile dùng trùng key (kiem_tu tái dùng Mortal combat art,
 * cultivate chung 'player-mortal-cultivate-v1') nên guard exists một
 * mình là chưa đủ. Một Set cục bộ chặn queue trùng; guard
 * textures.exists() vẫn giữ cho các lần gọi sau khi load hoàn tất.
 * An toàn gọi từ cả MainScene.preload() và CombatScene.preload().
 *
 * Combat Art Pipeline Task 9 (2026-09-05) — THÊM (không thay) queue
 * spritesheet placeholder (1 frame = ảnh gốc, xem CombatAnimationSet.ts)
 * cho từng entity CẠNH các ảnh PNG tĩnh cũ, KHÔNG bỏ ảnh tĩnh cũ: MainScene
 * (Home Scene, ngoài phạm vi task này) và nhánh fallback của
 * combat-grid-view.ts/combat-player-visual.ts vẫn dùng key tĩnh nguyên bản
 * (PLAYER_TEXTURE_KEY/profile.combatTextureKey/enemy texture key) làm
 * texture THẬT của Sprite; đổi các key đó thành spritesheet-only sẽ làm vỡ
 * MỌI chỗ đang add.sprite()/setTexture() bằng key tĩnh đó (MainScene player
 * đứng ở Nhà, không hề animate — tự comment trong MainScene.ts). CombatScene
 * chỉ cần các sheetKey RIÊNG (hậu tố '-idle-sheet'…) để chạy Animation, nên
 * load thêm là đủ, không cần sửa consumer nào khác ngoài 2 file brief này.
 */
export function queueCombatAssets(scene: Phaser.Scene): void {
  const queuedKeys = new Set<string>()

  const queueOnce = (key: string, url: string) => {
    if (queuedKeys.has(key) || scene.textures.exists(key)) {
      return
    }

    queuedKeys.add(key)

    scene.load.image(key, url)
  }

  const queueAtlasOnce = (clips: CombatAnimationCatalogue) => {
    for (const clip of Object.values(clips)) {
      if (queuedKeys.has(clip.sheetKey) || scene.textures.exists(clip.sheetKey)) {
        continue
      }

      queuedKeys.add(clip.sheetKey)

      // Atlas, not spritesheet (Spec B §3.1): frames are addressed by name so
      // the JSON's per-frame trim data survives to spec C.
      scene.load.atlas(clip.sheetKey, clip.sheetUrl, clip.atlasUrl)
    }
  }

  queueOnce(PLAYER_TEXTURE_KEY, PLAYER_TEXTURE_URL)

  // Thanh Vân modular art — load ĐÚNG variant phiên hiện tại (sky + 6
  // layer mùa).
  for (const entry of thanhVanLoadList(peekThanhVanVariant())) {
    queueOnce(entry.key, entry.url)
  }

  // Reward gourd art — PNG thật thay placeholder.
  queueOnce(GOURD_TEXTURE_KEY, GOURD_TEXTURE_URL)

  for (const templateId of ENEMY_TEMPLATE_IDS) {
    const textureKey = resolveEnemyTextureKey(templateId)

    if (textureKey) {
      queueOnce(textureKey, enemyTextureUrl(textureKey))
    }
  }

  // Player visual profiles — preload texture cho MỌI profile có thể
  // dùng trong combat (kiem_tu tái dùng mortal nên không cần key riêng).
  for (const profile of Object.values(PLAYER_VISUAL_PROFILES)) {
    queueOnce(profile.combatTextureKey, profile.combatTextureUrl)

    if (profile.cultivateTextureKey && profile.cultivateTextureUrl) {
      queueOnce(profile.cultivateTextureKey, profile.cultivateTextureUrl)
    }
  }

  // The placeholder atlas, for ANIMATED entities only (Spec B §3.2) —
  // CombatScene.create() registers animations from the SAME list, so the two
  // can never name different keys. Static entities queue nothing extra: their
  // still PNG is already queued above, and their motion is a tween.
  for (const { clips } of animatedCombatAnimationSets()) {
    queueAtlasOnce(clips)
  }
}

import { beforeEach, describe, expect, it, vi } from 'vitest'
import {
  GamePresentationCoordinator,
  type CoordinatorDeps,
} from './GamePresentationCoordinator'
import type {
  AssetPort,
  CoordinatorSnapshot,
  CurtainPort,
  DeadlineScheduler,
  RendererPort,
  RouteRequest,
} from './PresentationContracts'
import {
  PresentationSession,
  type SessionPresentationPort,
} from '../core/presentation/PresentationSession'

function deferred<T = void>() {
  let resolve!: (value: T | PromiseLike<T>) => void
  let reject!: (reason?: unknown) => void
  const promise = new Promise<T>((yes, no) => {
    resolve = yes
    reject = no
  })
  return { promise, resolve, reject }
}

async function flushTicks(count = 5) {
  for (let i = 0; i < count; i++) {
    await Promise.resolve()
  }
}

describe('GamePresentationCoordinator', () => {
  let sessionPort: SessionPresentationPort
  let renderer: RendererPort
  let curtain: CurtainPort
  let assets: AssetPort
  let callLog: string[]

  beforeEach(() => {
    sessionPort = new PresentationSession()
    callLog = []

    renderer = {
      prepare: vi.fn(async () => {
        callLog.push('renderer.prepare')
      }),
      deactivate: vi.fn(async () => {
        callLog.push('renderer.deactivate')
      }),
    }

    curtain = {
      close: vi.fn(async () => {
        callLog.push('curtain.close')
      }),
      open: vi.fn(async () => {
        callLog.push('curtain.open')
      }),
    }

    assets = {
      ensureFor: vi.fn(async () => {
        callLog.push('assets.ensureFor')
      }),
    }
  })

  function createCoordinator(overrides: Partial<CoordinatorDeps> = {}) {
    return new GamePresentationCoordinator({
      sessionPort,
      renderer,
      curtain,
      assets,
      initialRoute: 'home',
      ...overrides,
    })
  }

  it('executes full ordered kernel and verifies state at each deferred step', async () => {
    const closeDef = deferred()
    const assetsDef = deferred()
    const deactDef = deferred()
    const prepareDef = deferred()
    const openDef = deferred()

    curtain.close = vi.fn(() => {
      callLog.push('curtain.close')
      return closeDef.promise
    })
    assets.ensureFor = vi.fn(() => {
      callLog.push('assets.ensureFor')
      return assetsDef.promise
    })
    renderer.deactivate = vi.fn(() => {
      callLog.push('renderer.deactivate')
      return deactDef.promise
    })
    renderer.prepare = vi.fn(() => {
      callLog.push('renderer.prepare')
      return prepareDef.promise
    })
    curtain.open = vi.fn(() => {
      callLog.push('curtain.open')
      return openDef.promise
    })

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 1 }
    // Start session in interactive mode
    sessionPort.hold(session) // prime session or begin on port
    const portSession = sessionPort as PresentationSession
    portSession.begin(session, 'interactive')

    const snapshots: CoordinatorSnapshot[] = []
    coordinator.subscribe((s) => snapshots.push(s))

    const requestPromise = coordinator.request({ target: 'combat', session })

    // Step: closing curtain
    expect(coordinator.getSnapshot().phase).toBe('closing')
    expect(coordinator.getSnapshot().renderRoute).toBeNull()
    expect(coordinator.getSnapshot().currentRoute).toBe('home')
    expect(callLog).toEqual(['curtain.close'])
    closeDef.resolve()
    await flushTicks()

    // Step: loading assets
    expect(coordinator.getSnapshot().phase).toBe('loading')
    expect(coordinator.getSnapshot().renderRoute).toBeNull()
    expect(callLog).toEqual(['curtain.close', 'assets.ensureFor'])
    assetsDef.resolve()
    await flushTicks()

    // Step: deactivating prior renderer
    expect(callLog).toEqual(['curtain.close', 'assets.ensureFor', 'renderer.deactivate'])
    deactDef.resolve()
    await flushTicks()

    // Step: activating & awaiting-ready
    expect(coordinator.getSnapshot().renderRoute).toBe('combat')
    expect(coordinator.getSnapshot().currentRoute).toBe('home') // NOT committed yet!
    expect(portSession.isBlocking()).toBe(true) // NOT released yet!
    expect(callLog).toEqual(['curtain.close', 'assets.ensureFor', 'renderer.deactivate', 'renderer.prepare'])
    prepareDef.resolve()
    await flushTicks()

    // Step: opening curtain (committed currentRoute)
    expect(coordinator.getSnapshot().currentRoute).toBe('combat')
    expect(coordinator.getSnapshot().renderRoute).toBeNull()
    expect(portSession.isBlocking()).toBe(true) // Still held during opening!
    expect(callLog).toEqual(['curtain.close', 'assets.ensureFor', 'renderer.deactivate', 'renderer.prepare', 'curtain.open'])
    openDef.resolve()
    await flushTicks()

    const result = await requestPromise
    expect(result.status).toBe('entered')

    // Final: idle and unblocked
    expect(coordinator.getSnapshot().phase).toBe('idle')
    expect(coordinator.getSnapshot().currentRoute).toBe('combat')
    expect(portSession.isBlocking()).toBe(false)
  })

  it('handles synchronous READY cleanly', async () => {
    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 2 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const result = await coordinator.request({ target: 'combat', session })
    expect(result.status).toBe('entered')
    expect(coordinator.getSnapshot().currentRoute).toBe('combat')
    expect(coordinator.getSnapshot().phase).toBe('idle')
  })

  it('fails transition and keeps session held when prepare times out (missing READY)', async () => {
    vi.useFakeTimers()
    try {
      const prepareDef = deferred()
      renderer.prepare = vi.fn(() => prepareDef.promise)

      const coordinator = createCoordinator({ initialRoute: 'home' })
      const session = { kind: 'combat' as const, sessionId: 3 }
      ;(sessionPort as PresentationSession).begin(session, 'interactive')

      const requestPromise = coordinator.request({ target: 'combat', session })
      await flushTicks()

      // Advance timers by the prepareReady deadline (10,000ms)
      await vi.advanceTimersByTimeAsync(10_000)

      const result = await requestPromise
      expect(result.status).toBe('failed')

      const snapshot = coordinator.getSnapshot()
      expect(snapshot.phase).toBe('failed')
      expect(snapshot.error?.message).toContain('Renderer readiness timed out')
      expect(snapshot.renderRoute).toBeNull()

      // Law A7 & Gate: session must remain held on failure!
      expect((sessionPort as PresentationSession).isBlocking()).toBe(true)
    } finally {
      vi.useRealTimers()
    }
  })

  it('shares in-flight promise for duplicate request with same route and session', async () => {
    const prepareDef = deferred()
    renderer.prepare = vi.fn(() => prepareDef.promise)

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 4 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const req1 = coordinator.request({ target: 'combat', session })
    const req2 = coordinator.request({ target: 'combat', session })

    prepareDef.resolve()
    const [res1, res2] = await Promise.all([req1, req2])

    expect(res1).toBe(res2)
    expect(res1.status).toBe('entered')
  })

  it('rejects conflicting request while transition is in flight', async () => {
    const prepareDef = deferred()
    renderer.prepare = vi.fn(() => prepareDef.promise)

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session1 = { kind: 'combat' as const, sessionId: 5 }
    const session2 = { kind: 'combat' as const, sessionId: 6 }
    ;(sessionPort as PresentationSession).begin(session1, 'interactive')

    const req1 = coordinator.request({ target: 'combat', session: session1 })
    const conflictReq = await coordinator.request({ target: 'combat', session: session2 })

    expect(conflictReq.status).toBe('rejected')

    prepareDef.resolve()
    const res1 = await req1
    expect(res1.status).toBe('entered')
  })

  it('returns unchanged for same idle healthy route and session', async () => {
    const coordinator = createCoordinator({ initialRoute: 'home' })
    const result = await coordinator.request({ target: 'home' })
    expect(result.status).toBe('unchanged')
  })

  it('rejects requests with invalid edge', async () => {
    const coordinator = createCoordinator({ initialRoute: 'combat' })
    // Combat directly to character is not an allowed edge
    const result = await coordinator.request({ target: 'character' })
    expect(result.status).toBe('rejected')
  })

  it('allows same-route rebind for combat with new session', async () => {
    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session1 = { kind: 'combat' as const, sessionId: 10 }
    ;(sessionPort as PresentationSession).begin(session1, 'interactive')

    await coordinator.request({ target: 'combat', session: session1 })
    expect(coordinator.getSnapshot().currentRoute).toBe('combat')

    // New session on combat route
    const session2 = { kind: 'combat' as const, sessionId: 11 }
    ;(sessionPort as PresentationSession).begin(session2, 'interactive')

    const rebindResult = await coordinator.request({ target: 'combat', session: session2 })
    expect(rebindResult.status).toBe('entered')
    expect(coordinator.getSnapshot().currentSession?.sessionId).toBe(11)
  })

  it('fails transition and keeps session held when open curtain fails after commit', async () => {
    curtain.open = vi.fn(async () => {
      throw new Error('Curtain animation broken')
    })

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 7 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const result = await coordinator.request({ target: 'combat', session })
    expect(result.status).toBe('failed')

    const snapshot = coordinator.getSnapshot()
    expect(snapshot.phase).toBe('failed')
    expect(snapshot.error?.message).toContain('Curtain animation broken')
    // Hold must be detached with 'hold' policy (never released on failure)
    expect((sessionPort as PresentationSession).isBlocking()).toBe(true)
  })

  it('fails transition when attach returns false', async () => {
    sessionPort.attach = vi.fn(() => false)

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 8 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const result = await coordinator.request({ target: 'combat', session })
    expect(result.status).toBe('failed')
    expect(coordinator.getSnapshot().phase).toBe('failed')
    expect(coordinator.getSnapshot().error?.message).toContain('Failed to attach hold token')
  })

  it('fails transition when release returns false', async () => {
    sessionPort.release = vi.fn(() => false)

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 9 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const result = await coordinator.request({ target: 'combat', session })
    expect(result.status).toBe('failed')
    expect(coordinator.getSnapshot().phase).toBe('failed')
    expect(coordinator.getSnapshot().error?.message).toContain('Failed to release hold token')
  })

  it('allows retrying a failed target with the same valid session', async () => {
    let shouldFail = true
    renderer.prepare = vi.fn(async () => {
      if (shouldFail) throw new Error('First attempt failed')
    })

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 20 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const attempt1 = await coordinator.request({ target: 'combat', session })
    expect(attempt1.status).toBe('failed')
    expect(coordinator.getSnapshot().phase).toBe('failed')

    // Second attempt (retry same session) succeeds
    shouldFail = false
    const attempt2 = await coordinator.request({ target: 'combat', session })
    expect(attempt2.status).toBe('entered')
    expect(attempt2.transitionId).toBeGreaterThan(attempt1.transitionId)
    expect(coordinator.getSnapshot().phase).toBe('idle')
    expect(coordinator.getSnapshot().currentRoute).toBe('combat')
  })

  it('dispose aborts in-flight transition and unsubscribes listeners', async () => {
    const prepareDef = deferred()
    renderer.prepare = vi.fn(() => prepareDef.promise)

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 30 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const req = coordinator.request({ target: 'combat', session })
    coordinator.dispose()

    const res = await req
    expect(res.status).toBe('failed')

    // Further requests rejected
    const afterDispose = await coordinator.request({ target: 'home' })
    expect(afterDispose.status).toBe('rejected')
  })

  it('aborts the transition signal on failure so scoped waiters are torn down', async () => {
    let capturedSignal: AbortSignal | undefined
    const stuck = deferred()
    renderer.prepare = vi.fn((_req, _id, signal: AbortSignal) => {
      capturedSignal = signal
      return stuck.promise
    })

    const scheduler: DeadlineScheduler = {
      set: (callback) => {
        // Fire every deadline immediately: prepare never reports READY.
        const handle = setTimeout(callback, 0)
        return handle
      },
      clear: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
    }

    const coordinator = createCoordinator({ initialRoute: 'boot', scheduler })
    const result = await coordinator.request({ target: 'home' })

    expect(result.status).toBe('failed')
    expect(capturedSignal?.aborted).toBe(true)
  })

  it('retry re-runs the failed request under a fresh transition id and clears the error', async () => {
    let failNext = true
    renderer.prepare = vi.fn(async () => {
      if (failNext) {
        failNext = false
        throw new Error('scene create exploded')
      }
    })

    const coordinator = createCoordinator({ initialRoute: 'boot' })

    const first = await coordinator.request({ target: 'home' })
    expect(first.status).toBe('failed')
    expect(coordinator.getSnapshot().error?.failedRequest.target).toBe('home')

    const retried = await coordinator.retry()

    expect(retried.status).toBe('entered')
    expect(retried.transitionId).toBeGreaterThan(first.transitionId)
    expect(coordinator.getSnapshot().error).toBeNull()
    expect(coordinator.getSnapshot().currentRoute).toBe('home')
  })

  it('retry rejects when the failed session is no longer the current session', async () => {
    renderer.prepare = vi.fn(async () => {
      throw new Error('scene create exploded')
    })

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 77 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const failed = await coordinator.request({ target: 'combat', session })
    expect(failed.status).toBe('failed')

    // Domain moved on: the old session is gone, so retry must not resurrect it.
    ;(sessionPort as PresentationSession).end(session)

    const retried = await coordinator.retry()

    expect(retried.status).toBe('rejected')
    expect(coordinator.getSnapshot().currentRoute).toBe('home')
  })

  it('recovers to the route it never left after a failed entry (error shell Back)', async () => {
    // The Back button on the error shell calls request({ target: currentRoute }).
    // A failed entry never commits currentRoute, so this is a same-route request
    // and ALLOWED_EDGES.home has no 'home' self-entry. If it is rejected, phase
    // stays 'failed' forever: the overlay keeps pointer-events and both the
    // error card's buttons are dead - a permanent app lock with no way out but
    // a reload.
    let failNext = true
    renderer.prepare = vi.fn(async () => {
      if (failNext) {
        failNext = false
        throw new Error('scene create exploded')
      }
    })

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 91 }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')

    const failed = await coordinator.request({ target: 'combat', session })
    expect(failed.status).toBe('failed')
    expect(coordinator.getSnapshot().phase).toBe('failed')
    expect(coordinator.getSnapshot().currentRoute).toBe('home')

    // What App.vue's onTransitionBack does.
    coordinator.clearError()
    const back = await coordinator.request({ target: 'home' })

    expect(back.status).toBe('entered')
    expect(coordinator.getSnapshot().phase).toBe('idle')
    expect(coordinator.getSnapshot().currentRoute).toBe('home')
    expect(coordinator.getSnapshot().error).toBeNull()
  })

  it('retry with no recorded failure is rejected', async () => {
    const coordinator = createCoordinator({ initialRoute: 'home' })

    expect((await coordinator.retry()).status).toBe('rejected')
  })

  it('canEnter reports admissibility without allocating a transition', async () => {
    const coordinator = createCoordinator({ initialRoute: 'home' })

    expect(coordinator.canEnter('combat')).toBe(true)
    expect(coordinator.canEnter('character')).toBe(false)
    expect(coordinator.getSnapshot().transitionId).toBe(0)
    expect(coordinator.getSnapshot().phase).toBe('idle')

    // While a transition is in flight nothing else may be admitted.
    const gate = deferred()
    curtain.close = vi.fn(() => gate.promise)
    const pending = coordinator.request({ target: 'combat', session: startedSession(12) })
    await flushTicks()

    expect(coordinator.canEnter('tribulation')).toBe(false)

    gate.resolve()
    await pending
  })

  it('canEnter is false for a disallowed edge, which is what keeps a boot-stuck route from accepting combat', () => {
    const coordinator = createCoordinator({ initialRoute: 'boot' })

    expect(coordinator.canEnter('combat')).toBe(false)
    expect(coordinator.canEnter('home')).toBe(true)
  })

  function startedSession(sessionId: number) {
    const session = { kind: 'combat' as const, sessionId }
    ;(sessionPort as PresentationSession).begin(session, 'interactive')
    return session
  }

  it('runs behindCurtain only after the curtain has fully closed', async () => {
    const order: string[] = []
    curtain.close = vi.fn(async () => {
      order.push('curtain-closed')
    })
    curtain.open = vi.fn(async () => {
      order.push('curtain-opened')
    })

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 40 }

    const result = await coordinator.request({
      target: 'combat',
      session,
      behindCurtain: () => {
        order.push('domain-command')
        ;(sessionPort as PresentationSession).begin(session, 'interactive')
        return true
      },
    })

    expect(result.status).toBe('entered')
    expect(order).toEqual(['curtain-closed', 'domain-command', 'curtain-opened'])
  })

  it('fails the transition and reopens the curtain when behindCurtain returns false', async () => {
    const coordinator = createCoordinator({ initialRoute: 'home' })
    const openSpy = vi.spyOn(curtain, 'open')
    const session = { kind: 'combat' as const, sessionId: 41 }

    const result = await coordinator.request({
      target: 'combat',
      session,
      behindCurtain: () => false,
    })

    expect(result.status).toBe('failed')
    expect(openSpy).toHaveBeenCalled()
  })

  it('retry never re-invokes behindCurtain when the command already produced and held a session', async () => {
    // Regression (code review, task-2): retry() must not re-run the domain
    // command outside runAdmitted's admission/compensate wiring. Simulates
    // the reviewer's concrete scenario - behindCurtain succeeds and holds a
    // session, then asset loading times out on the FIRST attempt only.
    let assetAttempts = 0
    assets.ensureFor = vi.fn(async () => {
      assetAttempts += 1
      if (assetAttempts === 1) {
        throw new Error('asset load exploded')
      }
    })

    const coordinator = createCoordinator({ initialRoute: 'home' })
    const session = { kind: 'combat' as const, sessionId: 70 }
    let commandCalls = 0

    const behindCurtain = () => {
      commandCalls += 1
      ;(sessionPort as PresentationSession).begin(session, 'interactive')
      return true
    }

    const first = await coordinator.request({ target: 'combat', session, behindCurtain })
    expect(first.status).toBe('failed')
    expect(commandCalls).toBe(1)
    // Law A7: the produced session stays held across the failure, retryable.
    expect((sessionPort as PresentationSession).isBlocking()).toBe(true)

    const retried = await coordinator.retry()

    expect(retried.status).toBe('entered')
    expect(coordinator.getSnapshot().currentRoute).toBe('combat')
    // The domain command must not have run a second time.
    expect(commandCalls).toBe(1)
  })

  it('retry rejects a behindCurtain request that failed before ever producing a session', async () => {
    // Regression (code review, task-2): with no session to resume, retry()
    // must reject rather than re-run the domain command a second time - the
    // "retry never re-issues the domain start command" contract holds even
    // when nothing was ever produced/held.
    const coordinator = createCoordinator({ initialRoute: 'home' })
    let commandCalls = 0

    // No `session` field - matches the real shape createGamePresentation.ts
    // constructs (target, behindCurtain), where behindCurtain is the ONLY
    // possible source of a session. A literal `session` field here would let
    // retry()'s plain-session branch reject for the wrong reason even
    // without this fix, defeating the point of the regression test.
    const failed = await coordinator.request({
      target: 'combat',
      behindCurtain: () => {
        commandCalls += 1
        return false
      },
    })

    expect(failed.status).toBe('failed')
    expect(commandCalls).toBe(1)

    const retried = await coordinator.retry()

    expect(retried.status).toBe('rejected')
    expect(commandCalls).toBe(1)
    // The error/failed state is untouched by the rejected retry attempt.
    expect(coordinator.getSnapshot().phase).toBe('failed')
  })

  it('provides detached snapshots to subscribers so mutations cannot affect internal state', () => {
    const coordinator = createCoordinator({ initialRoute: 'home' })
    let received: CoordinatorSnapshot | undefined
    const unsubscribe = coordinator.subscribe((s) => {
      received = s
    })

    expect(received?.currentRoute).toBe('home')

    // Unsubscribe works
    unsubscribe()
    coordinator.setShowMainMenu(true)
    expect(received?.showMainMenu).toBe(false)
  })

  it('runs behindCurtain on a non-session target after curtain close, requiring no session', async () => {
    // combat -> home teardown (abandon + scene-exit bookkeeping) rides the
    // same closed-curtain window as combat entry. It must NOT be forced to
    // produce a session - 'home' has none - and it must not run while the
    // curtain is still travelling.
    const closeDef = deferred()
    curtain.close = vi.fn(() => {
      callLog.push('curtain.close')
      return closeDef.promise
    })

    const coordinator = createCoordinator({ initialRoute: 'combat' })
    let workCalls = 0

    const requestPromise = coordinator.request({
      target: 'home',
      behindCurtain: () => {
        workCalls += 1
        callLog.push('behindCurtain')
        return true
      },
    })

    await flushTicks()
    // Curtain is still closing: the domain work has not run yet.
    expect(workCalls).toBe(0)
    expect(callLog).toEqual(['curtain.close'])

    closeDef.resolve()
    const result = await requestPromise

    expect(result.status).toBe('entered')
    expect(workCalls).toBe(1)
    expect(coordinator.getSnapshot().currentRoute).toBe('home')
    // Work ran strictly between close and open.
    expect(callLog.indexOf('behindCurtain')).toBeGreaterThan(callLog.indexOf('curtain.close'))
    expect(callLog.indexOf('behindCurtain')).toBeLessThan(callLog.indexOf('curtain.open'))
  })

  it('never short-circuits a behindCurtain request as unchanged on the same route', async () => {
    // isUnchanged() skips a transition when target === currentRoute - but a
    // request carrying domain work has work that has never run, so it must
    // still close, execute, and reopen.
    const coordinator = createCoordinator({ initialRoute: 'home' })
    let workCalls = 0

    const result = await coordinator.request({
      target: 'home',
      behindCurtain: () => {
        workCalls += 1
        return true
      },
    })

    expect(result.status).toBe('entered')
    expect(workCalls).toBe(1)
    expect(callLog).toEqual([
      'curtain.close',
      'assets.ensureFor',
      'renderer.prepare',
      'curtain.open',
    ])
  })
})

import { beforeEach, describe, expect, it, vi } from 'vitest'
import { PhaserSceneAdapter } from './PhaserSceneAdapter'

interface FakeSceneManager {
  isActive: (key: string) => boolean
  start: import('vitest').Mock
  stop: import('vitest').Mock
  getScene: import('vitest').Mock
}

function createFakeGame() {
  const activeScenes = new Set<string>()
  const sceneInstances = new Map<string, Record<string, unknown>>()

  const sceneMock: FakeSceneManager = {
    isActive: (key: string) => activeScenes.has(key),
    start: vi.fn((key: string, data?: unknown) => {
      activeScenes.add(key)
      const instance = sceneInstances.get(key)
      if (instance?.onStart) {
        ;(instance.onStart as (d: unknown) => void)(data)
      }
    }),
    stop: vi.fn((key: string) => {
      activeScenes.delete(key)
    }),
    getScene: vi.fn((key: string) => sceneInstances.get(key)),
  }

  const game = {
    scene: sceneMock,
    _activeScenes: activeScenes,
    _sceneInstances: sceneInstances,
  }

  return game
}

describe('PhaserSceneAdapter', () => {
  let adapter: PhaserSceneAdapter
  let fakeGame: ReturnType<typeof createFakeGame>

  beforeEach(() => {
    adapter = new PhaserSceneAdapter()
    fakeGame = createFakeGame()
    adapter.setGame(fakeGame as unknown as import('phaser').Game)
  })

  it('handles synchronous reportReady during scene activation', async () => {
    // Scene calls reportReady synchronously when started
    fakeGame.scene.start = vi.fn((key: string, data?: unknown) => {
      fakeGame._activeScenes.add(key)
      const context = data as { transitionId: number; sessionId?: number }
      adapter.reportReady({
        transitionId: context.transitionId,
        sessionId: context.sessionId,
      })
    })

    const signal = new AbortController().signal
    await expect(
      adapter.prepare({ target: 'home' }, 1, signal),
    ).resolves.toBeUndefined()

    expect(adapter.getActivePrimarySceneKey()).toBe('MainScene')
    expect(fakeGame.scene.start).toHaveBeenCalledWith('MainScene', {
      transitionId: 1,
      sessionId: undefined,
    })
  })

  it('resolves immediately for non-Phaser routes without touching game.scene', async () => {
    const signal = new AbortController().signal

    await adapter.prepare({ target: 'auth' }, 2, signal)
    expect(fakeGame.scene.start).not.toHaveBeenCalled()

    await adapter.prepare({ target: 'boot' }, 3, signal)
    expect(fakeGame.scene.start).not.toHaveBeenCalled()
  })

  it('stops previous primary scene before activating next primary', async () => {
    const signal = new AbortController().signal

    // First: activate MainScene
    fakeGame.scene.start = vi.fn((key, data) => {
      fakeGame._activeScenes.add(key)
      adapter.reportReady({ transitionId: (data as any).transitionId })
    })

    await adapter.prepare({ target: 'home' }, 1, signal)
    expect(adapter.getActivePrimarySceneKey()).toBe('MainScene')
    expect(fakeGame.scene.start).toHaveBeenCalledWith('MainScene', expect.anything())

    // Next: activate CombatScene -> MainScene must be stopped
    const session = { kind: 'combat' as const, sessionId: 10 }
    await adapter.prepare({ target: 'combat', session }, 2, signal)

    expect(fakeGame.scene.stop).toHaveBeenCalledWith('MainScene')
    expect(fakeGame.scene.start).toHaveBeenCalledWith('CombatScene', expect.anything())
    expect(adapter.getActivePrimarySceneKey()).toBe('CombatScene')
  })

  it('performs same-route rebind for combat when CombatScene is already active', async () => {
    const signal = new AbortController().signal
    const rebindSpy = vi.fn((ctx) => {
      adapter.reportReady(ctx)
    })

    fakeGame._sceneInstances.set('CombatScene', {
      rebindSession: rebindSpy,
    })

    // Put adapter in combat route
    fakeGame.scene.start = vi.fn((key, data) => {
      fakeGame._activeScenes.add(key)
      adapter.reportReady(data as any)
    })
    await adapter.prepare(
      { target: 'combat', session: { kind: 'combat', sessionId: 1 } },
      1,
      signal,
    )
    fakeGame.scene.start.mockClear()

    // Second combat session: same-route rebind
    await adapter.prepare(
      { target: 'combat', session: { kind: 'combat', sessionId: 2 } },
      2,
      signal,
    )

    // Must NOT destroy or restart scene via scene.start
    expect(fakeGame.scene.start).not.toHaveBeenCalled()
    expect(rebindSpy).toHaveBeenCalledWith({ transitionId: 2, sessionId: 2 })
  })

  it('rejects stale reportReady call from old transitionId or game generation', async () => {
    const signal = new AbortController().signal

    // Start preparation (which doesn't report ready immediately)
    const prepPromise = adapter.prepare({ target: 'home' }, 1, signal)

    // Stale transitionId does not resolve
    expect(adapter.reportReady({ transitionId: 999 })).toBe(false)

    // Stale game generation does not resolve
    expect(adapter.reportReady({ transitionId: 1, gameGeneration: 999 })).toBe(false)

    // Correct transition resolves
    expect(adapter.reportReady({ transitionId: 1 })).toBe(true)
    await expect(prepPromise).resolves.toBeUndefined()
  })

  it('rejects pending waiter when game is destroyed / replaced mid-preparation', async () => {
    const signal = new AbortController().signal
    const prepPromise = adapter.prepare({ target: 'home' }, 1, signal)

    // Game destroyed / unmounted
    adapter.setGame(null)

    await expect(prepPromise).rejects.toThrow('Game instance replaced or destroyed')
  })

  it('propagates error when scene.start throws on create', async () => {
    fakeGame.scene.start = vi.fn(() => {
      throw new Error('Scene create error')
    })

    const signal = new AbortController().signal
    await expect(
      adapter.prepare({ target: 'home' }, 1, signal),
    ).rejects.toThrow('Scene create error')
  })

  it('waits for game ready when prepare is called before game host is set', async () => {
    const lateAdapter = new PhaserSceneAdapter()
    const signal = new AbortController().signal

    // When game starts scene, report ready
    fakeGame.scene.start = vi.fn((key, data) => {
      fakeGame._activeScenes.add(key)
      lateAdapter.reportReady({ transitionId: (data as any).transitionId })
    })

    const prepPromise = lateAdapter.prepare({ target: 'home' }, 1, signal)

    // Simulate game host creation after delay
    lateAdapter.setGame(fakeGame as unknown as import('phaser').Game)

    await expect(prepPromise).resolves.toBeUndefined()
  })
})

/**
 * PhaserSceneAdapter (AstraDoctrine Law A5, A6, AGENTS.md P17).
 * Sole owner of primary Phaser scene lifecycle, scene switching, and readiness reporting.
 *
 * Invariant:
 * - Only adapter starts/stops primary scenes (MainScene, CombatScene, TribulationScene).
 * - Registers readiness waiter with {transitionId, sessionId, gameGeneration} before scene start.
 * - Public reportReady resolves matching pending waiter once.
 * - Same-route combat transition calls explicit scene rebind instead of destroying Game.
 * - Maintains exactly one active primary scene in steady state.
 */

import type Phaser from 'phaser'
import type { RendererPort, Route, RouteRequest } from './PresentationContracts'

export const PRIMARY_SCENE_ROUTES: Record<string, string> = {
  home: 'MainScene',
  combat: 'CombatScene',
  tribulation: 'TribulationScene',
}

export interface ReadyContext {
  transitionId: number
  sessionId?: number
  gameGeneration?: number
}

interface PendingWaiter {
  transitionId: number
  sessionId?: number
  gameGeneration: number
  sceneKey: string
  resolve: () => void
  reject: (reason?: unknown) => void
}

export class PhaserSceneAdapter implements RendererPort {
  private game: Phaser.Game | null = null
  private gameGeneration = 0
  private activePrimarySceneKey: string | null = null
  private pendingWaiter: PendingWaiter | null = null
  private gameReadyResolvers = new Set<() => void>()
  private disposed = false

  setGame(game: Phaser.Game | null): void {
    if (this.game !== game) {
      this.gameGeneration += 1

      // Cancel any pending waiter from previous game generation
      if (this.pendingWaiter) {
        this.pendingWaiter.reject(new Error('Game instance replaced or destroyed'))
        this.pendingWaiter = null
      }

      this.activePrimarySceneKey = null
      this.game = game

      if (game) {
        for (const resolver of this.gameReadyResolvers) {
          resolver()
        }
        this.gameReadyResolvers.clear()
      }
    }
  }

  getGameGeneration(): number {
    return this.gameGeneration
  }

  getActivePrimarySceneKey(): string | null {
    return this.activePrimarySceneKey
  }

  isPrimarySceneActive(sceneKey: string): boolean {
    if (!this.game) return false
    try {
      return this.game.scene.isActive(sceneKey)
    } catch {
      return false
    }
  }

  reportReady(context: ReadyContext): boolean {
    if (!this.pendingWaiter) {
      return false
    }

    if (this.pendingWaiter.transitionId !== context.transitionId) {
      return false
    }

    if (
      this.pendingWaiter.sessionId !== undefined &&
      context.sessionId !== undefined &&
      this.pendingWaiter.sessionId !== context.sessionId
    ) {
      return false
    }

    if (
      context.gameGeneration !== undefined &&
      context.gameGeneration !== this.pendingWaiter.gameGeneration
    ) {
      return false
    }

    const resolve = this.pendingWaiter.resolve
    this.pendingWaiter = null
    resolve()
    return true
  }

  async prepare(request: RouteRequest, transitionId: number, signal: AbortSignal): Promise<void> {
    if (this.disposed) {
      throw new Error('PhaserSceneAdapter disposed')
    }
    if (signal.aborted) {
      throw new Error('Preparation aborted')
    }

    const sceneKey = PRIMARY_SCENE_ROUTES[request.target]
    if (!sceneKey) {
      // Non-Phaser route (boot, auth, character, error): no Phaser scene required
      return
    }

    if (!this.game) {
      await this.waitForGameReady(signal)
    }

    if (!this.game) {
      throw new Error('No Phaser.Game host available')
    }

    const sessionId = 'session' in request ? request.session.sessionId : undefined
    const currentGeneration = this.gameGeneration

    // Case 1: Same Combat route rebind
    if (request.target === 'combat' && this.activePrimarySceneKey === 'CombatScene') {
      const scene = this.game.scene.getScene('CombatScene') as {
        rebindSession?: (context: { transitionId: number; sessionId?: number }) => void
      }

      if (scene && typeof scene.rebindSession === 'function') {
        return this.registerWaiter(sceneKey, transitionId, sessionId, currentGeneration, signal, () => {
          scene.rebindSession!({ transitionId, sessionId })
        })
      }
    }

    // Case 2: New primary scene activation
    this.stopActivePrimary()

    return this.registerWaiter(sceneKey, transitionId, sessionId, currentGeneration, signal, () => {
      this.activePrimarySceneKey = sceneKey
      this.game!.scene.start(sceneKey, { transitionId, sessionId })
    })
  }

  async deactivate(route: Route): Promise<void> {
    const sceneKey = PRIMARY_SCENE_ROUTES[route]
    if (sceneKey && this.activePrimarySceneKey === sceneKey) {
      this.stopActivePrimary()
    }
  }

  stopActivePrimary(): void {
    if (this.activePrimarySceneKey && this.game) {
      try {
        if (this.game.scene.isActive(this.activePrimarySceneKey)) {
          this.game.scene.stop(this.activePrimarySceneKey)
        }
      } catch {
        // Safe cleanup
      }
      this.activePrimarySceneKey = null
    }

    if (this.pendingWaiter) {
      this.pendingWaiter.reject(new Error('Scene activation cancelled'))
      this.pendingWaiter = null
    }
  }

  dispose(): void {
    if (this.disposed) return
    this.disposed = true
    this.stopActivePrimary()
    this.setGame(null)
    this.gameReadyResolvers.clear()
  }

  private registerWaiter(
    sceneKey: string,
    transitionId: number,
    sessionId: number | undefined,
    generation: number,
    signal: AbortSignal,
    trigger: () => void,
  ): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      let onAbort: (() => void) | undefined

      const cleanup = () => {
        if (onAbort) {
          signal.removeEventListener('abort', onAbort)
        }
      }

      onAbort = () => {
        if (this.pendingWaiter?.transitionId === transitionId) {
          this.pendingWaiter = null
        }
        cleanup()
        reject(new Error('Preparation aborted'))
      }

      signal.addEventListener('abort', onAbort, { once: true })

      this.pendingWaiter = {
        transitionId,
        sessionId,
        gameGeneration: generation,
        sceneKey,
        resolve: () => {
          cleanup()
          resolve()
        },
        reject: (err) => {
          cleanup()
          reject(err)
        },
      }

      try {
        trigger()
      } catch (err) {
        this.pendingWaiter = null
        cleanup()
        reject(err instanceof Error ? err : new Error(String(err)))
      }
    })
  }

  private waitForGameReady(signal: AbortSignal): Promise<void> {
    if (this.game) return Promise.resolve()

    return new Promise<void>((resolve, reject) => {
      const onAbort = () => {
        this.gameReadyResolvers.delete(resolver)
        reject(new Error('Game host wait aborted'))
      }

      const resolver = () => {
        signal.removeEventListener('abort', onAbort)
        resolve()
      }

      signal.addEventListener('abort', onAbort, { once: true })
      this.gameReadyResolvers.add(resolver)
    })
  }
}

import type {
  PresentationHold,
  SessionPresentationPort,
  SessionRef,
} from '../core/presentation/PresentationSession'

export type Route = 'boot' | 'auth' | 'character' | 'home' | 'combat' | 'tribulation' | 'error'

export type RouteRequest =
  | Readonly<{
      target: 'combat' | 'tribulation'
      session: SessionRef
      /**
       * Domain work with visible effect, executed inside the closed-curtain window.
       * Runs after the curtain is fully closed and before the target is revealed.
       * Returning false fails the transition.
       */
      behindCurtain?: () => boolean
    }>
  | Readonly<{
      target: 'combat' | 'tribulation'
      /**
       * Domain work with visible effect, executed inside the closed-curtain window.
       * Runs after the curtain is fully closed and before the target is revealed.
       * Returning false fails the transition. Required (not merely allowed) on
       * this arm: it is the ONLY source of a session for a combat/tribulation
       * request that does not already carry one - without it there would be
       * nothing to adopt in Step 6 of GamePresentationCoordinator.executeTransition.
       */
      behindCurtain: () => boolean
    }>
  | Readonly<{
      target: 'boot' | 'auth' | 'character' | 'home' | 'error'
      /**
       * Domain work with visible effect, executed inside the closed-curtain window.
       * Runs after the curtain is fully closed and before the target is revealed.
       * Returning false fails the transition.
       */
      behindCurtain?: () => boolean
    }>

export type Phase =
  | 'idle'
  | 'closing'
  | 'loading'
  | 'activating'
  | 'awaiting-ready'
  | 'opening'
  | 'failed'

export type TransitionResult = Readonly<{
  status: 'entered' | 'unchanged' | 'rejected' | 'failed'
  transitionId: number
}>

export interface RendererPort {
  prepare(request: RouteRequest, id: number, signal: AbortSignal): Promise<void>
  deactivate(route: Route): Promise<void>
}

export interface CurtainPort {
  close(id: number, signal: AbortSignal): Promise<void>
  open(id: number, signal: AbortSignal): Promise<void>
}

export interface AssetPort {
  ensureFor(request: RouteRequest, signal: AbortSignal): Promise<void>
}

export interface DeadlineScheduler {
  set(callback: () => void, ms: number): unknown
  clear(handle: unknown): void
}

export type BootSubphase = 'intro' | 'loading_save' | 'initializing' | null

export type CoordinatorError = Readonly<{
  message: string
  failedRequest: RouteRequest
  availableRenderer: Route | null
}>

export type CoordinatorSnapshot = Readonly<{
  currentRoute: Route
  renderRoute: Route | null
  /**
   * Target of the in-flight transition, known from the moment it is admitted -
   * before the curtain closes and long before renderRoute is set. Hosts that
   * must EXIST for a transition to progress (the Phaser canvas, whose loader
   * scene the asset phase needs) mount on this; route SCREENS still mount on
   * renderRoute, behind the closed curtain.
   */
  targetRoute: Route | null
  currentSession: SessionRef | null
  targetSession: SessionRef | null
  phase: Phase
  transitionId: number
  bootSubphase: BootSubphase
  showMainMenu: boolean
  error: CoordinatorError | null
}>

import type { InjectionKey } from 'vue'
import type { PhaserSceneAdapter } from './PhaserSceneAdapter'
import type { AssetBundleManager } from './assets/AssetBundleManager'
import type { VueRouteAdapter } from './VueRouteAdapter'

export const PHASER_SCENE_ADAPTER_KEY: InjectionKey<PhaserSceneAdapter> = Symbol('phaserSceneAdapter')
export const ASSET_BUNDLE_MANAGER_KEY: InjectionKey<AssetBundleManager> = Symbol('assetBundleManager')
export const VUE_ROUTE_ADAPTER_KEY: InjectionKey<VueRouteAdapter> = Symbol('vueRouteAdapter')
export const GAME_PRESENTATION_KEY: InjectionKey<import('./createGamePresentation').GamePresentation> = Symbol('gamePresentation')

export const ASSET_LOADER_SCENE_KEY = 'AssetLoaderScene'

import { beforeEach, describe, expect, it, vi } from 'vitest'
import {
  CompositeRenderer,
  createVueRouteAdapter,
  type VueRouteAdapter,
} from './VueRouteAdapter'
import { PhaserSceneAdapter } from './PhaserSceneAdapter'
import { GamePresentationCoordinator } from './GamePresentationCoordinator'
import { PresentationSession } from '../core/presentation/PresentationSession'

describe('CompositeRenderer and VueRouteAdapter', () => {
  let phaserAdapter: PhaserSceneAdapter
  let compositeRenderer: CompositeRenderer
  let coordinator: GamePresentationCoordinator
  let sessionPort: PresentationSession

  beforeEach(() => {
    sessionPort = new PresentationSession()
    phaserAdapter = new PhaserSceneAdapter()
    compositeRenderer = new CompositeRenderer(phaserAdapter)

    coordinator = new GamePresentationCoordinator({
      sessionPort,
      renderer: compositeRenderer,
      curtain: {
        close: vi.fn(async () => {}),
        open: vi.fn(async () => {}),
      },
      assets: {
        ensureFor: vi.fn(async () => {}),
      },
      initialRoute: 'home',
    })
  })

  it('CompositeRenderer awaits BOTH Vue ready and Phaser ready for Phaser routes', async () => {
    let resolvePhaser!: () => void
    const phaserPromise = new Promise<void>((resolve) => {
      resolvePhaser = resolve
    })

    phaserAdapter.prepare = vi.fn(async () => phaserPromise)

    const signal = new AbortController().signal
    const session = { kind: 'combat' as const, sessionId: 1 }

    const prepPromise = compositeRenderer.prepare(
      { target: 'combat', session },
      1,
      signal,
    )

    let isDone = false
    void prepPromise.then(() => {
      isDone = true
    })

    await Promise.resolve()
    expect(isDone).toBe(false)

    // 1. Vue reports ready -> still not done because Phaser is pending
    expect(compositeRenderer.reportVueReady(1)).toBe(true)
    await Promise.resolve()
    expect(isDone).toBe(false)

    // 2. Phaser finishes -> now both done!
    resolvePhaser()
    await prepPromise
    expect(isDone).toBe(true)
  })

  it('CompositeRenderer for non-Phaser route does not call phaserAdapter.prepare', async () => {
    phaserAdapter.prepare = vi.fn()

    const signal = new AbortController().signal
    const prepPromise = compositeRenderer.prepare({ target: 'auth' }, 2, signal)

    expect(phaserAdapter.prepare).not.toHaveBeenCalled()

    // Resolves once Vue reports ready
    compositeRenderer.reportVueReady(2)
    await expect(prepPromise).resolves.toBeUndefined()
  })

  it('VueRouteAdapter reflects coordinator snapshot and activeRoute accurately', async () => {
    const adapter = createVueRouteAdapter(coordinator, compositeRenderer)

    expect(adapter.currentRoute.value).toBe('home')
    expect(adapter.renderRoute.value).toBeNull()
    expect(adapter.activeRoute.value).toBe('home')
    expect(adapter.isTransitioning.value).toBe(false)
    expect(adapter.isLocked.value).toBe(false)

    // Start transition to combat (stub phaserAdapter so it doesn't wait for a game host)
    phaserAdapter.prepare = vi.fn(async () => {})
    const session = { kind: 'combat' as const, sessionId: 2 }
    sessionPort.begin(session, 'interactive')

    // Prepare holds until Vue reports ready
    const requestPromise = coordinator.request({ target: 'combat', session })

    // During transition behind curtain: renderRoute is target
    for (let i = 0; i < 20 && adapter.phase.value !== 'awaiting-ready'; i++) {
      await Promise.resolve()
    }

    expect(adapter.renderRoute.value).toBe('combat')
    expect(adapter.activeRoute.value).toBe('combat')
    expect(adapter.currentRoute.value).toBe('home') // committed route stays home until READY
    expect(adapter.isTransitioning.value).toBe(true)
    expect(adapter.isLocked.value).toBe(true)

    // Report Vue ready
    adapter.reportVueReady(adapter.transitionId.value)

    const result = await requestPromise
    expect(result.status).toBe('entered')

    // After commit and reveal
    expect(adapter.currentRoute.value).toBe('combat')
    expect(adapter.renderRoute.value).toBeNull()
    expect(adapter.activeRoute.value).toBe('combat')
    expect(adapter.isTransitioning.value).toBe(false)
    expect(adapter.isLocked.value).toBe(false)

    adapter.dispose()
  })
})

/**
 * VueRouteAdapter (AstraDoctrine Law A5, A7, AGENTS.md P17).
 * Reactive bridge from GamePresentationCoordinator to Vue templates,
 * and composite renderer coordinating Vue mount readiness with Phaser scene readiness.
 *
 * Invariant:
 * - Readonly reactive view of coordinator snapshots; does not expose route setters.
 * - renderRoute controls target mount behind the curtain.
 * - Composite renderer prepare awaits Vue READY plus Phaser READY for Phaser-backed routes.
 * - Non-Phaser routes (boot, auth, character, error) do not wait for Phaser.
 */

import { computed, nextTick, readonly, shallowRef, type ComputedRef, type Ref } from 'vue'
import type {
  BootSubphase,
  CoordinatorError,
  CoordinatorSnapshot,
  Phase,
  RendererPort,
  Route,
  RouteRequest,
} from './PresentationContracts'
import { PRIMARY_SCENE_ROUTES, type PhaserSceneAdapter } from './PhaserSceneAdapter'
import { GamePresentationCoordinator } from './GamePresentationCoordinator'
import type { SessionRef } from '../core/presentation/PresentationSession'

export class CompositeRenderer implements RendererPort {
  private pendingVueWaiter: {
    transitionId: number
    route: Route
    resolve: () => void
    reject: (err: Error) => void
  } | null = null

  /**
   * Routes whose Vue tree is currently mounted. This is evidence reported by
   * the mounted component itself - a timer or a snapshot notification only
   * proves the coordinator changed state, not that anything rendered.
   */
  private readonly mountedRoutes = new Set<Route>()

  constructor(private readonly phaserAdapter: PhaserSceneAdapter) {}

  markRouteMounted(route: Route): void {
    this.mountedRoutes.add(route)

    if (this.pendingVueWaiter?.route === route) {
      this.reportVueReady(this.pendingVueWaiter.transitionId)
    }
  }

  markRouteUnmounted(route: Route): void {
    this.mountedRoutes.delete(route)
  }

  isRouteMounted(route: Route): boolean {
    return this.mountedRoutes.has(route)
  }

  reportVueReady(transitionId: number): boolean {
    if (this.pendingVueWaiter && this.pendingVueWaiter.transitionId === transitionId) {
      const resolve = this.pendingVueWaiter.resolve
      this.pendingVueWaiter = null
      resolve()
      return true
    }
    return false
  }

  hasPendingVueWaiter(transitionId?: number): boolean {
    if (transitionId !== undefined) {
      return this.pendingVueWaiter?.transitionId === transitionId
    }
    return this.pendingVueWaiter !== null
  }

  async prepare(request: RouteRequest, transitionId: number, signal: AbortSignal): Promise<void> {
    if (signal.aborted) {
      throw new Error('Preparation aborted')
    }

    const vuePromise = new Promise<void>((resolve, reject) => {
      const onAbort = () => {
        if (this.pendingVueWaiter?.transitionId === transitionId) {
          this.pendingVueWaiter = null
        }
        reject(new Error('Preparation aborted'))
      }

      signal.addEventListener('abort', onAbort, { once: true })

      this.pendingVueWaiter = {
        transitionId,
        route: request.target,
        resolve: () => {
          signal.removeEventListener('abort', onAbort)
          resolve()
        },
        reject: (err) => {
          signal.removeEventListener('abort', onAbort)
          reject(err)
        },
      }

      // Already mounted (re-entering a route whose tree stays alive, e.g. a
      // combat rebind under the same GameRoot) resolves without waiting.
      if (this.mountedRoutes.has(request.target)) {
        this.reportVueReady(transitionId)
      }
    })

    const isPhaserRoute = Boolean(PRIMARY_SCENE_ROUTES[request.target])
    if (isPhaserRoute) {
      await Promise.all([
        vuePromise,
        this.phaserAdapter.prepare(request, transitionId, signal),
      ])
    } else {
      await vuePromise
    }
  }

  async deactivate(route: Route): Promise<void> {
    await this.phaserAdapter.deactivate(route)
  }
}

export interface VueRouteAdapter {
  readonly currentRoute: Ref<Route>
  readonly renderRoute: Ref<Route | null>
  readonly targetRoute: Ref<Route | null>
  readonly activeRoute: ComputedRef<Route>
  readonly currentSession: Ref<SessionRef | null>
  readonly targetSession: Ref<SessionRef | null>
  readonly phase: Ref<Phase>
  readonly transitionId: Ref<number>
  readonly bootSubphase: Ref<BootSubphase>
  readonly showMainMenu: Ref<boolean>
  readonly error: Ref<CoordinatorError | null>
  readonly isTransitioning: ComputedRef<boolean>
  readonly isLocked: ComputedRef<boolean>
  reportVueReady(transitionId: number): boolean
  markRouteMounted(route: Route): void
  markRouteUnmounted(route: Route): void
  dispose(): void
}

export function createVueRouteAdapter(
  coordinator: GamePresentationCoordinator,
  compositeRenderer: CompositeRenderer,
): VueRouteAdapter {
  const currentSnapshot = coordinator.getSnapshot()

  const currentRoute = shallowRef<Route>(currentSnapshot.currentRoute)
  const renderRoute = shallowRef<Route | null>(currentSnapshot.renderRoute)
  const targetRoute = shallowRef<Route | null>(currentSnapshot.targetRoute)
  const currentSession = shallowRef<SessionRef | null>(currentSnapshot.currentSession)
  const targetSession = shallowRef<SessionRef | null>(currentSnapshot.targetSession)
  const phase = shallowRef<Phase>(currentSnapshot.phase)
  const transitionId = shallowRef<number>(currentSnapshot.transitionId)
  const bootSubphase = shallowRef<BootSubphase>(currentSnapshot.bootSubphase)
  const showMainMenu = shallowRef<boolean>(currentSnapshot.showMainMenu)
  const error = shallowRef<CoordinatorError | null>(currentSnapshot.error)

  const activeRoute = computed<Route>(() => renderRoute.value ?? currentRoute.value)
  const isTransitioning = computed<boolean>(
    () => phase.value !== 'idle' && phase.value !== 'failed',
  )
  const isLocked = computed<boolean>(() => phase.value !== 'idle')

  const unsubscribe = coordinator.subscribe((snapshot) => {
    currentRoute.value = snapshot.currentRoute
    renderRoute.value = snapshot.renderRoute
    targetRoute.value = snapshot.targetRoute
    currentSession.value = snapshot.currentSession
    targetSession.value = snapshot.targetSession
    phase.value = snapshot.phase
    transitionId.value = snapshot.transitionId
    bootSubphase.value = snapshot.bootSubphase
    showMainMenu.value = snapshot.showMainMenu
    error.value = snapshot.error
  })

  function reportVueReady(id: number): boolean {
    return compositeRenderer.reportVueReady(id)
  }

  /**
   * Called by the component that renders a route, on mount. Deferred one tick
   * so the whole subtree (overlays/chrome inside it) has flushed before the
   * route claims to be ready.
   */
  function markRouteMounted(route: Route): void {
    void nextTick(() => {
      compositeRenderer.markRouteMounted(route)
    })
  }

  function markRouteUnmounted(route: Route): void {
    compositeRenderer.markRouteUnmounted(route)
  }

  function dispose(): void {
    unsubscribe()
  }

  return {
    currentRoute: readonly(currentRoute) as Ref<Route>,
    renderRoute: readonly(renderRoute) as Ref<Route | null>,
    targetRoute: readonly(targetRoute) as Ref<Route | null>,
    activeRoute,
    currentSession: readonly(currentSession) as Ref<SessionRef | null>,
    targetSession: readonly(targetSession) as Ref<SessionRef | null>,
    phase: readonly(phase) as Ref<Phase>,
    transitionId: readonly(transitionId) as Ref<number>,
    bootSubphase: readonly(bootSubphase) as Ref<BootSubphase>,
    showMainMenu: readonly(showMainMenu) as Ref<boolean>,
    error: readonly(error) as Ref<CoordinatorError | null>,
    isTransitioning,
    isLocked,
    reportVueReady,
    markRouteMounted,
    markRouteUnmounted,
    dispose,
  }
}

import { describe, expect, it } from 'vitest'
import {
  enumerateResources,
  getBundleDescriptors,
  getBundlesForRoute,
  getCombatDescriptors,
  getCoreUiDescriptors,
  getHomeDescriptors,
  getTribulationDescriptors,
} from './AssetBundleCatalog'
import {
  ENEMY_TEMPLATE_IDS,
  PLAYER_TEXTURE_KEY,
  queueCombatAssets,
} from '@/game/support/CombatPreload'
import { GOURD_TEXTURE_KEY } from '@/game/support/RewardGourd'
import { resolveEnemyTextureKey } from '@/game/support/EnemyArt'
import { PLAYER_VISUAL_PROFILES } from '@/presentation/art/PlayerVisualProfiles'
import { animatedCombatEntities } from '@/presentation/art/CombatPresentationCatalogue'

describe('AssetBundleCatalog', () => {
  it('core-ui contains ink-wash-ui atlas descriptor', () => {
    const descriptors = getCoreUiDescriptors()
    expect(descriptors).toHaveLength(1)
    expect(descriptors[0]!.kind).toBe('atlas')
    expect(descriptors[0]!.key).toBe('ink-wash-ui')
  })

  it('Home contains player standing/cultivate textures and Dong Fu layers, but NOT enemies or gourd', () => {
    const descriptors = getHomeDescriptors()
    const keys = new Set(descriptors.map((d) => d.key))

    // Must contain player profile keys
    for (const profile of Object.values(PLAYER_VISUAL_PROFILES)) {
      expect(keys.has(profile.combatTextureKey)).toBe(true)
      if (profile.cultivateTextureKey) {
        expect(keys.has(profile.cultivateTextureKey)).toBe(true)
      }
    }

    // Must contain Dong Fu layers (dom-image)
    const domLayers = descriptors.filter((d) => d.kind === 'dom-image')
    expect(domLayers.length).toBe(10)

    // MUST NOT contain enemies or gourd (lazy asset preservation)
    expect(keys.has(GOURD_TEXTURE_KEY)).toBe(false)
    for (const templateId of ENEMY_TEMPLATE_IDS) {
      const enemyKey = resolveEnemyTextureKey(templateId)
      if (enemyKey) {
        expect(keys.has(enemyKey)).toBe(false)
      }
    }
  })

  it('combat descriptors match the keys queued by queueCombatAssets wrapper', () => {
    const queuedKeys = new Set<string>()
    const fakeScene = {
      textures: { exists: () => false },
      load: {
        image: (key: string) => queuedKeys.add(key),
        atlas: (key: string) => queuedKeys.add(key),
      },
    } as never

    queueCombatAssets(fakeScene)

    const descriptors = getCombatDescriptors()
    const catalogKeys = new Set(descriptors.map((d) => d.key))

    // Every key queued by the legacy wrapper must be enumerated by catalog
    for (const key of queuedKeys) {
      expect(catalogKeys.has(key)).toBe(true)
    }

    // Must contain animation sheet keys
    for (const { clips } of animatedCombatEntities()) {
      for (const clip of Object.values(clips)) {
        expect(catalogKeys.has(clip.sheetKey)).toBe(true)
      }
    }
  })

  it('tribulation descriptors contain char-cultivate multiatlas and ink-wash-ui atlas', () => {
    const descriptors = getTribulationDescriptors()
    const keys = descriptors.map((d) => d.key)
    expect(keys).toContain('char-cultivate')
    expect(keys).toContain('ink-wash-ui')
  })

  it('routes that render before a Phaser host exists require no Phaser bundle', () => {
    // Regression: 'core-ui' is a Phaser atlas. Requiring it for boot/auth/
    // character/error made those transitions wait on a loader scene that only
    // exists once PhaserCanvas mounts - they timed out and left the
    // coordinator stuck off-route for the rest of the session.
    expect(getBundlesForRoute('boot')).toEqual([])
    expect(getBundlesForRoute('auth')).toEqual([])
    expect(getBundlesForRoute('character')).toEqual([])
    expect(getBundlesForRoute('error')).toEqual([])
  })

  it('Phaser-backed routes require core-ui plus their own bundle', () => {
    expect(getBundlesForRoute('home')).toEqual(['core-ui', 'home'])
    expect(getBundlesForRoute('combat')).toEqual(['core-ui', 'combat'])
    expect(getBundlesForRoute('tribulation')).toEqual(['core-ui', 'tribulation'])
  })

  it('enumerateResources deduplicates keys across combined bundles', () => {
    const enumerated = enumerateResources(['core-ui', 'home', 'combat', 'tribulation'])
    const keys = enumerated.map((d) => d.key)
    const uniqueKeys = new Set(keys)

    expect(keys.length).toBe(uniqueKeys.size)
    expect(keys).toContain('ink-wash-ui')
    expect(keys).toContain('char-cultivate')
    expect(keys).toContain(PLAYER_TEXTURE_KEY)
  })
})

/**
 * AssetBundleCatalog (AstraDoctrine Law A10, AGENTS.md P17).
 * Central catalog of resource descriptors for each presentation bundle.
 *
 * Bundles:
 * - 'core-ui': common required UI assets (ink-wash-ui atlas).
 * - 'home': player standing/cultivate textures and Dong Fu modular DOM layers.
 * - 'combat': backdrop, player combat art, enemy sprites, gourd, animation sheets.
 * - 'tribulation': cultivate multiatlas, ink-wash-ui.
 */

import type { Route } from '../PresentationContracts'
import {
  INK_WASH_UI_ATLAS_DATA_URL,
  INK_WASH_UI_ATLAS_IMAGE_URL,
  INK_WASH_UI_ATLAS_KEY,
} from '@/game/support/InkWashUiPhaser'
import {
  dongFuLayerList,
  type DongFuLayerDescriptor,
} from '@/presentation/background/DongFuArt'
import {
  peekThanhVanVariant,
  thanhVanLoadList,
} from '@/presentation/background/ThanhVanBackdropArt'
import {
  ENEMY_TEMPLATE_IDS,
  PLAYER_TEXTURE_KEY,
  PLAYER_TEXTURE_URL,
} from '@/game/support/CombatPreload'
import {
  GOURD_TEXTURE_KEY,
  GOURD_TEXTURE_URL,
} from '@/game/support/RewardGourd'
import {
  enemyTextureUrl,
  resolveEnemyTextureKey,
} from '@/game/support/EnemyArt'
import { PLAYER_VISUAL_PROFILES } from '@/presentation/art/PlayerVisualProfiles'
import { animatedCombatEntities } from '@/presentation/art/CombatPresentationCatalogue'

export type AssetBundleId = 'core-ui' | 'home' | 'combat' | 'tribulation'

export type ImageResourceDescriptor = Readonly<{
  kind: 'image'
  key: string
  url: string
}>

export type SpritesheetResourceDescriptor = Readonly<{
  kind: 'spritesheet'
  key: string
  url: string
  frameWidth: number
  frameHeight: number
}>

export type AtlasResourceDescriptor = Readonly<{
  kind: 'atlas'
  key: string
  textureUrl: string
  atlasUrl: string
}>

export type MultiAtlasResourceDescriptor = Readonly<{
  kind: 'multiatlas'
  key: string
  jsonUrl: string
  basePath?: string
}>

export type DomImageResourceDescriptor = Readonly<{
  kind: 'dom-image'
  key: string
  url: string
}>

export type AssetResourceDescriptor =
  | ImageResourceDescriptor
  | SpritesheetResourceDescriptor
  | AtlasResourceDescriptor
  | MultiAtlasResourceDescriptor
  | DomImageResourceDescriptor

export function getCoreUiDescriptors(): readonly AssetResourceDescriptor[] {
  return [
    {
      kind: 'atlas',
      key: INK_WASH_UI_ATLAS_KEY,
      textureUrl: INK_WASH_UI_ATLAS_IMAGE_URL,
      atlasUrl: INK_WASH_UI_ATLAS_DATA_URL,
