}

export function getHomeDescriptors(): readonly AssetResourceDescriptor[] {
  const descriptors: AssetResourceDescriptor[] = []
  const seenKeys = new Set<string>()

  // Player textures required by Home (both standing and cultivate poses for all profiles)
  for (const profile of Object.values(PLAYER_VISUAL_PROFILES)) {
    if (!seenKeys.has(profile.combatTextureKey)) {
      seenKeys.add(profile.combatTextureKey)
      descriptors.push({
        kind: 'image',
        key: profile.combatTextureKey,
        url: profile.combatTextureUrl,
      })
    }

    if (profile.cultivateTextureKey && profile.cultivateTextureUrl && !seenKeys.has(profile.cultivateTextureKey)) {
      seenKeys.add(profile.cultivateTextureKey)
      descriptors.push({
        kind: 'image',
        key: profile.cultivateTextureKey,
        url: profile.cultivateTextureUrl,
      })
    }
  }

  // Dong Fu DOM layers (for the current variant)
  const variant = peekThanhVanVariant()
  for (const layer of dongFuLayerList(variant)) {
    descriptors.push({
      kind: 'dom-image',
      key: layer.key,
      url: layer.url,
    })
  }

  return descriptors
}

export function getCombatDescriptors(): readonly AssetResourceDescriptor[] {
  const descriptors: AssetResourceDescriptor[] = []
  const seenKeys = new Set<string>()

  const addImage = (key: string, url: string) => {
    if (seenKeys.has(key)) return
    seenKeys.add(key)
    descriptors.push({ kind: 'image', key, url })
  }

  // Mortal fallback player art
  addImage(PLAYER_TEXTURE_KEY, PLAYER_TEXTURE_URL)

  // Thanh Van modular backdrop layers
  for (const entry of thanhVanLoadList(peekThanhVanVariant())) {
    addImage(entry.key, entry.url)
  }

  // Reward Gourd art
  addImage(GOURD_TEXTURE_KEY, GOURD_TEXTURE_URL)

  // Mortal enemy batch textures
  for (const templateId of ENEMY_TEMPLATE_IDS) {
    const textureKey = resolveEnemyTextureKey(templateId)
    if (textureKey) {
      addImage(textureKey, enemyTextureUrl(textureKey))
    }
  }

  // Player profiles combat & cultivate textures
  for (const profile of Object.values(PLAYER_VISUAL_PROFILES)) {
    addImage(profile.combatTextureKey, profile.combatTextureUrl)
    if (profile.cultivateTextureKey && profile.cultivateTextureUrl) {
      addImage(profile.cultivateTextureKey, profile.cultivateTextureUrl)
    }
  }

  // Character animation atlases (Spec B §3.1) — one entry per distinct sheet,
  // however many entities and clips share it.
  for (const { clips } of animatedCombatEntities()) {
    for (const clip of Object.values(clips)) {
      if (seenKeys.has(clip.sheetKey)) continue
      seenKeys.add(clip.sheetKey)
      descriptors.push({
        kind: 'atlas',
        key: clip.sheetKey,
        textureUrl: clip.sheetUrl,
        atlasUrl: clip.atlasUrl,
      })
    }
  }

  return descriptors
}

export function getTribulationDescriptors(): readonly AssetResourceDescriptor[] {
  return [
    {
      kind: 'multiatlas',
      key: 'char-cultivate',
      jsonUrl: 'assets/cultivate.json',
      basePath: 'assets',
    },
    {
      kind: 'atlas',
      key: INK_WASH_UI_ATLAS_KEY,
      textureUrl: INK_WASH_UI_ATLAS_IMAGE_URL,
      atlasUrl: INK_WASH_UI_ATLAS_DATA_URL,
    },
  ]
}

export function getBundleDescriptors(bundleId: AssetBundleId): readonly AssetResourceDescriptor[] {
  switch (bundleId) {
    case 'core-ui':
      return getCoreUiDescriptors()
    case 'home':
      return getHomeDescriptors()
    case 'combat':
      return getCombatDescriptors()
    case 'tribulation':
      return getTribulationDescriptors()
  }
}

/**
 * Bundles a route must have loaded before it can be revealed.
 *
 * Only routes that activate a Phaser primary scene require Phaser-loaded
 * bundles. boot/auth/character/error render as plain Vue before any Phaser
 * host exists, so requiring 'core-ui' (a Phaser atlas) there would block on a
 * loader that cannot exist yet - the transition would sit until its deadline
 * and fail, leaving the coordinator stuck off-route for the rest of the
 * session. A route's asset requirement must be satisfiable by the renderer
 * that route actually uses.
 */
export function getBundlesForRoute(target: Route): readonly AssetBundleId[] {
  switch (target) {
    case 'home':
      return ['core-ui', 'home']
    case 'combat':
      return ['core-ui', 'combat']
    case 'tribulation':
      return ['core-ui', 'tribulation']
    case 'boot':
    case 'auth':
    case 'character':
    case 'error':
      return []
  }
}

export function enumerateResources(
  bundleIds: readonly AssetBundleId[],
): readonly AssetResourceDescriptor[] {
  const result: AssetResourceDescriptor[] = []
  const seenKeys = new Set<string>()

  for (const bundleId of bundleIds) {
    for (const descriptor of getBundleDescriptors(bundleId)) {
      if (seenKeys.has(descriptor.key)) continue
      seenKeys.add(descriptor.key)
      result.push(descriptor)
    }
  }

  return result
}

import { beforeEach, describe, expect, it, vi } from 'vitest'
import {
  AssetBundleManager,
  type DomImageLoader,
} from './AssetBundleManager'
import type { AssetResourceDescriptor } from './AssetBundleCatalog'
import type { AssetLoaderScene } from '@/game/scenes/AssetLoaderScene'

function createMockLoaderScene() {
  const loadedKeys = new Set<string>()
  const loadCalls: AssetResourceDescriptor[][] = []

  const mock = {
    isTextureLoaded: (key: string) => loadedKeys.has(key),
    loadDescriptors: vi.fn(async (descriptors: readonly AssetResourceDescriptor[]) => {
      loadCalls.push([...descriptors])
      for (const d of descriptors) {
        loadedKeys.add(d.key)
      }
    }),
    _loadedKeys: loadedKeys,
    _loadCalls: loadCalls,
  } as unknown as AssetLoaderScene & {
    _loadedKeys: Set<string>
    _loadCalls: AssetResourceDescriptor[][]
  }

  return mock
}

describe('AssetBundleManager', () => {
  let loaderScene: ReturnType<typeof createMockLoaderScene>
  let domImageCalls: string[]
  let domImageLoader: DomImageLoader

  beforeEach(() => {
    loaderScene = createMockLoaderScene()
    domImageCalls = []
    domImageLoader = vi.fn(async (url: string) => {
      domImageCalls.push(url)
    })
  })

  function createManager() {
    return new AssetBundleManager({
      loaderScene,
      domImageLoader,
    })
  }

  it('cached ensure resolves without repeating physical loads', async () => {
    const manager = createManager()

    await manager.ensureLoaded(['core-ui'])
    expect(loaderScene._loadCalls.length).toBe(1)

    // Second call is fully cached
    await manager.ensureLoaded(['core-ui'])
    expect(loaderScene._loadCalls.length).toBe(1)
  })

  it('concurrent ensure and prefetch deduplicate into one physical request', async () => {
    let resolveLoad!: () => void
    const blocker = new Promise<void>((resolve) => {
      resolveLoad = resolve
    })

    loaderScene.loadDescriptors = vi.fn(async (descriptors) => {
      await blocker
      for (const d of descriptors) {
        loaderScene._loadedKeys.add(d.key)
      }
    })

    const manager = createManager()

    const ensurePromise = manager.ensureLoaded(['core-ui'])
    const prefetchPromise = manager.prefetch(['core-ui'])

    resolveLoad()
    await Promise.all([ensurePromise, prefetchPromise])

    expect(loaderScene.loadDescriptors).toHaveBeenCalledTimes(1)
  })

  it('cancel A while B succeeds: A rejects with aborted, B resolves successfully', async () => {
    let resolveLoad!: () => void
    const blocker = new Promise<void>((resolve) => {
      resolveLoad = resolve
    })

    const hangingDomLoader: DomImageLoader = vi.fn(async (url, signal) => {
      await blocker
    })

    const manager = new AssetBundleManager({
      loaderScene,
      domImageLoader: hangingDomLoader,
    })

    const controllerA = new AbortController()

    const callA = manager.ensureLoaded(['home'], controllerA.signal)
    const callB = manager.ensureLoaded(['home']) // no abort signal

    controllerA.abort()

    await expect(callA).rejects.toThrow('Load aborted')

    resolveLoad()
    await expect(callB).resolves.toBeUndefined()
  })

  it('detects and rejects descriptor collisions with diagnostic message', async () => {
    const manager = createManager()

    // Prime a key
    await manager.ensureLoaded(['core-ui'])

    // Attempting to ensure a conflicting descriptor with same key but different URL
    const conflicting = [
      {
        kind: 'image' as const,
        key: 'ink-wash-ui', // collision with atlas key in core-ui
        url: '/assets/different/path.png',
      },
    ]

    expect(() => {
      // @ts-expect-error private method test
      manager.validateDescriptorCollisions(conflicting)
    }).toThrow(/Asset descriptor collision for key "ink-wash-ui"/)
  })

  it('handles error then retry: failed load rejects, subsequent retry succeeds', async () => {
    let shouldFail = true
    loaderScene.loadDescriptors = vi.fn(async (descriptors) => {
      if (shouldFail) {
        throw new Error('Network error during physical load')
      }
      for (const d of descriptors) {
        loaderScene._loadedKeys.add(d.key)
      }
    })

    const manager = createManager()

    await expect(manager.ensureLoaded(['core-ui'])).rejects.toThrow('Network error')
    expect(manager.isLoaded('core-ui')).toBe(false)

    // Retry succeeds
    shouldFail = false
    await manager.ensureLoaded(['core-ui'])
    expect(manager.isLoaded('core-ui')).toBe(true)
  })

  it('prefetch rejection is handled gracefully and does not throw', async () => {
    loaderScene.loadDescriptors = vi.fn(async () => {
      throw new Error('Prefetch failed')
    })

    const manager = createManager()

    // Prefetch must not throw
    await expect(manager.prefetch(['combat'])).resolves.toBeUndefined()
  })

  it('clears cache when loader scene is replaced (game destroyed / recreated)', async () => {
    const manager = createManager()

    await manager.ensureLoaded(['core-ui'])
    expect(manager.isLoaded('core-ui')).toBe(true)

    // New game instance creates new loader scene
    const newLoaderScene = createMockLoaderScene()
    manager.setLoaderScene(newLoaderScene)

    // Fresh game cache is empty
    expect(manager.isLoaded('core-ui')).toBe(false)
  })

  it('implements AssetPort.ensureFor routing target to corresponding bundles', async () => {
    const manager = createManager()
    const ensureSpy = vi.spyOn(manager, 'ensureLoaded')

    const signal = new AbortController().signal

    await manager.ensureFor({ target: 'home' }, signal)
    expect(ensureSpy).toHaveBeenCalledWith(['core-ui', 'home'], signal)

    await manager.ensureFor(
      { target: 'combat', session: { kind: 'combat', sessionId: 1 } },
      signal,
    )
    expect(ensureSpy).toHaveBeenCalledWith(['core-ui', 'combat'], signal)

    await manager.ensureFor(
      { target: 'tribulation', session: { kind: 'tribulation', sessionId: 2 } },
      signal,
    )
    expect(ensureSpy).toHaveBeenCalledWith(['core-ui', 'tribulation'], signal)
  })
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
