    const unequipSpy = vi.spyOn(gameManager.equipmentOps, 'unequipAllEquipment')

    // Simulate active battle
    vi.spyOn(gameManager, 'getBattle').mockReturnValue({
      state: 'fighting',
      id: 'mock_battle',
      player: {} as any,
      enemies: [],
    } as any)

    const started = await triggerBreakthroughAction(playerWithGear, gameManager, presentation)
    expect(started).toBe(false)

    // Unequip must NOT have been called!
    expect(unequipSpy).not.toHaveBeenCalled()
  })

  it('duplicate outcome check after clear is no-op and does not double-settle', async () => {
    const fakeGame = {
      scene: {
        isActive: () => true,
        start: vi.fn(),
        stop: vi.fn(),
        getScene: vi.fn(() => null),
      },
    } as any
    phaserAdapter.setGame(fakeGame)

    // Start in headless mode
    gameManager.setPresentationMode('headless')
    gameManager.startTribulation(player, calculateStats(player.baseStats, []), 'qi_refining')

    const active = gameManager.tribulationDirector.getState()!
    expect(active).toBeDefined()

    // The session-started event kicked off the home -> tribulation entry
    // transition; it is still in-flight here, and an outcome request issued
    // now would be rejected. In the real app the tick loop retries the
    // pending outcome until it lands - the test drives entry to completion
    // first (same readiness dance as the interactive-hold test above).
    await vi.waitFor(() => {
      expect(vueAdapter.phase.value).toBe('awaiting-ready')
    })
    const entrySession = gameManager.getCurrentPresentationSession()!
    phaserAdapter.reportReady({
      transitionId: vueAdapter.transitionId.value,
      sessionId: entrySession.sessionId,
    })
    vueAdapter.reportVueReady(vueAdapter.transitionId.value)
    await vi.waitFor(() => {
      expect(coordinator.getSnapshot().phase).toBe('idle')
      expect(coordinator.getSnapshot().currentRoute).toBe('tribulation')
    })

    // Force victory
    active.state = 'victory'

    const playerStoreMock = {
      $state: player,
      realmId: 'mortal',
      realmLevel: 10,
      cultivation: 1000,
      selectedTalentIds: [],
    } as any

    // First check issues the home transition; the outcome work itself runs
    // inside the closed-curtain window, so the clear lands after the mocked
    // curtain resolves - a few microtasks, not synchronously.
    const firstCheck = checkTribulationOutcomeAction(playerStoreMock, gameManager, presentation)
    expect(firstCheck).toBe(true)
    await vi.waitFor(() => {
      expect(gameManager.tribulationDirector.getState()).toBeNull()
    })

    // Second check is safe no-op
    const secondCheck = checkTribulationOutcomeAction(playerStoreMock, gameManager, presentation)
    expect(secondCheck).toBe(false)
  })

  it('production outcome check (presentation wired, as App.vue calls it) routes home', async () => {
    const fakeGame = {
      scene: {
        isActive: () => true,
        start: vi.fn(),
        stop: vi.fn(),
        getScene: vi.fn(() => null),
      },
    } as any
    phaserAdapter.setGame(fakeGame)

    // Same headless entry dance as the duplicate-outcome test above.
    gameManager.setPresentationMode('headless')
    gameManager.startTribulation(player, calculateStats(player.baseStats, []), 'qi_refining')

    await vi.waitFor(() => {
      expect(vueAdapter.phase.value).toBe('awaiting-ready')
    })
    const entrySession = gameManager.getCurrentPresentationSession()!
    phaserAdapter.reportReady({
      transitionId: vueAdapter.transitionId.value,
      sessionId: entrySession.sessionId,
    })
    vueAdapter.reportVueReady(vueAdapter.transitionId.value)
    await vi.waitFor(() => {
      expect(coordinator.getSnapshot().phase).toBe('idle')
      expect(coordinator.getSnapshot().currentRoute).toBe('tribulation')
    })

    const active = gameManager.tribulationDirector.getState()!
    active.state = 'victory'

    const playerStoreMock = {
      $state: player,
      realmId: 'mortal',
      realmLevel: 10,
      cultivation: 1000,
      selectedTalentIds: [],
    } as any

    // This is the exact call signature App.vue's tick() uses in
    // production after the F1 fix: the presentation argument routes the
    // outcome through the coordinator, so request({ target: 'home' }) is
    // issued and the route can leave 'tribulation'. Before the fix
    // App.vue omitted the third argument: the outcome was applied
    // (director cleared) but the coordinator's route could never leave
    // 'tribulation' - home chrome stayed hidden, the overlay rendered
    // nothing (active === null), and the TribulationScene was never
    // deactivated. Soft-lock until reload. The static guard in
    // tests/architecture/tribulationOutcomeWiring.test.ts pins the
    // 3-argument call site so the wiring cannot silently regress.
    const handled = checkTribulationOutcomeAction(playerStoreMock, gameManager, presentation)
    expect(handled).toBe(true)

    // The outcome work runs inside the closed-curtain window (the
    // director clears on a microtask), then the home transition does the
    // same readiness dance as the tribulation entry above: the
    // coordinator holds at awaiting-ready until Phaser (MainScene) and
    // Vue report.
    await vi.waitFor(() => {
      expect(gameManager.tribulationDirector.getState()).toBeNull()
      expect(vueAdapter.phase.value).toBe('awaiting-ready')
    })

    phaserAdapter.reportReady({ transitionId: vueAdapter.transitionId.value })
    vueAdapter.reportVueReady(vueAdapter.transitionId.value)

    await vi.waitFor(() => {
      expect(coordinator.getSnapshot().phase).toBe('idle')
      expect(coordinator.getSnapshot().currentRoute).toBe('home')
    })
  })

  it('stale READY is rejected by phaserAdapter', () => {
    const readyAccepted = phaserAdapter.reportReady({
      transitionId: 9999, // Stale transition
      sessionId: 888,
    })
    expect(readyAccepted).toBe(false)
  })
})

// @vitest-environment jsdom
//
// Development-phase save policy (dong-fu-command-wheel-inventory-spirit-
// stone-plan.md §"Chính sách migration và an toàn ghi đè") — auto-
// migrate v42/v43 đã retire: MỌI version cũ hơn CURRENT_SAVE_VERSION
// trả về 'incompatible' và KHÔNG ĐƯỢC phát sinh bất kỳ write nào vào
// localStorage (không ghi đè save gốc, không tạo backup, không đụng
// revision key). Người chơi xử lý qua SaveIncompatibleScreen
// (Export/Xoá) thay vì bị migrate âm thầm.
import { beforeEach, describe, expect, it } from 'vitest'
import { CURRENT_SAVE_VERSION, loadGame } from './SaveSystem'
import { createDefaultPlayer } from '../../core/player/Player'

function writeRawSave(version: number): string {
  const raw = JSON.stringify({
    version,

    player: { name: 'Test', spiritStone: 500 },

    materials: [{ materialId: 'legacy_material', amount: 3 }],
  })

  localStorage.setItem('tien-hiep-idle-save', raw)

  return raw
}

// Save version hiện hành phải nguyên shape theo validateGameSaveShape —
// fixture tối thiểu như writeRawSave không còn qua cửa load (đúng thiết
// kế mới của save-shape-validation-plan.md).
function writeValidCurrentSave(): string {
  const raw = JSON.stringify({
    version: CURRENT_SAVE_VERSION,

    player: { ...createDefaultPlayer(), name: 'Test' },

    techniques: [],
    skills: [],
    materials: [],
    equipment: [],
    pills: [],
    talismans: [],
    formations: [],
    buildings: [],
    equipmentSlots: [],
  })

  localStorage.setItem('tien-hiep-idle-save', raw)

  return raw
}

describe('loadGame — retirement của auto-migration (v42–v46)', () => {
  beforeEach(() => {
    localStorage.clear()
  })

  for (const version of [42, 43, 44, 45, 46, 54]) {
    it(`version ${version} → incompatible, KHÔNG write nào phát sinh`, () => {
      const raw = writeRawSave(version)

      const outcome = loadGame()

      expect(outcome).toEqual({ status: 'incompatible', foundVersion: version, raw })

      // Save gốc KHÔNG bị ghi đè/migrate.
      expect(localStorage.getItem('tien-hiep-idle-save')).toBe(raw)

      // Không backup/revision nào được tạo từ đường load.
      expect(localStorage.getItem('tien-hiep-idle-save-backup')).toBeNull()
      expect(localStorage.getItem('tien-hiep-idle-save-revision')).toBeNull()
    })
  }

  it(`version ${CURRENT_SAVE_VERSION} → ok giữ nguyên save`, () => {
    const raw = writeValidCurrentSave()

    const outcome = loadGame()

    expect(outcome.status).toBe('ok')

    if (outcome.status === 'ok') {
      expect(outcome.save.player.name).toBe('Test')
      expect(outcome.save.version).toBe(CURRENT_SAVE_VERSION)
    }
  })
})

