/** Settings phát sự kiện này để App dừng autosave trước khi xóa save. */
export const SAVE_RESET_REQUEST_EVENT = 'tien-hiep:reset-save-requested'

/**
 * Exact App restore order. Registry drift is rejected before Pinia, active-player,
 * or manager state can mutate; valid saves then restore through the existing owners.
 */
export function restoreGameSession(
  player: GameSessionPlayerOwner,
  gameManager: GameManager,
  save: GameSave,
): RestoreGameSessionResult {
  try {
    gameManager.saveOps.preflightSaveRegistryReferences(save)
  } catch (error: unknown) {
    return {
      status: 'rejected',
      message: error instanceof Error ? error.message : 'Save registry preflight failed',
    }
  }

  const offline = player.restoreFromSave(save)

  gameManager.setActivePlayer(player.$state)

  const equipmentModifiers = gameManager.saveOps.restoreFromSave(save)

  player.setEquipmentModifiers(equipmentModifiers)

  return { status: 'ok', offline }
}

/** Shape persist của một ProductionCycle — khớp core/production. */
export function buildGameSave(player: PlayerData, gameManager: GameManager): GameSave {
  return {
    version: CURRENT_SAVE_VERSION,

    player: {
      // R10 (AR-12): the snapshot must be a VALUE - deep-detach the
      // player (nested baseStats/modifiers/flags alias the live store
      // under a plain spread, so mutating live state after build used
      // to change the "saved" payload).
      //
      // JSON round-trip, NOT structuredClone: the real caller is a Pinia
      // store's reactive state, and structuredClone has no concept of
      // Proxy exotic objects at ANY nesting depth - it throws
      // DataCloneError the moment it meets one, including a nested field
      // Vue only wrapped in a Proxy lazily after some earlier getter/
      // computed touched it during actual gameplay (not reproducible from
      // a freshly-constructed player in isolation - toRaw() alone was not
      // sufficient either, since it only unwraps the outermost proxy).
      // JSON.stringify/parse reads through Proxies transparently via
      // normal property access, at any depth - and this object is going
      // to be JSON.stringify'd again by writeGameSave() for localStorage
      // regardless, so this changes no on-disk behavior.
      ...JSON.parse(JSON.stringify(player)),

      lastSavedAt: Date.now(),
    },

    techniques: gameManager.techniqueManager.getAll(),

    skills: gameManager.skillManager.getAll(),

    materials: gameManager.materialBag.getAll().map((stack) => ({
      materialId: stack.material.id,

      amount: stack.amount,
    })),

    equipment: gameManager.equipmentBag.getAll(),

    pills: gameManager.pillBag.getAll().map((stack) => ({
      pillId: stack.pill.id,

      amount: stack.amount,
    })),

    // Phù/Trận khai tử (§10.1) — bag không còn; mảng rỗng giữ shape save.
    talismans: [],

    formations: [],

    buildings: gameManager.buildingManager.getAll(),

    equipmentSlots: gameManager.equipmentSlotManager.getAll(),

    productionSites: gameManager.productionSystem.getAllStates().map((state) => ({
      siteId: state.siteId,

      level: state.level,

      autoRestart: state.autoRestart,

      activeCycle: state.activeCycle,

      workerCycles: state.workerCycles?.length ? state.workerCycles : undefined,
    })),

    alchemyJobs: gameManager.alchemySystem.getJobs(),

    quests: structuredClone(gameManager.questManager.getState()),

    // R7 (AR-08) - detached decompose snapshot (getSaveState returns a
    // value copy; structuredClone keeps it independent of live state).
    decompose: structuredClone(gameManager.decomposeSystem.getSaveState()),
  }
}

export type SaveWriteResult = { status: 'ok' } | { status: 'failed'; reason: 'quota' | 'unknown' }

export function writeGameSave(save: GameSave): SaveWriteResult {
  try {
    localStorage.setItem(SAVE_KEY, JSON.stringify(save))
    return { status: 'ok' }
  } catch (error: unknown) {
    // QuotaExceededError (DOMException name) — save vượt ~5MB localStorage.
    // Không throw: caller (CloudSaveCoordinator → autosave) quyết định cách
    // báo cho người chơi thay vì chết im lặng giữa tick.
    const name = error instanceof DOMException ? error.name : String(error)
    if (name === 'QuotaExceededError' || name === 'NS_ERROR_DOM_QUOTA_REACHED') {
      return { status: 'failed', reason: 'quota' }
    }
    return { status: 'failed', reason: 'unknown' }
  }
}

// Phase 5 (Reliability, mục XVI) — trước đây version không khớp hoặc
// JSON hỏng đều trả về null giống hệt "chưa từng có save", khiến
// App.vue coi là nhân vật mới và ÂM THẦM ghi đè save cũ ở lần save()
// kế tiếp. Giờ phân biệt rõ 3 trường hợp để App.vue chặn boot, báo
// người chơi, và để họ tự quyết (Export/Xoá) thay vì mất trắng không
// biết vì sao — xem SaveIncompatibleScreen.vue.
export type LoadOutcome =
  | { status: 'empty' }
  | { status: 'ok'; save: GameSave; discardedEquipmentCount: number }
  | { status: 'incompatible'; foundVersion: number | undefined; raw: string }
  | { status: 'corrupted'; raw: string }

export function loadGame(): LoadOutcome {
  const raw = localStorage.getItem(SAVE_KEY)

  if (!raw) {
    return { status: 'empty' }
  }

  let parsed: unknown

  try {
    parsed = JSON.parse(raw)
  } catch {
    return { status: 'corrupted', raw }
  }

  const foundVersion = (parsed as { version?: unknown })?.version

  if (typeof foundVersion !== 'number') {
    return {
      status: 'incompatible',
      foundVersion: undefined,
      raw,
    }
  }

  // Development-phase policy (dong-fu-command-wheel-inventory-spirit-
  // stone-plan.md §"Chính sách migration") — KHÔNG còn auto-migration
  // nào: mọi version cũ hơn CURRENT_SAVE_VERSION trả về 'incompatible'
  // để SaveIncompatibleScreen cho phép Export/Xoá. Điều này bảo đảm
  // không bao giờ có writeGameSave() phát sinh từ loadGame() (trước đây
  // nhánh v42/v43 ghi đè save gốc mà không backup và gắn thẳng version
  // hiện hành dù thiếu field của schema mới).
  if (foundVersion !== CURRENT_SAVE_VERSION) {
    return {
      status: 'incompatible',
      foundVersion,
      raw,
    }
  }

  // save-shape-validation-plan.md §3.4 — version khớp CHƯA đủ: save thiếu
  // array/field bắt buộc (vd player.nodeLevels thời v47) từng gây crash
  // boot hoặc NaN cultivation vĩnh viễn ở restoreFromSave(). Phát hiện
  // có chủ đích tại đây để SaveIncompatibleScreen xử lý (Xuất/Xoá).
  const shape = validateGameSaveShape(parsed)

  if (!shape.ok) {
    console.warn('[SaveSystem] Save đúng version nhưng sai shape:', shape.issues)

    return { status: 'corrupted', raw }
  }

  const importedHandoffRaw = localStorage.getItem(
    IMPORT_DISCARDED_EQUIPMENT_HANDOFF_KEY,
  )
  let importedDiscardedCount = 0

  if (importedHandoffRaw) {
    let importedHandoff: unknown

    try {
      importedHandoff = JSON.parse(importedHandoffRaw)
    } catch {
      importedHandoff = undefined
    }

    if (
      typeof importedHandoff === 'object' &&
      importedHandoff !== null &&
      'normalizedRaw' in importedHandoff &&
      importedHandoff.normalizedRaw === raw &&
      'discardedEquipmentCount' in importedHandoff &&
      Number.isSafeInteger(importedHandoff.discardedEquipmentCount) &&
      typeof importedHandoff.discardedEquipmentCount === 'number' &&
      importedHandoff.discardedEquipmentCount > 0
    ) {
      importedDiscardedCount = importedHandoff.discardedEquipmentCount
    }

    // OPT-06 — removeItem chạy SAU khi đọc + consume xong (trước đây
    // xóa ngay trước khi parse). Chỉ chạm storage khi key thực sự tồn
    // tại; handoff không còn giá trị sử dụng sau load hợp lệ nên vẫn
    // bị xóa kể cả khi marker lệch normalizedRaw (rác). Ý đồ cũ giữ
    // nguyên: mọi đường return trước (parse fail, version, shape) nằm
    // TRƯỚC block này nên handoff còn nguyên cho lần load hợp lệ.
    localStorage.removeItem(IMPORT_DISCARDED_EQUIPMENT_HANDOFF_KEY)
  }

  return {
    status: 'ok',
    // validateGameSaveShape đã kiểm tra boundary và trả bản normalized;
    // cast tập trung duy nhất tại cửa load, không giữ field legacy.
    save: shape.normalizedSave as GameSave,
    discardedEquipmentCount:
      shape.discardedEquipmentCount + importedDiscardedCount,
  }
}

// Sao lưu save hiện có vào BACKUP_KEY — gọi TRƯỚC mọi thao tác có
// thể xoá/ghi đè save chính (deleteSave(), importSaveRaw()), để luôn
// còn 1 bước lùi qua restoreBackup() nếu người chơi bấm nhầm.
export function backupCurrentSave() {
  const raw = localStorage.getItem(SAVE_KEY)

  if (raw) {
    localStorage.setItem(BACKUP_KEY, raw)
  }
}

export function hasBackup(): boolean {
  return localStorage.getItem(BACKUP_KEY) !== null
}

export function getRawSave(): string | null {
  return localStorage.getItem(SAVE_KEY)
}

export function restoreBackup(): boolean {
  const raw = localStorage.getItem(BACKUP_KEY)

  if (!raw) {
    return false
  }

  localStorage.setItem(SAVE_KEY, raw)
  localStorage.removeItem(IMPORT_DISCARDED_EQUIPMENT_HANDOFF_KEY)

  return true
}

export function deleteSave() {
  backupCurrentSave()

  localStorage.removeItem(SAVE_KEY)
  localStorage.removeItem(IMPORT_DISCARDED_EQUIPMENT_HANDOFF_KEY)

  // Xoá cả revision — save đã không còn thì revision cũ là rác, và
  // revision tồn dư khiến lần CAS đầu tiên của nhân vật mới fail.
  localStorage.removeItem(SAVE_REVISION_KEY)
}

// Tải save hiện có (bất kể đọc được hay không) xuống file .json —
// đường thoát an toàn thật sự cho save không tương thích/hỏng, vì
// BACKUP_KEY vẫn nằm trong cùng localStorage nên mất theo nếu người
// dùng xoá site data.
export function exportSaveToFile(raw: string) {
  const blob = new Blob([raw], { type: 'application/json' })
  const url = URL.createObjectURL(blob)

  const link = document.createElement('a')

  link.href = url
  link.download = `tien-hiep-idle-save-${Date.now()}.json`
  link.click()

  URL.revokeObjectURL(url)
}

// Nhập save từ nội dung file .json do người chơi chọn — kiểm tra parse
// được + có field `version`/`player`, và nếu là save ĐÚNG version hiện
// hành thì phải nguyên shape (validateGameSaveShape) mới cho ghi — chặn
// ghi đè save tốt bằng một save hỏng ngay tại cửa nhập. Save version
// KHÁC vẫn được ghi (loadGame() lần reload kế sẽ phân loại 'incompatible'
// và cho Export/Xoá qua SaveIncompatibleScreen — đúng flow recovery hiện
// có). Backup save hiện tại (nếu có) trước khi ghi đè.
export function importSaveRaw(raw: string): boolean {
  let parsed: unknown
  let normalizedRaw = raw
  let discardedEquipmentCount = 0

  try {
    parsed = JSON.parse(raw)
  } catch {
    return false
  }

  if (
    typeof parsed !== 'object' ||
    parsed === null ||
    !('version' in parsed) ||
    !('player' in parsed)
  ) {
    return false
  }

  // Chỉ enforce shape khi đúng version hiện hành — save version khác để
  // loadGame() xử lý 'incompatible' (không chặn đường recovery của user).
  if ((parsed as { version?: unknown }).version === CURRENT_SAVE_VERSION) {
    const shape = validateGameSaveShape(parsed)

    if (!shape.ok) {
      return false
    }

    normalizedRaw = JSON.stringify(shape.normalizedSave)
    discardedEquipmentCount = shape.discardedEquipmentCount
  }

  // Chuẩn bị handoff TRƯỚC khi đụng backup/save chính. Nếu storage không
  // nhận được marker thì import thất bại nguyên vẹn thay vì thay save nhưng
  // làm mất counter. Exact normalizedRaw ràng buộc marker với đúng payload.
  try {
    if (discardedEquipmentCount > 0) {
      localStorage.setItem(
        IMPORT_DISCARDED_EQUIPMENT_HANDOFF_KEY,
        JSON.stringify({ normalizedRaw, discardedEquipmentCount }),
      )
    } else {
      localStorage.removeItem(IMPORT_DISCARDED_EQUIPMENT_HANDOFF_KEY)
    }
  } catch {
    return false
  }

  backupCurrentSave()

  localStorage.setItem(SAVE_KEY, normalizedRaw)

  return true
}

/**
 * R14.6b guard — catalog/preload parity (roadmap R14, A10: "asset
 * resolution/preload enumeration derives from one canonical catalog").
 *
 * What exists already (AssetBundleCatalog.test.ts): catalog descriptors ⊇
 * keys queued by queueCombatAssets(). This file adds the missing direction
 * and the stray-load scan:
 *
 * - Exact key-set equality between queueCombatAssets() and the combat
 *   bundle — a divergence either way means a texture is loaded that the
 *   bundle manager does not know, or catalogued but never ensured for the
 *   transitional preload net.
 * - Every literal `load.*` URL in production source must be enumerated by
 *   some bundle — a hardcoded path that no bundle owns is an untracked load.
 * - Non-literal `load.*` call sites are pinned to the canonical feeders
 *   (queueCombatAssets descriptors, the catalog-driven AssetLoaderScene,
 *   canonical list functions). A new ad-hoc load site fails until it is
 *   routed through the catalog or consciously allowlisted.
 */
import { describe, expect, it } from 'vitest'
import { join } from 'node:path'
import { readTs, srcCorpus, SCAN_TIMEOUT } from './helpers/scanTs'
import { queueCombatAssets } from '@/game/support/CombatPreload'
import {
  enumerateResources,
  getCombatDescriptors,
} from '@/presentation/assets/AssetBundleCatalog'

const GAME_ROOT = process.cwd()
const ALL_BUNDLES = ['core-ui', 'home', 'combat', 'tribulation'] as const

function queuedCombatKeys(): Set<string> {
  const keys = new Set<string>()
  const fakeScene = {
    textures: { exists: () => false },
    load: {
      image: (key: string) => keys.add(key),
      atlas: (key: string) => keys.add(key),
    },
  } as never

  queueCombatAssets(fakeScene)

  return keys
}

describe('R14.6b — combat preload enumeration equals the combat bundle', () => {
  it('queueCombatAssets() and getCombatDescriptors() name the same key set', () => {
    const queued = queuedCombatKeys()
    const catalog = new Set(getCombatDescriptors().map((d) => d.key))

    expect([...queued].filter((k) => !catalog.has(k)), 'queued keys missing from catalog').toEqual([])
    expect([...catalog].filter((k) => !queued.has(k)), 'catalog keys never queued').toEqual([])
  })
})

describe('R14.6b — no stray preload enumeration outside the catalog', () => {
  it('every literal load.* URL belongs to an enumerated bundle', { timeout: SCAN_TIMEOUT }, () => {
    const catalogUrls = new Set<string>()

    for (const d of enumerateResources([...ALL_BUNDLES])) {
      for (const field of ['url', 'textureUrl', 'atlasUrl', 'jsonUrl', 'basePath'] as const) {
        const value = field in d ? (d as Record<string, string | undefined>)[field] : undefined
        if (value !== undefined) {
          catalogUrls.add(value.replace(/^\/+/, ''))
        }
      }
    }

    const corpus = srcCorpus(join(GAME_ROOT, 'src'))
    const loadCall = /\.load\.(?:image|atlas|spritesheet|multiatlas|audio|json)\s*\(([^)]*)\)/g
    const literalArg = /'([^']+)'|"([^"]+)"/g

    for (const file of corpus) {
      for (const call of file.text.matchAll(loadCall)) {
        for (const literal of call[1]!.matchAll(literalArg)) {
          const value = (literal[1] ?? literal[2]!).replace(/^\/+/, '')

          if (!value.includes('/')) {
            continue
          }

          expect(
            catalogUrls.has(value),
            `${file.fromSrc}: literal load URL "${value}" is not enumerated by any asset bundle`,
          ).toBe(true)
        }
      }
    }
  })

  it('non-literal load.* call sites are confined to canonical feeders', { timeout: SCAN_TIMEOUT }, () => {
    const corpus = srcCorpus(join(GAME_ROOT, 'src'))
    const loadCall = /\.load\.(?:image|atlas|spritesheet|multiatlas|audio|json)\s*\(([^)]*)\)/g

    // Files whose load.* calls are fed by canonical enumerations:
    // - CombatPreload: the transitional net, descriptor-fed (queueOnce).
    // - AssetLoaderScene: the catalog-driven loader itself.
    // - InkWashUiPhaser: atlas loader fed by its own exported URL constants.
    // - CombatScene: Thanh Van variant swap — args come from
    //   thanhVanLoadList(variant), the same source the catalog enumerates.
    // - TranPhapCombatPreviewScene: PLACEHOLDER_* constants declared by the
    //   combat presentation catalogue (enumerated in the combat bundle).
    // - TribulationScene: literal 'assets/cultivate.json' — in the
    //   tribulation bundle (checked by the literal-url test above).
    const allowedFeeders = new Set([
      'game/support/CombatPreload.ts',
      'game/scenes/AssetLoaderScene.ts',
      'game/support/InkWashUiPhaser.ts',
      'game/scenes/CombatScene.ts',
      'game/scenes/TranPhapCombatPreviewScene.ts',
      'game/scenes/TribulationScene.ts',
    ])

    for (const file of corpus) {
      for (const call of file.text.matchAll(loadCall)) {
        const args = call[1]!
        const hasLiteralPath = /'[^']*\/[^']*'|"[^"]*\/[^"]*"/.test(args)

        if (hasLiteralPath) {
          continue // covered by the literal-url test
        }

        expect(
          allowedFeeders.has(file.fromSrc),
          `${file.fromSrc}: dynamic load call ${call[0].slice(0, 60)}… is not a canonical feeder — route it through the asset catalog or add a reviewed exception`,
        ).toBe(true)
      }
    }
  })
})

import { expect, test } from '@playwright/test'

import { bootToGuestHome } from './helpers'

/**
 * UI/UX QA remediation (Task 10, 2026-09-07) — reduced motion: với
 * `prefers-reduced-motion: reduce`, các animation CSS chính (loading
 * pulse, game-button spinner, realm aura, menu glow) phải đứng yên
 * (animation-duration ~0 / không chạy). Kiểm tra qua getComputedStyle.
 */
test.describe('Reduced motion', () => {
  test('animations disabled under prefers-reduced-motion: reduce', async ({ page }) => {
    await page.emulateMedia({ reducedMotion: 'reduce' })

    await page.goto('/')

    // LoadingScreen pulse (hiện trong intro — trước auth).
    const pulse = page.locator('.loading-screen__pulse')
    const pulseVisible = await pulse.isVisible({ timeout: 5_000 }).catch(() => false)

    if (pulseVisible) {
      const animationName = await pulse.evaluate((el) => getComputedStyle(el).animationName)
      expect(animationName, 'loading pulse phải tắt animation khi reduce').toBe('none')
    }

    // Auth screen vẫn hiện bình thường (không bị reduced-motion chặn).
    await expect(page.getByTestId('auth-screen')).toBeVisible({ timeout: 15_000 })
  })
})

/**
 * B2 balance sweep (2026-09-14) — real-engine feasibility check for all
 * 30 chapter floors. For each stage, builds a player the unlock gate
 * allows and runs the real TurnBattleSystem. Prints a per-floor table:
 * outcome, rounds, player HP remaining, player/enemy stat lines.
 * Analysis artifact, not a CI assertion — numbers feed
 * docs/qa/2026-09-14-beta-b2-balance.md.
 *
 * Two player models per floor:
 *  - NAKED: min-path attribute points (12+12 prior realms, floor-1 in
 *    realm), 50/50 vit/str, starter skill only. The floor of what a
 *    gate-legal player can be.
 *  - GEARED: same + full 6-slot equipment, each slot = best quality of
 *    20 real rolls (a player who farmed the floor a handful of times),
 *    unenhanced. The intended-power sanity bar.
 */
import { describe, it } from 'vitest'
import { createLab, type Lab } from './harness'
import { STAGES } from '@/data/stage/Stages'
import { ITEM_QUALITY_ORDER } from '@/core/item/ItemQuality'
import type { Stage } from '@/core/stage/Stage'

const REALM_PRIOR_MIN_LEVELS: Record<string, number> = {
  mortal: 0,
  qi_refining: 12,
  foundation_establishment: 24,
}

const REALM_ORDER: Record<string, number> = { mortal: 0, qi_refining: 1, foundation_establishment: 2 }

const SLOT_TEMPLATES: Record<string, string> = {
  weapon: 'base_kiem',
  helmet: 'base_quan',
  armor: 'base_bao',
  boots: 'base_hai',
  ring: 'base_gioi',
  necklace: 'base_truy',
}

const COMBAT_CAP_SECONDS = 900
const GEAR_ROLLS_PER_SLOT = 20

interface SimResult {
  state: string
  rounds: number | string
  hpPct: number
  playerLine: string
  enemyLine: string
}

function runFloor(lab: Lab, stage: Stage, floor: number): SimResult {
  const stats = lab.stats()
  const started = lab.manager.turnBattleOps.startStage(lab.player, stats, stage, false)
  if (!started) {
    return { state: 'START-FAILED', rounds: '?', hpPct: 0, playerLine: '', enemyLine: '' }
  }

  lab.combat(COMBAT_CAP_SECONDS)
  const battle = lab.manager.getTurnBattle()
  const me = battle?.players[0]
  const foe = battle?.enemies[0]
  return {
    state: battle?.state ?? '?',
    rounds: battle?.roundsElapsed ?? '?',
    hpPct: me ? Math.round((me.entity.currentHp / me.entity.maxHp) * 100) : 0,
    playerLine: `hp=${stats.maxHp} atk=${stats.attack.toFixed(1)} def=${stats.defense.toFixed(1)} spd=${stats.speed.toFixed(1)}`,
    enemyLine: `hp=${foe?.entity.maxHp ?? '?'} atk=${foe?.entity.stats.attack ?? '?'} def=${foe?.entity.stats.defense ?? '?'} spd=${foe?.entity.stats.speed ?? '?'}`,
  }
}

function buildPlayer(lab: Lab, realmId: string, floor: number, geared: boolean, stageList: Stage[], stageIndex: number): void {
  lab.cheat.setRealm(realmId, floor)
  lab.player.cultivationPath = 'phap_tu'
  lab.player.attributePoints = (REALM_PRIOR_MIN_LEVELS[realmId] ?? 0) + Math.max(0, floor - 1)
  lab.player.completedStageIds.push(...stageList.slice(0, stageIndex).map((s) => s.id))

  let wantVit = true
  while (lab.player.attributePoints > 0) {
    const primary = wantVit ? 'vitality' : 'strength'
    if (!lab.manager.progressionOps.allocateAttributePoint(lab.player, primary)) {
      if (!lab.manager.progressionOps.allocateAttributePoint(lab.player, wantVit ? 'strength' : 'vitality')) break
    }
    wantVit = !wantVit
  }

  if (realmId !== 'mortal') {
    lab.manager.progressionOps.learnSkill('hoa_cau_thuat')
    lab.manager.skillSystem.equipToSlot('hoa_cau_thuat', 0)
  }

  if (!geared) return

  for (const templateId of Object.values(SLOT_TEMPLATES)) {
    let bestId: string | null = null
    let bestQuality = -1
    for (let i = 0; i < GEAR_ROLLS_PER_SLOT; i++) {
      const grant = lab.cheat.addEquipment(templateId)
      const qualityIndex = ITEM_QUALITY_ORDER.indexOf(grant.instance.quality)
      if (qualityIndex > bestQuality) {
        bestQuality = qualityIndex
        bestId = grant.instance.instanceId
      }
    }
    if (bestId) {
      lab.manager.equipmentOps.equipItem(bestId, lab.player)
    }
  }

  // Equipment modifiers are static — the store layer mirrors
  // equipmentOps.getEquipmentModifiers() into player.modifiers after
  // each equip; the lab has no store so we do the same sync here.
  lab.player.modifiers = lab.manager.equipmentOps.getEquipmentModifiers()
}

describe('balance sweep — all chapter floors vs player models', () => {
  it('prints the per-floor feasibility table', () => {
    const stageList: Stage[] = STAGES.slice().sort(
      (a, b) =>
        (REALM_ORDER[a.requiredRealmId ?? 'mortal'] ?? 0) -
          (REALM_ORDER[b.requiredRealmId ?? 'mortal'] ?? 0) || a.floor - b.floor,
    )

    const rows: string[] = []

    for (const stage of stageList) {
      const realmId = stage.requiredRealmId ?? 'mortal'
      const floor = stage.requiredRealmLevel ?? stage.floor ?? 1
      const stageIndex = stageList.indexOf(stage)

      for (const geared of [false, true]) {
        const lab = createLab()
        lab.useRealData()
        buildPlayer(lab, realmId, floor, geared, stageList, stageIndex)
        const r = runFloor(lab, stage, floor)
        rows.push(
          `${stage.id}\tF${floor}\t${geared ? 'GEARED' : 'NAKED '}\t${r.state}\trounds=${r.rounds}\thp=${r.hpPct}%` +
            `\t| P ${r.playerLine}\t| E ${r.enemyLine}`,
        )
      }
    }

    console.log('\n=== BALANCE SWEEP ===\n' + rows.join('\n'))
  }, 600_000)
})
